{"command":"cd /workspace && cat > src/node.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"

	yaml "yq/third_party/yaml"
)

type Kind uint32

const (
	SequenceNode Kind = 1 << iota
	MappingNode
	ScalarNode
	AliasNode
)

type Style = yaml.Style

const (
	TaggedStyle       = yaml.TaggedStyle
	DoubleQuotedStyle = yaml.DoubleQuotedStyle
	SingleQuotedStyle = yaml.SingleQuotedStyle
	LiteralStyle      = yaml.LiteralStyle
	FoldedStyle       = yaml.FoldedStyle
	FlowStyle         = yaml.FlowStyle
)

type CandidateNode struct {
	Kind    Kind
	Style   Style
	Tag     string
	Value   string
	Anchor  string
	Alias   *CandidateNode
	Content []*CandidateNode

	HeadComment string
	LineComment string
	FootComment string

	Parent *CandidateNode
	Key    *CandidateNode

	LeadingContent string

	document  uint
	filename  string
	fileIndex int

	Line   int
	Column int

	EvaluateTogether bool
	IsMapKey         bool
}

func (n *CandidateNode) GetDocument() uint {
	if n.Parent == nil {
		return n.document
	}
	return n.Parent.GetDocument()
}

func (n *CandidateNode) SetDocument(idx uint) { n.document = idx }

func (n *CandidateNode) GetFilename() string {
	if n.Parent == nil {
		return n.filename
	}
	return n.Parent.GetFilename()
}

func (n *CandidateNode) SetFilename(f string) { n.filename = f }

func (n *CandidateNode) GetFileIndex() int {
	if n.Parent == nil {
		return n.fileIndex
	}
	return n.Parent.GetFileIndex()
}

func (n *CandidateNode) SetFileIndex(i int) { n.fileIndex = i }

func (n *CandidateNode) GetKey() string {
	keyPrefix := ""
	if n.IsMapKey {
		keyPrefix = fmt.Sprintf("key-%v-", n.Value)
	}
	key := ""
	if n.Key != nil {
		key = n.Key.Value
	}
	return fmt.Sprintf("%v%v - %v", keyPrefix, n.GetDocument(), key)
}

func (n *CandidateNode) GetNicePath() string {
	var sb strings.Builder
	path := n.GetPath()
	for i, element := range path {
		elementStr := fmt.Sprintf("%v", element)
		switch element.(type) {
		case int:
			sb.WriteString("[" + elementStr + "]")
		default:
			s, _ := element.(string)
			if strings.ContainsAny(s, ". ") || strings.ContainsAny(s, "[]") {
				sb.WriteString("[" + elementStr + "]")
			} else if i == 0 {
				sb.WriteString(elementStr)
			} else {
				sb.WriteString("." + elementStr)
			}
		}
	}
	return sb.String()
}

func (n *CandidateNode) GetPath() []interface{} {
	result := n.getParsedKey()
	if n.Parent != nil {
		return append(n.Parent.GetPath(), result...)
	}
	return result
}

func (n *CandidateNode) getParsedKey() []interface{} {
	if n.IsMapKey {
		return []interface{}{}
	}
	if n.Key == nil {
		return []interface{}{}
	}
	if n.Parent != nil && n.Parent.Kind == SequenceNode {
		index, err := strconv.Atoi(n.Key.Value)
		if err != nil {
			return []interface{}{n.Key.Value}
		}
		return []interface{}{index}
	}
	return []interface{}{n.Key.Value}
}

func (n *CandidateNode) unwrapDocument() *CandidateNode { return n }

func createScalarNode(value interface{}, stringValue string) *CandidateNode {
	node := &CandidateNode{Kind: ScalarNode}
	node.Value = stringValue
	switch value.(type) {
	case float32, float64:
		node.Tag = "!!float"
	case int, int64, int32:
		node.Tag = "!!int"
	case bool:
		node.Tag = "!!bool"
	case string:
		node.Tag = "!!str"
	case nil:
		node.Tag = "!!null"
	}
	return node
}

func createStringScalar(s string) *CandidateNode {
	return &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: s}
}

func createIntScalar(i int64) *CandidateNode {
	return &CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: fmt.Sprintf("%v", i)}
}

func createBoolScalar(b bool) *CandidateNode {
	return &CandidateNode{Kind: ScalarNode, Tag: "!!bool", Value: fmt.Sprintf("%v", b)}
}

func createNullScalar() *CandidateNode {
	return &CandidateNode{Kind: ScalarNode, Tag: "!!null", Value: "null"}
}

func (n *CandidateNode) CreateChild() *CandidateNode {
	return &CandidateNode{Parent: n}
}

func (n *CandidateNode) CreateReplacement(kind Kind, tag string, value string) *CandidateNode {
	node := &CandidateNode{Kind: kind, Tag: tag, Value: value}
	return n.CopyAsReplacement(node)
}

func (n *CandidateNode) CopyAsReplacement(replacement *CandidateNode) *CandidateNode {
	newCopy := replacement.Copy()
	newCopy.Parent = n.Parent
	if n.IsMapKey {
		newCopy.Key = n
	} else {
		newCopy.Key = n.Key
	}
	newCopy.document = n.document
	newCopy.filename = n.filename
	newCopy.fileIndex = n.fileIndex
	return newCopy
}

func (n *CandidateNode) CreateReplacementWithComments(kind Kind, tag string, style Style) *CandidateNode {
	replacement := n.CreateReplacement(kind, tag, "")
	replacement.LeadingContent = n.LeadingContent
	replacement.HeadComment = n.HeadComment
	replacement.LineComment = n.LineComment
	replacement.FootComment = n.FootComment
	replacement.Style = style
	return replacement
}

func (n *CandidateNode) IsNull() bool {
	return n.Kind == ScalarNode && n.Tag == "!!null"
}

// AddKeyValueChild adds a key/value pair to a mapping node, copying both
func (n *CandidateNode) AddKeyValueChild(rawKey *CandidateNode, rawValue *CandidateNode) (*CandidateNode, *CandidateNode) {
	key := rawKey.Copy()
	key.SetParent(n)
	key.IsMapKey = true

	value := rawValue.Copy()
	value.SetParent(n)
	value.IsMapKey = false
	value.Key = key

	n.Content = append(n.Content, key, value)
	return key, value
}

func (n *CandidateNode) AddChild(rawChild *CandidateNode) {
	value := rawChild.Copy()
	value.SetParent(n)
	value.IsMapKey = false
	index := len(n.Content)
	keyNode := createScalarNode(index, fmt.Sprintf("%v", index))
	keyNode.SetParent(n)
	value.Key = keyNode
	n.Content = append(n.Content, value)
}

func (n *CandidateNode) AddChildren(children []*CandidateNode) {
	if n.Kind == MappingNode {
		for i := 0; i+1 < len(children); i += 2 {
			n.AddKeyValueChild(children[i], children[i+1])
		}
	} else {
		for _, c := range children {
			n.AddChild(c)
		}
	}
}

func (n *CandidateNode) SetParent(parent *CandidateNode) {
	n.Parent = parent
}

func (n *CandidateNode) GetValueRep() (interface{}, error) {
	realTag := n.guessTagFromCustomType()
	switch realTag {
	case "!!int":
		_, val, err := parseInt64(n.Value)
		return val, err
	case "!!float":
		return strconv.ParseFloat(strings.ReplaceAll(n.Value, "_", ""), 64)
	case "!!bool":
		return isTruthyNode(n), nil
	case "!!null":
		return nil, nil
	}
	return n.Value, nil
}

func (n *CandidateNode) guessTagFromCustomType() string {
	if strings.HasPrefix(n.Tag, "!!") {
		return n.Tag
	} else if n.Value == "" {
		return n.Tag
	}
	dataBucket, errorReading := parseSnippet(n.Value)
	if errorReading != nil {
		return n.Tag
	}
	return dataBucket.Tag
}

func (n *CandidateNode) GetNiceTag() string {
	return n.unwrapDocument().Tag
}

// Copy does a deep copy
func (n *CandidateNode) Copy() *CandidateNode {
	return n.doCopy(true)
}

func (n *CandidateNode) CopyWithoutContent() *CandidateNode {
	return n.doCopy(false)
}

func (n *CandidateNode) doCopy(cloneContent bool) *CandidateNode {
	var content []*CandidateNode
	var copyKey *CandidateNode
	if n.Key != nil {
		copyKey = n.Key.Copy()
	}
	clone := &CandidateNode{
		Kind:             n.Kind,
		Style:            n.Style,
		Tag:              n.Tag,
		Value:            n.Value,
		Anchor:           n.Anchor,
		Alias:            n.Alias,
		HeadComment:      n.HeadComment,
		LineComment:      n.LineComment,
		FootComment:      n.FootComment,
		Parent:           n.Parent,
		Key:              copyKey,
		LeadingContent:   n.LeadingContent,
		document:         n.document,
		filename:         n.filename,
		fileIndex:        n.fileIndex,
		Line:             n.Line,
		Column:           n.Column,
		EvaluateTogether: n.EvaluateTogether,
		IsMapKey:         n.IsMapKey,
	}
	if cloneContent {
		content = make([]*CandidateNode, len(n.Content))
		for i, c := range n.Content {
			cc := c.Copy()
			cc.Parent = clone
			content[i] = cc
		}
		// fix up keys of values in maps
		if n.Kind == MappingNode {
			for i := 0; i+1 < len(content); i += 2 {
				content[i+1].Key = content[i]
			}
		}
	}
	clone.Content = content
	return clone
}

// UpdateFrom updates this node from another, used for assignment
func (n *CandidateNode) UpdateFrom(other *CandidateNode, prefs assignPreferences) {
	if n == other {
		return
	}
	// if this is an empty map or empty array, use the style of other node.
	if (n.Kind != ScalarNode && len(n.Content) == 0) ||
		// if the tag is the same or empty, use the style of other node.
		(n.Kind == ScalarNode && other.Kind == ScalarNode && (n.Tag == other.Tag || n.Tag == "!!null")) {
		n.Style = other.Style
	}

	n.UpdateAttributesFrom(other, prefs)

	// handle content
	content := make([]*CandidateNode, len(other.Content))
	for i, c := range other.Content {
		cc := c.Copy()
		cc.Parent = n
		content[i] = cc
	}
	if other.Kind == MappingNode {
		for i := 0; i+1 < len(content); i += 2 {
			content[i+1].Key = content[i]
		}
	} else if other.Kind == SequenceNode {
		for i, c := range content {
			c.Key = createScalarNode(i, fmt.Sprintf("%v", i))
		}
	}
	n.Content = content
	n.Kind = other.Kind
	n.Value = other.Value
	n.Alias = other.Alias
}

func (n *CandidateNode) UpdateAttributesFrom(other *CandidateNode, prefs assignPreferences) {
	if n.Kind != other.Kind {
		// clear out the contents when switching to a different type
		// e.g. map to array
		n.Content = make([]*CandidateNode, 0)
		n.Value = ""
	}
	n.Kind = other.Kind

	// don't clobber custom tags...
	if prefs.ClobberCustomTags || strings.HasPrefix(n.Tag, "!!") || n.Tag == "" {
		n.Tag = other.Tag
	}

	n.Alias = other.Alias

	if !prefs.DontOverWriteAnchor {
		n.Anchor = other.Anchor
	}

	// merge will pickup the style of the new thing
	// when autocreating nodes
	if n.Style == 0 {
		n.Style = other.Style
	}

	if other.FootComment != "" {
		n.FootComment = other.FootComment
	}
	if other.HeadComment != "" {
		n.HeadComment = other.HeadComment
	}
	if other.LineComment != "" {
		n.LineComment = other.LineComment
	}
}
EOF
echo done"}

