	yaml "yq/third_party/yaml"
)

const docSeparatorPlaceholder = "$yqDocSeparator$"

type YamlPreferences struct {
	Indent                      int
	ColorsEnabled               bool
	LeadingContentPreProcessing bool
	PrintDocSeparators          bool
	UnwrapScalar                bool
	EvaluateTogether            bool
