type yamlDecoder struct {
	decoder        *yaml.Decoder
	prefs          YamlPreferences
	leadingContent string
	readAnything   bool
	firstFile      bool
	documentIndex  uint
}

func NewYamlDecoder(prefs YamlPreferences) Decoder {
	return &yamlDecoder{prefs: prefs, firstFile: true}
