var commentLineRegEx = regexp.MustCompile(`^\s*#`)
var yamlDirectiveLineRegEx = regexp.MustCompile(`^\s*%YA`)

func processReadStream(reader *bufio.Reader) (*bufio.Reader, string, error) {
	var sb strings.Builder
	for {
		peekBytes, err := reader.Peek(4)
		if errors.Is(err, io.EOF) {
			return reader, sb.String(), nil
		} else if err != nil {
			return reader, sb.String(), err
		}
		peek := string(peekBytes)
		if peekBytes[0] == '\n' {
			_, _ = reader.ReadString('\n')
			sb.WriteString("\n")
		} else if peek == "--- " {
			line, rerr := reader.ReadString('\n')
			sb.WriteString(docSeparatorPlaceholder + "\n")
			rest := strings.TrimSpace(strings.TrimSuffix(line[4:], "\n"))
			remaining, _ := io.ReadAll(reader)
			_ = rerr
			reader = bufio.NewReader(io.MultiReader(strings.NewReader(rest), bytes.NewReader(remaining)))
		} else if peek == "---\n" {
			_, _ = reader.ReadString('\n')
			sb.WriteString(docSeparatorPlaceholder + "\n")
		} else if commentLineRegEx.MatchString(peek) {
			line, _ := reader.ReadString('\n')
			sb.WriteString(line)
		} else if yamlDirectiveLineRegEx.MatchString(peek) {
			line, _ := reader.ReadString('\n')
			sb.WriteString(line)
		} else {
			return reader, sb.String(), nil
		}
	}
}

func (dec *yamlDecoder) Init(reader io.Reader) error {
	readerToUse := reader
	leadingContent := ""
	var err error
	if dec.prefs.LeadingContentPreProcessing {
		var br *bufio.Reader
		br, leadingContent, err = processReadStream(bufio.NewReader(reader))
		if err != nil {
			return err
		}
		readerToUse = br
	}
	dec.leadingContent = leadingContent
	dec.readAnything = false
	dec.decoder = yaml.NewDecoder(readerToUse)
	dec.firstFile = false
	dec.documentIndex = 0
	return nil
}

func (dec *yamlDecoder) Decode() (*CandidateNode, error) {
	var yamlNode yaml.Node
	err := dec.decoder.Decode(&yamlNode)
	if errors.Is(err, io.EOF) && dec.leadingContent != "" && !dec.readAnything {
		dec.readAnything = true
		return dec.blankNodeWithComment(), nil
	} else if err != nil {
		return nil, err
	}

	candidateNode := yamlDocToCandidate(&yamlNode)
	candidateNode.document = dec.documentIndex
	if dec.leadingContent != "" {
		candidateNode.LeadingContent = dec.leadingContent
		dec.leadingContent = ""
	}
	dec.readAnything = true
	dec.documentIndex++
	return candidateNode, nil
}

func (dec *yamlDecoder) blankNodeWithComment() *CandidateNode {
	node := createScalarNode(nil, "")
	node.LeadingContent = dec.leadingContent
	return node
