func yamlDocToCandidate(doc *yaml.Node) *CandidateNode {
	anchorMap := map[*yaml.Node]*CandidateNode{}
	if doc.Kind == yaml.DocumentNode {
		var c *CandidateNode
		if len(doc.Content) == 0 {
			c = createScalarNode(nil, "")
		} else {
			c = yamlToCandidate(doc.Content[0], anchorMap)
		}
		c.HeadComment = doc.HeadComment + c.HeadComment
		c.FootComment = doc.FootComment + c.FootComment
		if doc.LineComment != "" {
			c.LineComment = doc.LineComment + c.LineComment
		}
		return c
	}
	return yamlToCandidate(doc, anchorMap)
}

func yamlToCandidate(n *yaml.Node, anchorMap map[*yaml.Node]*CandidateNode) *CandidateNode {
	c := &CandidateNode{
		Style:       n.Style,
		Tag:         n.Tag,
		Value:       n.Value,
		Anchor:      n.Anchor,
		HeadComment: n.HeadComment,
		LineComment: n.LineComment,
		FootComment: n.FootComment,
		Line:        n.Line,
		Column:      n.Column,
	}
	anchorMap[n] = c
	switch n.Kind {
	case yaml.DocumentNode:
		return yamlDocToCandidate(n)
	case yaml.SequenceNode:
		c.Kind = SequenceNode
		for i, child := range n.Content {
			cc := yamlToCandidate(child, anchorMap)
			cc.Parent = c
			cc.Key = createIntScalar(int64(i))
			cc.Key.Parent = c
			c.Content = append(c.Content, cc)
		}
	case yaml.MappingNode:
		c.Kind = MappingNode
		for i := 0; i+1 < len(n.Content); i += 2 {
			k := yamlToCandidate(n.Content[i], anchorMap)
			k.Parent = c
			k.IsMapKey = true
			v := yamlToCandidate(n.Content[i+1], anchorMap)
			v.Parent = c
			v.Key = k
			c.Content = append(c.Content, k, v)
		}
	case yaml.ScalarNode:
		c.Kind = ScalarNode
	case yaml.AliasNode:
		c.Kind = AliasNode
		if n.Alias != nil {
			if target, ok := anchorMap[n.Alias]; ok {
				c.Alias = target
			} else {
				c.Alias = yamlToCandidate(n.Alias, anchorMap)
			}
		}
	}
	return c
