func candidateToYaml(n *CandidateNode) *yaml.Node {
	anchorMap := map[*CandidateNode]*yaml.Node{}
	return candidateToYamlRec(n, anchorMap)
}

func candidateToYamlRec(n *CandidateNode, anchorMap map[*CandidateNode]*yaml.Node) *yaml.Node {
	y := &yaml.Node{
		Style:       n.Style,
		Tag:         n.Tag,
		Value:       n.Value,
		Anchor:      n.Anchor,
		HeadComment: n.HeadComment,
		LineComment: n.LineComment,
		FootComment: n.FootComment,
		Line:        n.Line,
		Column:      n.Column,
	}
	anchorMap[n] = y
	switch n.Kind {
	case SequenceNode:
		y.Kind = yaml.SequenceNode
	case MappingNode:
		y.Kind = yaml.MappingNode
	case ScalarNode:
		y.Kind = yaml.ScalarNode
	case AliasNode:
		y.Kind = yaml.AliasNode
		if n.Alias != nil {
			if t, ok := anchorMap[n.Alias]; ok {
				y.Alias = t
			} else {
				y.Alias = &yaml.Node{Kind: yaml.ScalarNode, Anchor: n.Value, Value: n.Value}
			}
		}
	default:
		y.Kind = yaml.ScalarNode
	}
	for _, c := range n.Content {
		y.Content = append(y.Content, candidateToYamlRec(c, anchorMap))
	}
	return y
}

type yamlEncoder struct {
	prefs YamlPreferences
}

func NewYamlEncoder(prefs YamlPreferences) Encoder {
	return &yamlEncoder{prefs: prefs}
}

func (ye *yamlEncoder) CanHandleAliases() bool { return true }

func (ye *yamlEncoder) PrintDocumentSeparator(writer io.Writer) error {
	if ye.prefs.PrintDocSeparators {
		return writeString(writer, "---\n")
	}
	return nil
}

func (ye *yamlEncoder) PrintLeadingContent(writer io.Writer, content string) error {
	reader := bufio.NewReader(strings.NewReader(content))
	for {
		readline, errReading := reader.ReadString('\n')
		if errReading != nil && !errors.Is(errReading, io.EOF) {
			return errReading
		}
		if strings.Contains(readline, docSeparatorPlaceholder) {
			if err := ye.PrintDocumentSeparator(writer); err != nil {
				return err
			}
		} else {
			if len(readline) > 0 && readline != "\n" && readline[0] != '%' && !commentLineRegEx.MatchString(readline) {
				readline = "# " + readline
			}
			if ye.prefs.ColorsEnabled && strings.TrimSpace(readline) != "" {
				readline = colorComment(readline)
			}
			if err := writeString(writer, readline); err != nil {
				return err
			}
		}
		if errors.Is(errReading, io.EOF) {
			if readline != "" {
				if err := writeString(writer, "\n"); err != nil {
					return err
				}
			}
			break
		}
	}
	return nil
}

func (ye *yamlEncoder) Encode(writer io.Writer, node *CandidateNode) error {
	if node.Kind == ScalarNode && ye.prefs.UnwrapScalar {
		valueToPrint := node.Value
		if node.LeadingContent == "" || valueToPrint != "" {
			valueToPrint = valueToPrint + "\n"
		}
		return writeString(writer, valueToPrint)
	}

	destination := writer
	tempBuffer := bytes.NewBuffer(nil)
	if ye.prefs.ColorsEnabled {
		destination = tempBuffer
	}

	var encoder = yaml.NewEncoder(destination)
	encoder.SetIndent(ye.prefs.Indent)
	if ye.prefs.CompactSequenceIndent {
		encoder.CompactSeqIndent()
	}

	target := candidateToYaml(node)
	trailingContent := target.FootComment
	target.FootComment = ""

	if err := encoder.Encode(target); err != nil {
		return err
	}
	if err := encoder.Close(); err != nil {
		return err
	}
	if err := ye.PrintLeadingContent(destination, trailingContent); err != nil {
		return err
	}
	if ye.prefs.ColorsEnabled {
		return colorizeAndPrint(tempBuffer.Bytes(), writer)
	}
	return nil
}

func writeString(writer io.Writer, txt string) error {
	_, err := writer.Write([]byte(txt))
	return err
}
