package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

type tokenType uint32

const (
	operationToken tokenType = 1 << iota
	openBracket
	closeBracket
	openCollect
	closeCollect
	openCollectObject
	closeCollectObject
	traverseArrayCollect
)

type token struct {
	TokenType            tokenType
	Operation            *Operation
	AssignOperation      *Operation
	CheckForPostTraverse bool
	Match                string
	Optional             bool
}

func (t *token) toString() string {
	switch t.TokenType {
	case operationToken:
		return t.Operation.StringValue
	case openBracket:
		return "("
	case closeBracket:
		return ")"
	case openCollect:
		return "["
	case closeCollect:
		return "]"
	case openCollectObject:
		return "{"
	case closeCollectObject:
		return "}"
	case traverseArrayCollect:
		return ".["
	}
	return "NFI"
}

type lexAction func(match string) (*token, error)

type lexRule struct {
	re     *regexp.Regexp
	action lexAction // nil == skip
}

var lexRules []*lexRule

func addRule(pattern string, action lexAction) {
	lexRules = append(lexRules, &lexRule{re: regexp.MustCompile(`^(?:` + pattern + `)`), action: action})
}

func literalToken(tt tokenType, checkForPost bool) lexAction {
	return func(match string) (*token, error) {
		t := &token{TokenType: tt, CheckForPostTraverse: checkForPost, Match: match}
		if tt == closeCollect && strings.HasSuffix(match, "?") {
			t.Optional = true
		}
		return t, nil
	}
}

func opTokenWithPrefs(opType *operationType, assignOpType *operationType, prefs interface{}) lexAction {
	return func(match string) (*token, error) {
		op := &Operation{OperationType: opType, Value: opType.Type, StringValue: match, Preferences: prefs}
		var assign *Operation
		if assignOpType != nil {
			assign = &Operation{OperationType: assignOpType, Value: assignOpType.Type, StringValue: match, Preferences: prefs}
		}
		return &token{TokenType: operationToken, Operation: op, AssignOperation: assign, CheckForPostTraverse: opType.CheckForPostTraverse, Match: match}, nil
	}
}

func opToken(opType *operationType) lexAction {
	return opTokenWithPrefs(opType, nil, nil)
}

func simpleOp(pattern string, opType *operationType) {
	addRule(pattern, opToken(opType))
}

func assignableOp(pattern string, opType *operationType, assignType *operationType, prefs interface{}) {
	addRule(pattern, opTokenWithPrefs(opType, assignType, prefs))
}

func valueToken(node *CandidateNode, match string) *token {
	op := &Operation{OperationType: valueOpType, Value: node.Value, StringValue: match, CandidateNode: node}
	return &token{TokenType: operationToken, Operation: op, Match: match}
}

func numberAction(match string) (*token, error) {
	var v string = match
	isFloat := strings.ContainsAny(match, ".eE") && !strings.HasPrefix(strings.TrimPrefix(match, "-"), "0x") && !strings.HasPrefix(strings.TrimPrefix(match, "-"), "0X")
	if isFloat {
		if _, err := strconv.ParseFloat(v, 64); err != nil {
			return nil, err
		}
		return valueToken(&CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: v}, match), nil
	}
	if _, _, err := parseInt64(v); err != nil {
		return nil, err
	}
	return valueToken(&CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: v}, match), nil
}

func stringAction(match string) (*token, error) {
	inner := match[1 : len(match)-1]
	value := unescapeString(inner)
	node := &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: value}
	if ConfiguredStringInterpolation && strings.Contains(inner, "\\(") {
		op := &Operation{OperationType: stringInterpolationOpType, Value: value, StringValue: match, CandidateNode: node, Preferences: inner}
		return &token{TokenType: operationToken, Operation: op, Match: match}, nil
	}
	return valueToken(node, match), nil
}

func unescapeString(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			n := s[i+1]
			switch n {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'v':
				sb.WriteByte('\v')
			case 'a':
				sb.WriteByte('\a')
			default:
				sb.WriteByte('\\')
				sb.WriteByte(n)
			}
			i++
			continue
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

func pathAction(match string) (*token, error) {
	value := match[1:]
	optional := false
	if strings.HasSuffix(value, "?") {
		optional = true
		value = value[:len(value)-1]
	}
	if len(value) >= 2 && strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"") {
		value = value[1 : len(value)-1]
	}
	op := &Operation{OperationType: traversePathOpType, Value: value, StringValue: value, Preferences: traversePreferences{OptionalTraverse: optional}}
	return &token{TokenType: operationToken, Operation: op, CheckForPostTraverse: true, Match: match}, nil
}

