func assignOpTokenAction(updateAssign bool) lexAction {
	return func(match string) (*token, error) {
		prefs := assignPreferences{DontOverWriteAnchor: true}
		if strings.HasSuffix(match, "c") {
			prefs.ClobberCustomTags = true
		}
		op := &Operation{OperationType: assignOpType, Value: assignOpType.Type, StringValue: match, UpdateAssign: updateAssign, Preferences: prefs}
		return &token{TokenType: operationToken, Operation: op, Match: match}, nil
	}
}

func multiplyPrefsFromString(options string) multiplyPreferences {
	prefs := multiplyPreferences{}
	prefs.AssignPrefs = assignPreferences{}
	if strings.Contains(options, "+") {
		prefs.AppendArrays = true
	}
	if strings.Contains(options, "?") {
		prefs.TraversePrefs = traversePreferences{DontAutoCreate: true}
	}
	if strings.Contains(options, "n") {
		prefs.AssignPrefs.OnlyWriteNull = true
	}
	if strings.Contains(options, "d") {
		prefs.DeepMergeArrays = true
	}
	if strings.Contains(options, "c") {
		prefs.AssignPrefs.ClobberCustomTags = true
	}
	prefs.TraversePrefs.DontFollowAlias = true
	return prefs
}

func multiplyWithPrefs() lexAction {
	return func(match string) (*token, error) {
		prefs := multiplyPrefsFromString(match[1:])
		op := &Operation{OperationType: multiplyOpType, Value: multiplyOpType.Type, StringValue: match, Preferences: prefs}
		return &token{TokenType: operationToken, Operation: op, Match: match}, nil
	}
}

func multiplyAssignWithPrefs() lexAction {
	return func(match string) (*token, error) {
		prefs := multiplyPrefsFromString(match[2:])
		op := &Operation{OperationType: multiplyAssignOpType, Value: multiplyAssignOpType.Type, StringValue: match, Preferences: prefs}
		return &token{TokenType: operationToken, Operation: op, Match: match}, nil
	}
}

