func encodeParseIndent(format string) lexAction {
	return func(match string) (*token, error) {
		idx := strings.Index(match, "(")
		indent, err := strconv.Atoi(match[idx+1 : len(match)-1])
		if err != nil {
			return nil, err
		}
		return encodeWithIndent(format, indent)(match)
	}
}

func encodeWithIndent(format string, indent int) lexAction {
	return func(match string) (*token, error) {
