	Operation            *Operation
	AssignOperation      *Operation
	CheckForPostTraverse bool
	Match                string
	Optional             bool
}

func (t *token) toString() string {
	switch t.TokenType {
	case operationToken:
		return t.Operation.StringValue
	case openBracket:
		return "("
	case closeBracket:
		return ")"
	case openCollect:
