		}
		return &token{TokenType: operationToken, Operation: op, AssignOperation: assign, CheckForPostTraverse: opType.CheckForPostTraverse, Match: match}, nil
	}
}

func opToken(opType *operationType) lexAction {
	return opTokenWithPrefs(opType, nil, nil)
}

