func numberAction(match string) (*token, error) {
	var v string = match
	isFloat := strings.ContainsAny(match, ".eE") && !strings.HasPrefix(strings.TrimPrefix(match, "-"), "0x") && !strings.HasPrefix(strings.TrimPrefix(match, "-"), "0X")
	if isFloat {
		if _, err := strconv.ParseFloat(v, 64); err != nil {
			return nil, err
		}
		return valueToken(&CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: v}, match), nil
	}
	if _, _, err := parseInt64(v); err != nil {
