		op := &Operation{OperationType: loadOpType, StringValue: match, Preferences: prefs}
		return &token{TokenType: operationToken, Operation: op, Match: match}, nil
	}
}

func lexExpression(expression string) ([]*token, error) {
	var tokens []*token
	pos := 0
	line, col := 1, 1
	for pos < len(expression) {
		rest := expression[pos:]
		matched := false
		for _, rule := range lexRules {
			loc := rule.re.FindStringIndex(rest)
			if loc == nil || loc[1] == 0 {
				continue
			}
			text := rest[:loc[1]]
			matched = true
			if rule.action != nil {
				t, err := rule.action(text)
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, t)
			}
			for _, r := range text {
				if r == '\n' {
					line++
					col = 1
				} else {
					col++
				}
			}
			pos += loc[1]
			break
		}
		if !matched {
			snippet := []rune(rest)
			s := rest
			if len(snippet) > 16 {
				s = string(snippet[:16]) + "..."
			}
			return nil, fmt.Errorf("%v:%v: lexer: invalid input text %q", line, col, s)
		}
	}
	return tokens, nil
}

func tokenise(expression string) ([]*token, error) {
	rawTokens, err := lexExpression(expression)
	if err != nil {
		return nil, err
	}
	var postProcessed = make([]*token, 0)
	skipNextToken := false
	for index := range rawTokens {
		if skipNextToken {
			skipNextToken = false
		} else {
			postProcessed, skipNextToken = handleToken(rawTokens, index, postProcessed)
		}
	}
	return postProcessed, nil
}

func handleToken(tokens []*token, index int, postProcessedTokens []*token) (tokensAccum []*token, skipNextToken bool) {
	skipNextToken = false
	currentToken := tokens[index]

	if currentToken.TokenType == traverseArrayCollect {
		// `.[exp]` works by creating a traversal array of [self, exp]
		op := &Operation{OperationType: selfReferenceOpType, StringValue: "SELF"}
		postProcessedTokens = append(postProcessedTokens, &token{TokenType: operationToken, Operation: op})

		op = &Operation{OperationType: traverseArrayOpType, StringValue: "TRAVERSE_ARRAY", Preferences: traversePreferences{}}
		postProcessedTokens = append(postProcessedTokens, &token{TokenType: operationToken, Operation: op})

		currentToken = &token{TokenType: openCollect, Match: "["}
	}

	if index != len(tokens)-1 && currentToken.AssignOperation != nil &&
		tokens[index+1].TokenType == operationToken &&
		tokens[index+1].Operation.OperationType == assignOpType {
		newOp := *currentToken.AssignOperation
		newOp.UpdateAssign = tokens[index+1].Operation.UpdateAssign
		if p, ok := tokens[index+1].Operation.Preferences.(assignPreferences); ok {
			if newOp.Preferences == nil {
				newOp.Preferences = p
			}
			newOp.assignPrefs = p
		}
		newToken := *currentToken
		newToken.Operation = &newOp
		currentToken = &newToken
		skipNextToken = true
	}

	postProcessedTokens = append(postProcessedTokens, currentToken)

	if index != len(tokens)-1 &&
		((currentToken.TokenType == openCollect && tokens[index+1].TokenType == closeCollect) ||
			(currentToken.TokenType == openCollectObject && tokens[index+1].TokenType == closeCollectObject)) {
		op := &Operation{OperationType: emptyOpType, StringValue: "EMPTY"}
		postProcessedTokens = append(postProcessedTokens, &token{TokenType: operationToken, Operation: op})
	}

	// slice support: `[:x]` and `[x:]` within a traverse array
	if currentToken.TokenType == openCollect && index != len(tokens)-1 &&
		tokens[index+1].TokenType == operationToken && tokens[index+1].Operation.OperationType == createMapOpType &&
		len(postProcessedTokens) >= 2 {
		prev := postProcessedTokens[len(postProcessedTokens)-2]
		if prev.TokenType == operationToken && prev.Operation.OperationType == traverseArrayOpType {
			postProcessedTokens = append(postProcessedTokens, valueToken(createIntScalar(0), "0"))
		}
	}
	if currentToken.TokenType == operationToken && currentToken.Operation.OperationType == createMapOpType &&
		index != len(tokens)-1 && tokens[index+1].TokenType == closeCollect {
		if isInsideTraverseArray(postProcessedTokens) {
			op := &Operation{OperationType: lengthOpType, StringValue: "length"}
			postProcessedTokens = append(postProcessedTokens, &token{TokenType: operationToken, Operation: op})
		}
	}

	if index != len(tokens)-1 && currentToken.CheckForPostTraverse &&
		((tokens[index+1].TokenType == operationToken && (tokens[index+1].Operation.OperationType == traversePathOpType)) ||
			(tokens[index+1].TokenType == traverseArrayCollect)) {
		op := &Operation{OperationType: shortPipeOpType, Value: "PIPE", StringValue: "."}
		postProcessedTokens = append(postProcessedTokens, &token{TokenType: operationToken, Operation: op})
	}
	if index != len(tokens)-1 && currentToken.CheckForPostTraverse &&
		tokens[index+1].TokenType == openCollect {
		op := &Operation{OperationType: traverseArrayOpType, StringValue: "TRAVERSE_ARRAY", Preferences: traversePreferences{}}
		postProcessedTokens = append(postProcessedTokens, &token{TokenType: operationToken, Operation: op})
	}
	return postProcessedTokens, skipNextToken
}

// isInsideTraverseArray determines whether the innermost open collect is the rhs of a traverse array
func isInsideTraverseArray(tokens []*token) bool {
	depth := 0
	for i := len(tokens) - 1; i >= 0; i-- {
		t := tokens[i]
		switch t.TokenType {
		case closeCollect, closeBracket, closeCollectObject:
			depth++
		case openBracket, openCollectObject:
			if depth == 0 {
				continue
			}
			depth--
		case openCollect:
			if depth == 0 {
				if i > 0 && tokens[i-1].TokenType == operationToken && tokens[i-1].Operation.OperationType == traverseArrayOpType {
					return true
				}
				return false
			}
			depth--
		}
	}
	return false
}
