func popOpToResult(opStack []*token, result []*Operation) ([]*token, []*Operation) {
	var newOp *token
	opStack, newOp = opStack[0:len(opStack)-1], opStack[len(opStack)-1]
	return opStack, append(result, newOp.Operation)
}

func convertToPostfix(infixTokens []*token) ([]*Operation, error) {
	var result []*Operation
	var opStack = []*token{{TokenType: openBracket}}
	var tokens = append(infixTokens, &token{TokenType: closeBracket})

	for _, currentToken := range tokens {
		switch currentToken.TokenType {
		case openBracket, openCollect, openCollectObject:
			opStack = append(opStack, currentToken)
		case closeCollect, closeCollectObject, closeBracket:
			var opener tokenType = openCollect
			if currentToken.TokenType == closeCollectObject {
				opener = openCollectObject
			} else if currentToken.TokenType == closeBracket {
				opener = openBracket
			}
			for len(opStack) > 0 && !isOpener(opStack[len(opStack)-1].TokenType) {
				opStack, result = popOpToResult(opStack, result)
			}
			if len(opStack) == 0 {
				return nil, errors.New("bad expression, got close brackets without matching opening bracket")
			}
			top := opStack[len(opStack)-1]
			if top.TokenType != opener {
				return nil, fmt.Errorf("bad expression, could not find matching `%v`", getCloseToken(top.TokenType))
			}
			opStack = opStack[0 : len(opStack)-1]

			if currentToken.TokenType == closeBracket {
				continue
			}
			if currentToken.TokenType == closeCollectObject {
				result = append(result, &Operation{OperationType: collectObjectOpType, StringValue: ""})
			} else {
				result = append(result, &Operation{OperationType: collectOpType, StringValue: ""})
			}
			// optional traverse flag
			if len(opStack) > 0 && opStack[len(opStack)-1].Operation != nil &&
				opStack[len(opStack)-1].Operation.OperationType == traverseArrayOpType {
				opStack[len(opStack)-1].Operation.Preferences = traversePreferences{OptionalTraverse: currentToken.Optional}
			}
		default:
			var currentPrecedence = currentToken.Operation.OperationType.Precedence
			for len(opStack) > 0 &&
				opStack[len(opStack)-1].TokenType == operationToken &&
				opStack[len(opStack)-1].Operation.OperationType.Precedence > currentPrecedence {
				opStack, result = popOpToResult(opStack, result)
			}
			opStack = append(opStack, currentToken)
		}
	}

	if len(opStack) > 0 {
		top := opStack[len(opStack)-1]
		name := top.toString()
		if top.TokenType == operationToken {
			name = top.Operation.OperationType.Type
		}
		return nil, fmt.Errorf("bad expression - probably missing close bracket on %v", name)
	}
	return result, nil
}

func createExpressionTree(postFixPath []*Operation) (*ExpressionNode, error) {
	var stack = make([]*ExpressionNode, 0)
	if len(postFixPath) == 0 {
		return nil, nil
	}
	for _, pathElement := range postFixPath {
		var newNode = ExpressionNode{Operation: pathElement}
		numArgs := pathElement.OperationType.NumArgs
		if numArgs == 1 {
			if len(stack) < 1 {
				if !pathElement.OperationType.OptionalArg {
					return nil, fmt.Errorf("'%v' expects 1 arg but received none", strings.TrimSpace(pathElement.StringValue))
				}
			} else {
				remaining, rhs := stack[:len(stack)-1], stack[len(stack)-1]
				newNode.RHS = rhs
				stack = remaining
			}
		} else if numArgs == 2 {
			if len(stack) < 2 {
				return nil, fmt.Errorf("'%v' expects 2 args but there is %v", strings.TrimSpace(pathElement.StringValue), len(stack))
			}
			remaining, lhs, rhs := stack[:len(stack)-2], stack[len(stack)-2], stack[len(stack)-1]
			newNode.LHS = lhs
			newNode.RHS = rhs
			stack = remaining
		}
		stack = append(stack, &newNode)
	}
	if len(stack) != 1 {
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	return stack[0], nil
}

func ParseExpression(expression string) (*ExpressionNode, error) {
	tokens, err := tokenise(expression)
	if err != nil {
		return nil, err
	}
	postfix, err := convertToPostfix(tokens)
	if err != nil {
		return nil, err
	}
	return createExpressionTree(postfix)
}
