package main

import (
	"fmt"
)

var listIDCounter int64

func newListID() int64 {
	listIDCounter++
	return listIDCounter
}

type Context struct {
	MatchingNodes  []*CandidateNode
	Variables      map[string]*varValue
	DontAutoCreate bool
	listID         int64
}

type varValue struct {
	nodes  []*CandidateNode
	listID int64
}

func (n *Context) SingleReadonlyChildContext(candidate *CandidateNode) Context {
	ctx := n.SingleChildContext(candidate)
	ctx.DontAutoCreate = true
	return ctx
}

func (n *Context) SingleChildContext(candidate *CandidateNode) Context {
	return n.ChildContext([]*CandidateNode{candidate})
}

func (n *Context) GetVariable(name string) *varValue {
	if n.Variables == nil {
		return nil
	}
	return n.Variables[name]
}

func (n *Context) SetVariable(name string, value []*CandidateNode) {
	if n.Variables == nil {
		n.Variables = make(map[string]*varValue)
	}
	n.Variables[name] = &varValue{nodes: value, listID: newListID()}
}

func (n *Context) ChildContext(results []*CandidateNode) Context {
	clone := Context{DontAutoCreate: n.DontAutoCreate, listID: newListID()}
	clone.Variables = make(map[string]*varValue)
	for k, v := range n.Variables {
		clone.Variables[k] = v
	}
	clone.MatchingNodes = results
	return clone
}

// childContextSameList keeps the identity of an existing list
func (n *Context) childContextWithID(results []*CandidateNode, id int64) Context {
	c := n.ChildContext(results)
	c.listID = id
	return c
}

func (n *Context) ToString() string {
	return fmt.Sprintf("Context with %v nodes", len(n.MatchingNodes))
}

func (n *Context) DeepClone() Context {
	clonedContent := make([]*CandidateNode, 0, len(n.MatchingNodes))
	for _, m := range n.MatchingNodes {
		clonedContent = append(clonedContent, m.Copy())
	}
	return n.ChildContext(clonedContent)
}

func (n *Context) Clone() Context {
	clone := n.ChildContext(n.MatchingNodes)
	clone.listID = n.listID
	return clone
}

func (n *Context) ReadOnlyClone() Context {
	clone := n.Clone()
	clone.DontAutoCreate = true
	return clone
}

func (n *Context) WritableClone() Context {
	clone := n.Clone()
	clone.DontAutoCreate = false
	return clone
}

type dataTreeNavigator struct{}

func (d *dataTreeNavigator) GetMatchingNodes(context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode == nil {
		return context, nil
	}
	handler := expressionNode.Operation.OperationType.Handler
	if handler != nil {
		return handler(d, context, expressionNode)
	}
	return Context{}, fmt.Errorf("unknown operator %v", expressionNode.Operation.OperationType.Type)
}

func emptyOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return context.ChildContext([]*CandidateNode{}), nil
}

func selfOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return context, nil
}

func valueOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if len(context.MatchingNodes) == 0 {
		clone := expressionNode.Operation.CandidateNode.Copy()
		return context.SingleChildContext(clone), nil
	}
	var results []*CandidateNode
	for range context.MatchingNodes {
		results = append(results, expressionNode.Operation.CandidateNode.Copy())
	}
	return context.ChildContext(results), nil
}

func pipeOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.LHS.Operation.OperationType == assignVariableOpType {
		return variableLoop(d, context, expressionNode)
	}
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	rhsContext := context.childContextWithID(lhs.MatchingNodes, lhs.listID)
	rhsContext.Variables = lhs.Variables
	rhs, err := d.GetMatchingNodes(rhsContext, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	return context.childContextWithID(rhs.MatchingNodes, rhs.listID), nil
}

func unionOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	rhs, err := d.GetMatchingNodes(context, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	results := make([]*CandidateNode, 0, len(lhs.MatchingNodes)+len(rhs.MatchingNodes))
	results = append(results, lhs.MatchingNodes...)
	if lhs.listID != rhs.listID || lhs.listID == 0 {
		results = append(results, rhs.MatchingNodes...)
	}
	return lhs.ChildContext(results), nil
}

func allEvaluateTogether(nodes []*CandidateNode) bool {
	for _, n := range nodes {
		if !n.EvaluateTogether {
			return false
		}
	}
	return true
}

func variableLoop(d *dataTreeNavigator, context Context, originalExp *ExpressionNode) (Context, error) {
	if allEvaluateTogether(context.MatchingNodes) {
		return variableLoopSingleChild(d, context, originalExp)
	}
	var results []*CandidateNode
	for _, el := range context.MatchingNodes {
		result, err := variableLoopSingleChild(d, context.SingleChildContext(el), originalExp)
		if err != nil {
			return Context{}, err
		}
		results = append(results, result.MatchingNodes...)
	}
	return context.ChildContext(results), nil
}

func variableLoopSingleChild(d *dataTreeNavigator, context Context, originalExp *ExpressionNode) (Context, error) {
	variableExp := originalExp.LHS
	lhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), variableExp.LHS)
	if err != nil {
		return Context{}, err
	}
	if variableExp.RHS.Operation.OperationType != getVariableOpType {
		return Context{}, fmt.Errorf("RHS of 'as' operator must be a variable name e.g. $foo")
	}
	variableName := variableExp.RHS.Operation.StringValue
	prefs := variableExp.Operation.Preferences.(assignVarPreferences)

	var results []*CandidateNode
	for _, el := range lhs.MatchingNodes {
		var variableValue []*CandidateNode
		if prefs.IsReference {
			variableValue = []*CandidateNode{el}
		} else {
			variableValue = []*CandidateNode{el.Copy()}
		}
		newContext := context.childContextWithID(context.MatchingNodes, context.listID)
		newContext.SetVariable(variableName, variableValue)
		rhs, err := d.GetMatchingNodes(newContext, originalExp.RHS)
		if err != nil {
			return Context{}, err
		}
		results = append(results, rhs.MatchingNodes...)
	}
	if len(lhs.MatchingNodes) == 0 {
		return d.GetMatchingNodes(context, originalExp.RHS)
	}
	return context.ChildContext(results), nil
}

type assignVarPreferences struct {
	IsReference bool
}

func useWithPipe(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return Context{}, fmt.Errorf("must use variable with a pipe, e.g. `exp as $x | ...`")
}

func getVariableOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	variableName := expressionNode.Operation.StringValue
	result := context.GetVariable(variableName)
	if result == nil {
		return context.ChildContext([]*CandidateNode{}), nil
	}
	return context.childContextWithID(result.nodes, result.listID), nil
}
