package main

import (
	"fmt"
	"os"
	"strings"
	"sync"
)

type traversePreferences struct {
	DontFollowAlias      bool
	IncludeMapKeys       bool
	DontAutoCreate       bool
	DontIncludeMapValues bool
	OptionalTraverse     bool
	ExactKeyMatch        bool
}

type recursiveDescentPreferences struct {
	TraversePreferences traversePreferences
	RecurseArray        bool
}

// orderedNodeMap keeps the first insertion position but the last value
type orderedNodeMap struct {
	keys   []string
	values map[string]*CandidateNode
}

func newOrderedNodeMap() *orderedNodeMap {
	return &orderedNodeMap{values: map[string]*CandidateNode{}}
}

func (o *orderedNodeMap) Set(key string, value *CandidateNode) {
	if _, ok := o.values[key]; !ok {
		o.keys = append(o.keys, key)
	}
	o.values[key] = value
}

func (o *orderedNodeMap) Has(key string) bool {
	_, ok := o.values[key]
	return ok
}

func (o *orderedNodeMap) Len() int { return len(o.keys) }

func (o *orderedNodeMap) List() []*CandidateNode {
	res := make([]*CandidateNode, 0, len(o.keys))
	for _, k := range o.keys {
		res = append(res, o.values[k])
	}
	return res
}

func traversePathOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var matches []*CandidateNode
	for _, n := range context.MatchingNodes {
		newNodes, err := traverse(context, n, expressionNode.Operation)
		if err != nil {
			return Context{}, err
		}
		matches = append(matches, newNodes...)
	}
	return context.ChildContext(matches), nil
}

func traverse(context Context, matchingNode *CandidateNode, operation *Operation) ([]*CandidateNode, error) {
	prefs, _ := operation.Preferences.(traversePreferences)
	if matchingNode.Tag == "!!null" && operation.Value != "[]" && !context.DontAutoCreate {
		matchingNode.Kind = MappingNode
		matchingNode.Tag = ""
	}

	switch matchingNode.Kind {
	case MappingNode:
		return traverseMap(context, matchingNode, createStringScalar(operation.StringValue), prefs, false)
	case SequenceNode:
		indices := []*CandidateNode{{Value: operation.StringValue}}
		return traverseArrayWithIndices(matchingNode, indices, prefs)
	case AliasNode:
		if matchingNode.Alias == nil {
			return nil, nil
		}
		return traverse(context, matchingNode.Alias, operation)
	default:
		return nil, nil
	}
}

func traverseArrayOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	// slice support
	if expressionNode.RHS != nil && expressionNode.RHS.Operation.OperationType == collectOpType &&
		expressionNode.RHS.RHS != nil && expressionNode.RHS.RHS.Operation.OperationType == createMapOpType {
		lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
		if err != nil {
			return Context{}, err
		}
		return sliceNodes(d, lhs, expressionNode.RHS.RHS)
	}

	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	prefs, _ := expressionNode.Operation.Preferences.(traversePreferences)
	var indicesToTraverse []*CandidateNode
	if len(rhs.MatchingNodes) > 0 {
		indicesToTraverse = rhs.MatchingNodes[0].Content
	}
	result, err := traverseNodesWithArrayIndices(lhs, indicesToTraverse, prefs)
	if err != nil {
		return Context{}, err
	}
	return context.ChildContext(result.MatchingNodes), nil
}

func sliceArrayOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return sliceNodes(d, context, expressionNode)
}

func getSliceNumber(d *dataTreeNavigator, context Context, node *CandidateNode, expressionNode *ExpressionNode) (int, error) {
	result, err := d.GetMatchingNodes(context.SingleChildContext(node), expressionNode)
	if err != nil {
		return 0, err
	}
	if len(result.MatchingNodes) != 1 {
		return 0, fmt.Errorf("expected to find 1 number, got %v instead", len(result.MatchingNodes))
	}
	return parseInt(result.MatchingNodes[0].Value)
}

func sliceNodes(d *dataTreeNavigator, context Context, createMapNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, lhsNode := range context.MatchingNodes {
		firstNumber, err := getSliceNumber(d, context, lhsNode, createMapNode.LHS)
		if err != nil {
			return Context{}, err
		}
		secondNumber, err := getSliceNumber(d, context, lhsNode, createMapNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if lhsNode.Kind == ScalarNode && lhsNode.Tag == "!!str" || (lhsNode.Kind == ScalarNode && lhsNode.guessTagFromCustomType() == "!!str") {
			runes := []rune(lhsNode.Value)
			length := len(runes)
			from, to := clampSlice(firstNumber, secondNumber, length)
			replacement := lhsNode.CreateReplacement(ScalarNode, lhsNode.Tag, string(runes[from:to]))
			replacement.Style = lhsNode.Style
			results = append(results, replacement)
			continue
		}
		length := len(lhsNode.Content)
		from, to := clampSlice(firstNumber, secondNumber, length)
		var newResults []*CandidateNode
		for i := from; i < to; i++ {
			newResults = append(newResults, lhsNode.Content[i])
		}
		sliceArrayNode := lhsNode.CreateReplacement(SequenceNode, lhsNode.Tag, "")
		if lhsNode.Kind != SequenceNode {
			sliceArrayNode.Tag = "!!seq"
		}
		sliceArrayNode.Style = lhsNode.Style
		for _, n := range newResults {
			sliceArrayNode.AddChild(n)
		}
		results = append(results, sliceArrayNode)
	}
	return context.ChildContext(results), nil
}

func clampSlice(first, second, length int) (int, int) {
	from := first
	if from < 0 {
		from = length + from
	}
	if from < 0 {
		from = 0
	}
	if from > length {
		from = length
	}
	to := second
	if to < 0 {
		to = length + to
	} else if to > length {
		to = length
	}
	if to < from {
		to = from
	}
	return from, to
}

func traverseNodesWithArrayIndices(context Context, indicesToTraverse []*CandidateNode, prefs traversePreferences) (Context, error) {
	var matches []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		newNodes, err := traverseArrayIndices(context, candidate, indicesToTraverse, prefs)
		if err != nil {
			return Context{}, err
		}
		matches = append(matches, newNodes...)
	}
	return context.ChildContext(matches), nil
}

func traverseArrayIndices(context Context, matchingNode *CandidateNode, indicesToTraverse []*CandidateNode, prefs traversePreferences) ([]*CandidateNode, error) {
	if matchingNode.Tag == "!!null" {
		matchingNode.Tag = ""
		matchingNode.Kind = SequenceNode
		if len(indicesToTraverse) != 0 && indicesToTraverse[0].Tag != "!!int" {
			matchingNode.Kind = MappingNode
		}
	}

	if matchingNode.Kind == AliasNode {
		if matchingNode.Alias == nil {
			return nil, nil
		}
		return traverseArrayIndices(context, matchingNode.Alias, indicesToTraverse, prefs)
	} else if matchingNode.Kind == SequenceNode {
		return traverseArrayWithIndices(matchingNode, indicesToTraverse, prefs)
	} else if matchingNode.Kind == MappingNode {
		return traverseMapWithIndices(context, matchingNode, indicesToTraverse, prefs)
	}
	return nil, nil
}

func traverseMapWithIndices(context Context, candidate *CandidateNode, indices []*CandidateNode, prefs traversePreferences) ([]*CandidateNode, error) {
	if len(indices) == 0 {
		return traverseMap(context, candidate, createStringScalar(""), prefs, true)
	}
	var matches []*CandidateNode
	for _, indexNode := range indices {
		newNodes, err := traverseMap(context, candidate, indexNode, prefs, false)
		if err != nil {
			return nil, err
		}
		matches = append(matches, newNodes...)
	}
	return matches, nil
}

func traverseArrayWithIndices(node *CandidateNode, indices []*CandidateNode, prefs traversePreferences) ([]*CandidateNode, error) {
	var newMatches []*CandidateNode
	if len(indices) == 0 {
		newMatches = append(newMatches, node.Content...)
		return newMatches, nil
	}

	for _, indexNode := range indices {
		index, err := parseInt(indexNode.Value)
		if err != nil && prefs.OptionalTraverse {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("cannot index array with '%v' (%w)", indexNode.Value, err)
		}
		indexToUse := index
		contentLength := len(node.Content)
		for contentLength <= index {
			if contentLength == 0 {
				node.Style = 0
			}
			valueNode := createScalarNode(nil, "null")
			node.AddChild(valueNode)
			contentLength = len(node.Content)
		}

		if indexToUse < 0 {
			indexToUse = contentLength + indexToUse
		}
		if indexToUse < 0 {
			return nil, fmt.Errorf("index [%v] out of range, array size is %v", index, contentLength)
		}
		newMatches = append(newMatches, node.Content[indexToUse])
	}
	return newMatches, nil
}

func traverseMap(context Context, matchingNode *CandidateNode, keyNode *CandidateNode, prefs traversePreferences, splat bool) ([]*CandidateNode, error) {
	var newMatches = newOrderedNodeMap()
	err := doTraverseMap(newMatches, matchingNode, keyNode.Value, prefs, splat)
	if err != nil {
		return nil, err
	}

	if !splat && !prefs.DontAutoCreate && !context.DontAutoCreate && newMatches.Len() == 0 {
		valueNode := &CandidateNode{Kind: ScalarNode, Tag: "!!null", Value: "null"}
		if len(matchingNode.Content) == 0 {
			matchingNode.Style = 0
		}
		var newKey, newValue = matchingNode.AddKeyValueChild(keyNode, valueNode)
		if prefs.IncludeMapKeys {
			newMatches.Set(newKey.GetKey(), newKey)
		}
		if !prefs.DontIncludeMapValues {
			newMatches.Set(newValue.GetKey(), newValue)
		}
	}
	return newMatches.List(), nil
}

var mergeWarningOnce sync.Once

func warnMergeAnchor() {
	if !ConfiguredYamlPreferences.FixMergeAnchorToSpec {
		mergeWarningOnce.Do(func() {
			logWarn("--yaml-fix-merge-anchor-to-spec is false; causing merge anchors to override the existing values which isn't to the yaml spec. This flag will default to true in late 2025. See https://mikefarah.gitbook.io/yq/operators/traverse-read for more details.")
		})
	}
}

func doTraverseMap(newMatches *orderedNodeMap, node *CandidateNode, wantedKey string, prefs traversePreferences, splat bool) error {
	var contents = node.Content

	if ConfiguredYamlPreferences.FixMergeAnchorToSpec {
		// merge anchors first, then direct keys
		for index := 0; index+1 < len(contents); index = index + 2 {
			key := contents[index]
			value := contents[index+1]
			if key.Tag == "!!merge" && !prefs.DontFollowAlias && wantedKey != key.Value {
				if err := traverseMergeAnchor(newMatches, value, wantedKey, prefs, splat); err != nil {
					return err
				}
			}
		}
		for index := 0; index+1 < len(contents); index = index + 2 {
			key := contents[index]
			value := contents[index+1]
			if key.Tag == "!!merge" && !prefs.DontFollowAlias && wantedKey != key.Value {
				continue
			}
			if splat || keyMatches(key, wantedKey, prefs) {
				addTraverseMatch(newMatches, key, value, prefs)
			}
		}
		return nil
	}

	for index := 0; index+1 < len(contents); index = index + 2 {
		key := contents[index]
		value := contents[index+1]

		if key.Tag == "!!merge" && !prefs.DontFollowAlias && wantedKey != key.Value {
			warnMergeAnchor()
			if err := traverseMergeAnchor(newMatches, value, wantedKey, prefs, splat); err != nil {
				return err
			}
		} else if splat || keyMatches(key, wantedKey, prefs) {
			addTraverseMatch(newMatches, key, value, prefs)
		}
	}
	return nil
}

func addTraverseMatch(newMatches *orderedNodeMap, key *CandidateNode, value *CandidateNode, prefs traversePreferences) {
	if prefs.IncludeMapKeys {
		newMatches.Set(key.GetKey(), key)
	}
	if !prefs.DontIncludeMapValues {
		newMatches.Set(value.GetKey(), value)
	}
}

func traverseMergeAnchor(newMatches *orderedNodeMap, merge *CandidateNode, wantedKey string, prefs traversePreferences, splat bool) error {
	switch merge.Kind {
	case AliasNode:
		if merge.Alias == nil {
			return nil
		}
		if merge.Alias.Kind != MappingNode {
			return fmt.Errorf("can only use merge anchors with maps (!!map) or sequences (!!seq) of maps, but got %v", merge.Alias.Tag)
		}
		return doTraverseMap(newMatches, merge.Alias, wantedKey, prefs, splat)
	case MappingNode:
		return doTraverseMap(newMatches, merge, wantedKey, prefs, splat)
	case SequenceNode:
		content := merge.Content
		if ConfiguredYamlPreferences.FixMergeAnchorToSpec {
			reversed := make([]*CandidateNode, len(content))
			for i, c := range content {
				reversed[len(content)-1-i] = c
			}
			content = reversed
		}
		for _, childValue := range content {
			target := childValue
			if childValue.Kind == AliasNode {
				target = childValue.Alias
			}
			if target == nil {
				continue
			}
			if target.Kind != MappingNode {
				return fmt.Errorf("can only use merge anchors with maps (!!map) or sequences (!!seq) of maps, but got sequence containing %v", target.Tag)
			}
			if err := doTraverseMap(newMatches, target, wantedKey, prefs, splat); err != nil {
				return err
			}
		}
	default:
		return fmt.Errorf("can only use merge anchors with maps (!!map) or sequences (!!seq) of maps, but got %v", merge.Tag)
	}
	return nil
}

func keyMatches(key *CandidateNode, wantedKey string, prefs traversePreferences) bool {
	if prefs.ExactKeyMatch {
		return key.Value == wantedKey
	}
	return matchKey(key.Value, wantedKey)
}

func matchKey(name string, pattern string) (matched bool) {
	if pattern == "" {
		return name == pattern
	}
	if pattern == "*" {
		return true
	}
	return deepMatch([]rune(name), []rune(pattern))
}

func deepMatch(str, pattern []rune) bool {
	for len(pattern) > 0 {
		switch pattern[0] {
		default:
			if len(str) == 0 || str[0] != pattern[0] {
				return false
			}
		case '?':
			if len(str) == 0 {
				return false
			}
		case '*':
			return deepMatch(str, pattern[1:]) ||
				(len(str) > 0 && deepMatch(str[1:], pattern))
		}
		str = str[1:]
		pattern = pattern[1:]
	}
	return len(str) == 0 && len(pattern) == 0
}

func splat(context Context, prefs traversePreferences) (Context, error) {
	return traverseNodesWithArrayIndices(context, []*CandidateNode{}, prefs)
}

func recursiveDescentOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	preferences := expressionNode.Operation.Preferences.(recursiveDescentPreferences)
	err := recursiveDecent(&results, context, preferences)
	if err != nil {
		return Context{}, err
	}
	return context.ChildContext(results), nil
}

func recursiveDecent(results *[]*CandidateNode, context Context, prefs recursiveDescentPreferences) error {
	for _, candidate := range context.MatchingNodes {
		*results = append(*results, candidate)
		if candidate.Kind != AliasNode && len(candidate.Content) > 0 &&
			(prefs.RecurseArray || candidate.Kind != SequenceNode) {
			children, err := splat(context.SingleChildContext(candidate), prefs.TraversePreferences)
			if err != nil {
				return err
			}
			err = recursiveDecent(results, children, prefs)
			if err != nil {
				return err
			}
		}
	}
	return nil
}

func logWarn(msg string) {
	fmt.Fprintf(os.Stderr, "%v level=WARN msg=%v\n", logTimestamp(), quoteLogValue(msg))
}

func quoteLogValue(s string) string {
	if s == "" || strings.ContainsAny(s, " =\"") || needsQuoting(s) {
		return fmt.Sprintf("%q", s)
	}
	return s
}

func needsQuoting(s string) bool {
	for _, r := range s {
		if r < ' ' || r == 0x7f {
			return true
		}
	}
	return false
}
