func assignUpdateFunc(prefs assignPreferences) crossFunctionCalculation {
	return func(d *dataTreeNavigator, context Context, lhs *CandidateNode, rhs *CandidateNode) (*CandidateNode, error) {
		if !prefs.OnlyWriteNull || lhs.Tag == "!!null" {
			lhs.UpdateFrom(rhs, prefs)
		}
		return lhs, nil
	}
}

func getAssignPreferences(preferences interface{}) assignPreferences {
	prefs := assignPreferences{}
	switch typedPref := preferences.(type) {
	case assignPreferences:
		prefs = typedPref
	}
	return prefs
}

func assignUpdateOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}

	prefs := getAssignPreferences(expressionNode.Operation.Preferences)

	if !expressionNode.Operation.UpdateAssign {
		// "=" - rhs is evaluated against the original context
		rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for _, rhsNode := range rhs.MatchingNodes {
			for _, candidate := range lhs.MatchingNodes {
				candidate.UpdateFrom(rhsNode, prefs)
			}
		}
		return context, nil
	}

	for _, candidate := range lhs.MatchingNodes {
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		// grab the first value
		if len(rhs.MatchingNodes) > 0 {
			first := rhs.MatchingNodes[0]
			candidate.UpdateFrom(first, prefs)
		}
	}
	return context, nil
}

// does not update content or values
func assignAttributesOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	for _, candidate := range lhs.MatchingNodes {
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if len(rhs.MatchingNodes) > 0 {
			prefs := getAssignPreferences(expressionNode.Operation.Preferences)
			if !prefs.OnlyWriteNull || candidate.Tag == "!!null" {
				candidate.UpdateAttributesFrom(rhs.MatchingNodes[0], prefs)
			}
		}
	}
	return context, nil
}

func compoundAssignFunction(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode, calculation crossFunctionCalculation) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	prefs := assignPreferences{DontOverWriteAnchor: true}
	for _, candidate := range lhs.MatchingNodes {
		rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		original := candidate.Copy()
		var newValues []*CandidateNode
		for _, rhsNode := range rhs.MatchingNodes {
			lhsCopy := original.Copy()
			lhsCopy.Parent = candidate.Parent
			lhsCopy.Key = candidate.Key
			newValue, err := calculation(d, context, lhsCopy, rhsNode)
			if err != nil {
				return Context{}, err
			}
			if newValue != nil {
				newValues = append(newValues, newValue)
			}
		}
		for _, nv := range newValues {
			candidate.UpdateFrom(nv, prefs)
		}
	}
	return context, nil
}

func addAssignOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return compoundAssignFunction(d, context, expressionNode, add)
}

func subtractAssignOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return compoundAssignFunction(d, context, expressionNode, subtract)
}

func multiplyAssignOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	prefs, _ := expressionNode.Operation.Preferences.(multiplyPreferences)
	return compoundAssignFunction(d, context, expressionNode, multiply(prefs))
}

