		if err != nil {
			return Context{}, err
		}
		for _, addition := range additions.MatchingNodes {
			additionCopy := addition.Copy()
			additionCopy.SetParent(nil)
			additionCopy.Key = nil
			newObject = append(newObject, additionCopy)
		}
	}
	return context.ChildContext(newObject), nil
}

func collectObjectCartesian(d *dataTreeNavigator, context Context, remainingMatches []*CandidateNode) (Context, error) {
	if len(remainingMatches) == 0 {
		return context, nil
	}
	candidate := remainingMatches[0]
	remainingMatches = remainingMatches[1:]

	splatted, err := splat(context.SingleChildContext(candidate),
		traversePreferences{DontFollowAlias: true, IncludeMapKeys: false})
	if err != nil {
		return Context{}, err
	}

	if len(context.MatchingNodes) == 0 {
		return collectObjectCartesian(d, splatted, remainingMatches)
	}

	var newAgg []*CandidateNode
	for _, aggCandidate := range context.MatchingNodes {
		for _, splatCandidate := range splatted.MatchingNodes {
