			newCandidate, err = multiply(multiplyPreferences{AppendArrays: false})(d, context, newCandidate, splatCandidate)
			if err != nil {
				return Context{}, err
			}
			newAgg = append(newAgg, newCandidate)
		}
	}
	return collectObjectCartesian(d, context.ChildContext(newAgg), remainingMatches)
}
