package main

import (
	"fmt"
	"regexp"
	"strings"
)

type commentOpPreferences struct {
	LineComment bool
	HeadComment bool
	FootComment bool
}

func assignCommentsOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	preferences := expressionNode.Operation.Preferences.(commentOpPreferences)
	comment := ""
	if !expressionNode.Operation.UpdateAssign {
		rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if len(rhs.MatchingNodes) > 0 {
			comment = rhs.MatchingNodes[0].Value
		}
	}

	for _, candidate := range lhs.MatchingNodes {
		if expressionNode.Operation.UpdateAssign {
			rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			if len(rhs.MatchingNodes) > 0 {
				comment = rhs.MatchingNodes[0].Value
			}
		}
		if preferences.LineComment {
			candidate.LineComment = comment
		}
		if preferences.HeadComment {
			candidate.HeadComment = comment
			candidate.LeadingContent = ""
		}
		if preferences.FootComment {
			candidate.FootComment = comment
		}
	}
	return context, nil
}

var startCommentCharacterRegExp = regexp.MustCompile(`^# `)
var subsequentCommentCharacterRegExp = regexp.MustCompile(`\n# `)

func getCommentsOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	preferences := expressionNode.Operation.Preferences.(commentOpPreferences)
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		comment := ""
		if preferences.LineComment {
			comment = candidate.LineComment
		} else if preferences.HeadComment && candidate.LeadingContent != "" {
			var chompRegexp = regexp.MustCompile(`\n$`)
			var output strings.Builder
			lines := strings.SplitAfter(candidate.LeadingContent, "\n")
			for _, line := range lines {
				if strings.Contains(line, docSeparatorPlaceholder) {
					continue
				}
				output.WriteString(line)
			}
			comment = chompRegexp.ReplaceAllString(output.String(), "")
		} else if preferences.HeadComment {
			comment = candidate.HeadComment
		} else if preferences.FootComment {
			comment = candidate.FootComment
		}
		comment = startCommentCharacterRegExp.ReplaceAllString(comment, "")
		comment = subsequentCommentCharacterRegExp.ReplaceAllString(comment, "\n")

		node := candidate.CreateReplacement(ScalarNode, "!!str", comment)
		if candidate.IsMapKey {
			node.IsMapKey = false
			node.Key = candidate
		}
		results = append(results, node)
	}
	return context.ChildContext(results), nil
}

func parseStyle(customStyle string) (Style, error) {
	switch customStyle {
	case "tagged":
		return TaggedStyle, nil
	case "double":
		return DoubleQuotedStyle, nil
	case "single":
		return SingleQuotedStyle, nil
	case "literal":
		return LiteralStyle, nil
	case "folded":
		return FoldedStyle, nil
	case "flow":
		return FlowStyle, nil
	case "":
		return 0, nil
	}
	return 0, fmt.Errorf("unknown style %v", customStyle)
}

func assignStyleOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	var style Style
	if !expressionNode.Operation.UpdateAssign {
		rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if len(rhs.MatchingNodes) > 0 {
			style, err = parseStyle(rhs.MatchingNodes[0].Value)
			if err != nil {
				return Context{}, err
			}
		}
	}
	for _, candidate := range lhs.MatchingNodes {
		if expressionNode.Operation.UpdateAssign {
			rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			if len(rhs.MatchingNodes) > 0 {
				style, err = parseStyle(rhs.MatchingNodes[0].Value)
				if err != nil {
					return Context{}, err
				}
			}
		}
		candidate.Style = style
	}
	return context, nil
}

func getStyleOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		var style string
		switch candidate.Style {
		case TaggedStyle:
			style = "tagged"
		case DoubleQuotedStyle:
			style = "double"
		case SingleQuotedStyle:
			style = "single"
		case LiteralStyle:
			style = "literal"
		case FoldedStyle:
			style = "folded"
		case FlowStyle:
			style = "flow"
		case 0:
			style = ""
		default:
			style = "<unknown>"
		}
		result := candidate.CreateReplacement(ScalarNode, "!!str", style)
		results = append(results, result)
	}
	return context.ChildContext(results), nil
}

func assignTagOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	tag := ""
	if !expressionNode.Operation.UpdateAssign {
		rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if len(rhs.MatchingNodes) > 0 {
			tag = rhs.MatchingNodes[0].Value
		}
	}
	for _, candidate := range lhs.MatchingNodes {
		if expressionNode.Operation.UpdateAssign {
			rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			if len(rhs.MatchingNodes) > 0 {
				tag = rhs.MatchingNodes[0].Value
			}
		}
		candidate.Tag = tag
	}
	return context, nil
}

func getTagOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		result := candidate.CreateReplacement(ScalarNode, "!!str", candidate.Tag)
		results = append(results, result)
	}
	return context.ChildContext(results), nil
}

func assignAnchorOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	anchorName := ""
	if !expressionNode.Operation.UpdateAssign {
		rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if len(rhs.MatchingNodes) > 0 {
			anchorName = rhs.MatchingNodes[0].Value
		}
	}
	for _, candidate := range lhs.MatchingNodes {
