type flattenPreferences struct {
	depth int
}

func flatten(node *CandidateNode, depth int) {
	if depth == 0 {
		return
	}
	if node.Kind != SequenceNode {
		return
	}
	content := node.Content
	newSeq := make([]*CandidateNode, 0)
	for i := 0; i < len(content); i++ {
		if content[i].Kind == SequenceNode {
			flatten(content[i], depth-1)
			newSeq = append(newSeq, content[i].Content...)
		} else {
			newSeq = append(newSeq, content[i])
		}
	}
	node.Content = make([]*CandidateNode, 0)
	node.AddChildren(newSeq)
}

func flattenOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	depth := expressionNode.Operation.Preferences.(flattenPreferences).depth
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return Context{}, fmt.Errorf("only arrays are supported for flatten")
		}
		flatten(candidate, depth)
	}
	return context, nil
}

// ---------------- sorting -----------------

type sortableNode struct {
	Node           *CandidateNode
	CompareContext Context
	dateTimeLayout string
}

type sortableNodeArray []sortableNode

func (a sortableNodeArray) Len() int      { return len(a) }
func (a sortableNodeArray) Swap(i, j int) { a[i], a[j] = a[j], a[i] }

func (a sortableNodeArray) Less(i, j int) bool {
	lhsContext := a[i].CompareContext
	rhsContext := a[j].CompareContext
	rIdx := 0
	for lIdx := 0; lIdx < len(lhsContext.MatchingNodes) && rIdx < len(rhsContext.MatchingNodes); lIdx++ {
		lhs := lhsContext.MatchingNodes[lIdx]
		rhs := rhsContext.MatchingNodes[rIdx]
		result := compareNodesForSort(lhs, rhs, a[i].dateTimeLayout)
		if result < 0 {
			return true
		} else if result > 0 {
			return false
		}
		rIdx++
	}
	return false
}

func compareNodesForSort(lhs *CandidateNode, rhs *CandidateNode, dateTimeLayout string) int {
	lhsTag := lhs.Tag
	rhsTag := rhs.Tag
	if !strings.HasPrefix(lhsTag, "!!") {
		lhsTag = lhs.guessTagFromCustomType()
	}
	if !strings.HasPrefix(rhsTag, "!!") {
		rhsTag = rhs.guessTagFromCustomType()
	}

	isDateTime := lhsTag == "!!timestamp" && rhsTag == "!!timestamp"
	layout := dateTimeLayout
	if lhsTag == "!!str" && layout != defaultDateTimeLayout {
		_, errLhs := parseDateTime(layout, lhs.Value)
		_, errRhs := parseDateTime(layout, rhs.Value)
		isDateTime = errLhs == nil && errRhs == nil
	}

	if lhsTag == "!!null" && rhsTag != "!!null" {
		return -1
	} else if lhsTag != "!!null" && rhsTag == "!!null" {
		return 1
	} else if lhsTag == "!!bool" && rhsTag != "!!bool" {
		return -1
	} else if lhsTag != "!!bool" && rhsTag == "!!bool" {
		return 1
	} else if lhsTag == "!!bool" && rhsTag == "!!bool" {
		lhsTruthy := isTruthyNode(lhs)
		rhsTruthy := isTruthyNode(rhs)
		if lhsTruthy == rhsTruthy {
			return 0
		} else if lhsTruthy {
			return 1
		}
		return -1
	} else if isDateTime {
		lhsTime, err := parseDateTime(layout, lhs.Value)
		if err != nil {
			return strings.Compare(lhs.Value, rhs.Value)
		}
		rhsTime, err := parseDateTime(layout, rhs.Value)
		if err != nil {
			return strings.Compare(lhs.Value, rhs.Value)
		}
		if lhsTime.Equal(rhsTime) {
			return 0
		} else if lhsTime.Before(rhsTime) {
			return -1
		}
		return 1
	} else if lhsTag == "!!int" && rhsTag == "!!int" {
		_, lhsNum, err := parseInt64(lhs.Value)
		if err != nil {
			return strings.Compare(lhs.Value, rhs.Value)
		}
		_, rhsNum, err := parseInt64(rhs.Value)
		if err != nil {
			return strings.Compare(lhs.Value, rhs.Value)
		}
		if lhsNum == rhsNum {
			return 0
		} else if lhsNum < rhsNum {
			return -1
		}
		return 1
	} else if (lhsTag == "!!int" || lhsTag == "!!float") && (rhsTag == "!!int" || rhsTag == "!!float") {
		lhsNum, err := strconv.ParseFloat(lhs.Value, 64)
		if err != nil {
			return strings.Compare(lhs.Value, rhs.Value)
		}
		rhsNum, err := strconv.ParseFloat(rhs.Value, 64)
		if err != nil {
			return strings.Compare(lhs.Value, rhs.Value)
		}
		if lhsNum == rhsNum {
			return 0
		} else if lhsNum < rhsNum {
			return -1
		}
		return 1
	}
	return strings.Compare(lhs.Value, rhs.Value)
}

func sortOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	selfExpression := &ExpressionNode{Operation: &Operation{OperationType: selfReferenceOpType}}
	return sortByExpression(d, context, selfExpression)
}

func sortByOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return sortByExpression(d, context, expressionNode.RHS)
}

func sortByExpression(d *dataTreeNavigator, context Context, rhsExp *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind == MappingNode {
			n := len(candidate.Content) / 2
			sortableArray := make(sortableNodeArray, n)
			for i := 0; i < n; i++ {
				valueNode := candidate.Content[i*2+1]
				compareContext, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(valueNode), rhsExp)
				if err != nil {
					return Context{}, err
				}
				sortableArray[i] = sortableNode{Node: candidate.Content[i*2], CompareContext: compareContext, dateTimeLayout: context.GetDateTimeLayout()}
			}
			sort.Stable(sortableArray)
			sortedMap := candidate.CopyWithoutContent()
			sortedMap.Content = nil
			for _, sn := range sortableArray {
				keyNode := sn.Node
				valueNode := candidate.Content[indexOfNode(candidate.Content, keyNode)+1]
				sortedMap.AddKeyValueChild(keyNode, valueNode)
			}
			results = append(results, sortedMap)
			continue
		}
		if candidate.Kind != SequenceNode {
			return context, fmt.Errorf("node at path [%v] is not an array or map (it's a %v)", candidate.GetNicePath(), candidate.Tag)
		}
		sortableArray := make(sortableNodeArray, len(candidate.Content))
		for i, originalNode := range candidate.Content {
			compareContext, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(originalNode), rhsExp)
			if err != nil {
				return Context{}, err
			}
			sortableArray[i] = sortableNode{Node: originalNode, CompareContext: compareContext, dateTimeLayout: context.GetDateTimeLayout()}
		}
		sort.Stable(sortableArray)
		sortedList := candidate.CopyWithoutContent()
		sortedList.Content = nil
		for _, sn := range sortableArray {
			sortedList.AddChild(sn.Node)
		}
		results = append(results, sortedList)
	}
	return context.ChildContext(results), nil
}

func indexOfNode(content []*CandidateNode, n *CandidateNode) int {
	for i, c := range content {
		if c == n {
			return i
		}
	}
	return -1
}

func sortKeysOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	for _, candidate := range context.MatchingNodes {
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for _, node := range rhs.MatchingNodes {
			if node.Kind == MappingNode {
				sortKeys(node)
			}
		}
	}
	return context, nil
}

func sortKeys(node *CandidateNode) {
	keys := make([]string, len(node.Content)/2)
	keyBucket := map[string]*CandidateNode{}
	valueBucket := map[string]*CandidateNode{}
	var contents = node.Content
	for index := 0; index+1 < len(contents); index = index + 2 {
		key := contents[index]
		value := contents[index+1]
		keys[index/2] = key.Value
		keyBucket[key.Value] = key
		valueBucket[key.Value] = value
	}
	sort.Strings(keys)
	sortedContent := make([]*CandidateNode, len(node.Content))
	for index := 0; index < len(keys); index = index + 1 {
		keyString := keys[index]
		sortedContent[index*2] = keyBucket[keyString]
		sortedContent[1+(index*2)] = valueBucket[keyString]
	}
	node.Content = sortedContent
}

func reverseOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return context, fmt.Errorf("node at path [%v] is not an array (it's a %v)", candidate.GetNicePath(), candidate.Tag)
		}
		reverseList := candidate.CreateReplacementWithComments(SequenceNode, "!!seq", candidate.Style)
		reverseContent := make([]*CandidateNode, len(candidate.Content))
		for i, originalNode := range candidate.Content {
			reverseContent[len(candidate.Content)-i-1] = originalNode
		}
		reverseList.AddChildren(reverseContent)
		results = append(results, reverseList)
	}
	return context.ChildContext(results), nil
}

func shuffleOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return context, fmt.Errorf("node at path [%v] is not an array (it's a %v)", candidate.GetNicePath(), candidate.Tag)
		}
		result := candidate.Copy()
		a := result.Content
		rand.Shuffle(len(a), func(i, j int) {
			a[i], a[j] = a[j], a[i]
		})
		results = append(results, result)
	}
	return context.ChildContext(results), nil
}

// ---------------- unique / group -----------------

func uniqueOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	selfExpression := &ExpressionNode{Operation: &Operation{OperationType: selfReferenceOpType}}
	return uniqueByExpression(d, context, selfExpression)
}

func uniqueByOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return uniqueByExpression(d, context, expressionNode.RHS)
}

func getUniqueKeyValue(rhs Context) (string, error) {
	keyValue := "null"
	var err error
	if len(rhs.MatchingNodes) > 0 {
		keyCandidate := rhs.MatchingNodes[0]
		keyValue = keyCandidate.Value
		if keyCandidate.Kind != ScalarNode {
			keyValue, err = encodeToString(keyCandidate, encoderPreferences{format: YamlFormat, indent: 0})
		}
	}
	return keyValue, err
}

func uniqueByExpression(d *dataTreeNavigator, context Context, rhsExp *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return Context{}, fmt.Errorf("only arrays are supported for unique")
		}
		var keys []string
		values := map[string]*CandidateNode{}
		for _, child := range candidate.Content {
			rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(child), rhsExp)
			if err != nil {
				return Context{}, err
			}
			keyValue, err := getUniqueKeyValue(rhs)
			if err != nil {
				return Context{}, err
			}
			if _, exists := values[keyValue]; !exists {
				keys = append(keys, keyValue)
				values[keyValue] = child
			}
		}
		resultNode := candidate.CreateReplacementWithComments(SequenceNode, "!!seq", candidate.Style)
		for _, k := range keys {
			resultNode.AddChild(values[k])
		}
		results = append(results, resultNode)
	}
	return context.ChildContext(results), nil
}

func groupByOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return Context{}, fmt.Errorf("only arrays are supported for group by")
		}
		var keys []string
		groups := map[string]*CandidateNode{}
		for _, child := range candidate.Content {
			rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(child), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			keyValue, err := getUniqueKeyValue(rhs)
			if err != nil {
				return Context{}, err
			}
			group, exists := groups[keyValue]
			if !exists {
				group = candidate.CreateReplacement(SequenceNode, "!!seq", "")
				keys = append(keys, keyValue)
				groups[keyValue] = group
			}
			group.AddChild(child)
		}
		resultNode := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		for _, k := range keys {
			resultNode.AddChild(groups[k])
		}
		results = append(results, resultNode)
	}
	return context.ChildContext(results), nil
}

// ---------------- first / min / max -----------------

func firstOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode && candidate.Kind != MappingNode {
			continue
		}
		if expressionNode.RHS == nil {
			if len(candidate.Content) > 0 {
				results = append(results, candidate.Content[0])
			}
			continue
		}
		splatted, err := splat(context.SingleChildContext(candidate), traversePreferences{})
		if err != nil {
			return Context{}, err
		}
		for _, child := range splatted.MatchingNodes {
			rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(child), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			found := false
			for _, r := range rhs.MatchingNodes {
				if isTruthyNode(r) {
					found = true
					break
				}
			}
			if found {
				results = append(results, child)
				break
			}
		}
	}
	return context.ChildContext(results), nil
}

func minMaxOperator(d *dataTreeNavigator, context Context, isMax bool) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		var values []*CandidateNode
		if candidate.Kind == SequenceNode {
			values = candidate.Content
		} else if candidate.Kind == MappingNode {
			for i := 1; i < len(candidate.Content); i += 2 {
				values = append(values, candidate.Content[i])
			}
		} else {
			if isMax {
				return Context{}, fmt.Errorf("max only works for arrays and maps, but got %v", candidate.Tag)
			}
			return Context{}, fmt.Errorf("min only works for arrays and maps, but got %v", candidate.Tag)
		}
		if len(values) == 0 {
			continue
		}
		best := values[0]
		for _, v := range values[1:] {
			if v.Kind == MappingNode || best.Kind == MappingNode {
				return Context{}, fmt.Errorf("maps not yet supported for comparison")
			}
			if v.Kind == SequenceNode || best.Kind == SequenceNode {
				return Context{}, fmt.Errorf("arrays not yet supported for comparison")
			}
			c := compareNodesForSort(v, best, context.GetDateTimeLayout())
			if (isMax && c > 0) || (!isMax && c < 0) {
				best = v
			}
		}
		if len(values) == 1 && (best.Kind == MappingNode) {
			results = append(results, best)
			continue
		}
		results = append(results, best)
	}
	return context.ChildContext(results), nil
}

func minOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return minMaxOperator(d, context, false)
}

func maxOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return minMaxOperator(d, context, true)
}

// ---------------- any / all -----------------

func anyOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return Context{}, fmt.Errorf("any only supports arrays, was %v", candidate.Tag)
		}
		result := false
		for _, c := range candidate.Content {
			if isTruthyNode(c) {
				result = true
				break
			}
		}
		results = append(results, createBooleanCandidate(candidate, result))
	}
	return context.ChildContext(results), nil
}

func allOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return Context{}, fmt.Errorf("all only supports arrays, was %v", candidate.Tag)
		}
		result := true
		for _, c := range candidate.Content {
			if !isTruthyNode(c) {
				result = false
				break
			}
		}
		results = append(results, createBooleanCandidate(candidate, result))
	}
	return context.ChildContext(results), nil
}

func anyConditionOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return Context{}, fmt.Errorf("any only supports arrays, was %v", candidate.Tag)
		}
		result := false
		for _, c := range candidate.Content {
			rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(c), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			for _, r := range rhs.MatchingNodes {
				if isTruthyNode(r) {
					result = true
					break
				}
			}
			if result {
				break
			}
		}
		results = append(results, createBooleanCandidate(candidate, result))
	}
	return context.ChildContext(results), nil
}

func allConditionOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != SequenceNode {
			return Context{}, fmt.Errorf("all only supports arrays, was %v", candidate.Tag)
		}
		result := true
		for _, c := range candidate.Content {
			rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(c), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			truthy := false
			for _, r := range rhs.MatchingNodes {
				if isTruthyNode(r) {
					truthy = true
					break
				}
			}
			if !truthy {
				result = false
				break
			}
		}
		results = append(results, createBooleanCandidate(candidate, result))
	}
	return context.ChildContext(results), nil
}

// ---------------- contains -----------------

func containsOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return crossFunction(d, context.ReadOnlyClone(), &ExpressionNode{
		Operation: expressionNode.Operation,
		LHS:       &ExpressionNode{Operation: &Operation{OperationType: selfReferenceOpType}},
		RHS:       expressionNode.RHS,
	}, containsWithNodes, false)
}

func containsArrayElement(array *CandidateNode, item *CandidateNode) (bool, error) {
	for index := 0; index < len(array.Content); index = index + 1 {
		containedInArray, err := contains(array.Content[index], item)
		if err != nil {
			return false, err
		}
		if containedInArray {
			return true, nil
		}
	}
	return false, nil
}

func containsArray(lhs *CandidateNode, rhs *CandidateNode) (bool, error) {
	if rhs.Kind != SequenceNode {
		return containsArrayElement(lhs, rhs)
	}
	for index := 0; index < len(rhs.Content); index = index + 1 {
		itemInArray, err := containsArrayElement(lhs, rhs.Content[index])
		if err != nil {
			return false, err
		}
		if !itemInArray {
			return false, nil
		}
	}
	return true, nil
}

func containsObject(lhs *CandidateNode, rhs *CandidateNode) (bool, error) {
	if rhs.Kind != MappingNode {
		return false, nil
	}
	for index := 0; index+1 < len(rhs.Content); index = index + 2 {
		rhsKey := rhs.Content[index]
		rhsValue := rhs.Content[index+1]
		indexInLHS := findKeyInMap(lhs, rhsKey)
		if indexInLHS < 0 {
			return false, nil
		}
		lhsValue := lhs.Content[indexInLHS+1]
		itemInArray, err := contains(lhsValue, rhsValue)
		if err != nil || !itemInArray {
			return false, err
		}
	}
	return true, nil
}

func containsScalars(lhs *CandidateNode, rhs *CandidateNode) (bool, error) {
	if lhs.Tag == "!!str" {
		return strings.Contains(lhs.Value, rhs.Value), nil
	}
	return lhs.Value == rhs.Value, nil
}

func contains(lhs *CandidateNode, rhs *CandidateNode) (bool, error) {
	switch lhs.Kind {
	case MappingNode:
		return containsObject(lhs, rhs)
	case SequenceNode:
		return containsArray(lhs, rhs)
	case ScalarNode:
		if rhs.Kind != ScalarNode || lhs.Tag != rhs.Tag {
			return false, fmt.Errorf("%v cannot check contained in %v", rhs.Tag, lhs.Tag)
		}
		if lhs.Tag == "!!null" {
			return rhs.Tag == "!!null", nil
		}
		return containsScalars(lhs, rhs)
	}
	return false, fmt.Errorf("%v not yet supported for contains", lhs.Tag)
}

func containsWithNodes(d *dataTreeNavigator, context Context, lhs *CandidateNode, rhs *CandidateNode) (*CandidateNode, error) {
	if lhs.Kind != rhs.Kind {
		return nil, fmt.Errorf("%v cannot check contained in %v", rhs.Tag, lhs.Tag)
	}
	result, err := contains(lhs, rhs)
	if err != nil {
		return nil, err
	}
	return createBooleanCandidate(lhs, result), nil
}

// ---------------- entries -----------------

func entrySeqFor(key *CandidateNode, value *CandidateNode) *CandidateNode {
	var keyKey = &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: "key"}
	var valueKey = &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: "value"}
	candidate := &CandidateNode{Kind: MappingNode, Tag: "!!map"}
	candidate.AddKeyValueChild(keyKey, key)
	candidate.AddKeyValueChild(valueKey, value)
	return candidate
}

func toEntriesFromMap(candidateNode *CandidateNode) *CandidateNode {
	var sequence = candidateNode.CreateReplacementWithComments(SequenceNode, "!!seq", 0)
	var contents = candidateNode.Content
	for index := 0; index+1 < len(contents); index = index + 2 {
		key := contents[index]
		value := contents[index+1]
		sequence.AddChild(entrySeqFor(key, value))
	}
	return sequence
}

func toEntriesfromSeq(candidateNode *CandidateNode) *CandidateNode {
	var sequence = candidateNode.CreateReplacementWithComments(SequenceNode, "!!seq", 0)
	var contents = candidateNode.Content
	for index := 0; index < len(contents); index = index + 1 {
		key := &CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: fmt.Sprintf("%v", index)}
		value := contents[index]
		sequence.AddChild(entrySeqFor(key, value))
	}
	return sequence
}

func toEntriesOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		switch candidate.Kind {
		case MappingNode:
			results = append(results, toEntriesFromMap(candidate))
		case SequenceNode:
			results = append(results, toEntriesfromSeq(candidate))
		default:
			if candidate.Tag != "!!null" {
				return Context{}, fmt.Errorf("%v has no keys", candidate.Tag)
			}
		}
	}
	return context.ChildContext(results), nil
}

func parseEntry(candidateNode *CandidateNode, position int) (*CandidateNode, *CandidateNode, error) {
	prefs := traversePreferences{DontAutoCreate: true}
	keyResults, err := traverseMap(Context{}, candidateNode, createStringScalar("key"), prefs, false)
	if err != nil {
		return nil, nil, err
	} else if len(keyResults) != 1 {
		return nil, nil, fmt.Errorf("expected to find one 'key' entry but found %v in position %v", len(keyResults), position)
	}
	valueResults, err := traverseMap(Context{}, candidateNode, createStringScalar("value"), prefs, false)
	if err != nil {
		return nil, nil, err
	} else if len(valueResults) != 1 {
		return nil, nil, fmt.Errorf("expected to find one 'value' entry but found %v in position %v", len(valueResults), position)
	}
	return keyResults[0], valueResults[0], nil
}

func fromEntries(candidateNode *CandidateNode) (*CandidateNode, error) {
	var node = candidateNode.CopyWithoutContent()
	node.Content = nil
	var contents = candidateNode.Content
	for index := 0; index < len(contents); index = index + 1 {
		key, value, err := parseEntry(contents[index], index)
		if err != nil {
			return nil, err
		}
		node.AddKeyValueChild(key, value)
	}
	node.Kind = MappingNode
	node.Tag = "!!map"
	return node, nil
}

func fromEntriesOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		switch candidate.Kind {
		case SequenceNode:
			mapResult, err := fromEntries(candidate)
			if err != nil {
				return Context{}, err
			}
			results = append(results, mapResult)
		default:
			return Context{}, fmt.Errorf("from entries only runs against arrays")
		}
	}
	return context.ChildContext(results), nil
}

func withEntriesOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	toEntries, err := toEntriesOperator(d, context, expressionNode)
	if err != nil {
		return Context{}, err
	}
	var results []*CandidateNode
	for _, candidate := range toEntries.MatchingNodes {
		splatted, err := splat(context.SingleChildContext(candidate), traversePreferences{})
		if err != nil {
			return Context{}, err
		}
		newResults := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
		for _, s := range splatted.MatchingNodes {
			result, err := d.GetMatchingNodes(splatted.SingleChildContext(s), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			for _, r := range result.MatchingNodes {
				newResults.AddChild(r)
			}
		}
		fromEntries, err := fromEntriesOperator(d, context.SingleChildContext(newResults), expressionNode)
		if err != nil {
			return Context{}, err
		}
		results = append(results, fromEntries.MatchingNodes...)
	}
	return context.ChildContext(results), nil
}

// ---------------- with / del / paths -----------------

func withOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.RHS.Operation.OperationType != blockOpType {
		return Context{}, fmt.Errorf("with must be given a block (;), got %v instead", expressionNode.RHS.Operation.OperationType.Type)
	}
	pathExp := expressionNode.RHS.LHS
	updateContext, err := d.GetMatchingNodes(context, pathExp)
	if err != nil {
		return Context{}, err
	}
	updateExp := expressionNode.RHS.RHS
	for _, candidate := range updateContext.MatchingNodes {
		_, err = d.GetMatchingNodes(updateContext.SingleChildContext(candidate), updateExp)
		if err != nil {
			return Context{}, err
		}
	}
	return context, nil
}

func deleteChildOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	nodesToDelete, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	// need to iterate backwards to ensure correct indices when deleting multiple
	for i := len(nodesToDelete.MatchingNodes) - 1; i >= 0; i-- {
		candidate := nodesToDelete.MatchingNodes[i]
		if candidate.Parent == nil {
			// deleting the root - remove it from the context
			var newMatches []*CandidateNode
			for _, m := range context.MatchingNodes {
				if m != candidate {
					newMatches = append(newMatches, m)
				}
			}
			context = context.ChildContext(newMatches)
			continue
		}
		parentNode := candidate.Parent
		candidatePath := candidate.GetPath()
		if len(candidatePath) == 0 {
			continue
		}
		childPath := candidatePath[len(candidatePath)-1]

		if parentNode.Kind == MappingNode {
			deleteFromMap(candidate.Parent, childPath, candidate)
		} else if parentNode.Kind == SequenceNode {
			deleteFromArray(candidate.Parent, childPath, candidate)
		} else {
			return Context{}, fmt.Errorf("cannot delete nodes from parent of tag %v", parentNode.Tag)
		}
	}
	return context, nil
}

func deleteFromMap(node *CandidateNode, childPath interface{}, candidate *CandidateNode) {
	contents := node.Content
	newContents := make([]*CandidateNode, 0)
	for index := 0; index+1 < len(contents); index = index + 2 {
		key := contents[index]
		value := contents[index+1]
		shouldDelete := (value == candidate || key == candidate)
		if !shouldDelete {
			newContents = append(newContents, key, value)
		}
	}
	node.Content = newContents
}

func deleteFromArray(node *CandidateNode, childPath interface{}, candidate *CandidateNode) {
	contents := node.Content
	newContents := make([]*CandidateNode, 0)
	for index := 0; index < len(contents); index = index + 1 {
		value := contents[index]
		if value != candidate {
			newContents = append(newContents, value)
		}
	}
	node.Content = newContents
	// re-index keys
	for i, c := range node.Content {
		c.Key = createScalarNode(i, fmt.Sprintf("%v", i))
		c.Key.Parent = node
	}
}

func setPathOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.RHS.Operation.OperationType != blockOpType {
		return Context{}, fmt.Errorf("SETPATH must be given a block (;), got %v instead", expressionNode.RHS.Operation.OperationType.Type)
	}
	lhsPathContext, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS.LHS)
	if err != nil {
		return Context{}, err
	}
	if len(lhsPathContext.MatchingNodes) != 1 {
		return Context{}, fmt.Errorf("SETPATH: expected single path but found %v results instead", len(lhsPathContext.MatchingNodes))
	}
	lhsValue := lhsPathContext.MatchingNodes[0]
	if lhsValue.Kind != SequenceNode {
		return Context{}, fmt.Errorf("SETPATH: expected path array, but got %v instead", lhsValue.Tag)
	}
	targetContextValue, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS.RHS)
	if err != nil {
		return Context{}, err
	}
	if len(targetContextValue.MatchingNodes) != 1 {
		return Context{}, fmt.Errorf("SETPATH: expected single value on RHS but found %v", len(targetContextValue.MatchingNodes))
	}
	lhsTraversalTree, err := createTraversalTreeFromPathNodes(lhsValue.Content)
	if err != nil {
		return Context{}, err
	}
	assignmentOp := &Operation{OperationType: assignOpType}
	targetValueRefOp := &Operation{OperationType: referenceOpType, CandidateNode: targetContextValue.MatchingNodes[0]}
	assignmentOpNode := &ExpressionNode{
		Operation: assignmentOp,
		LHS:       lhsTraversalTree,
		RHS:       &ExpressionNode{Operation: targetValueRefOp},
	}
	_, err = d.GetMatchingNodes(context, assignmentOpNode)
	return context, err
}

func createTraversalTreeFromPathNodes(pathNodes []*CandidateNode) (*ExpressionNode, error) {
	path := make([]interface{}, 0, len(pathNodes))
	for _, p := range pathNodes {
		if p.Tag == "!!int" {
			i, err := parseInt(p.Value)
			if err != nil {
				return nil, err
			}
			path = append(path, i)
		} else {
			path = append(path, p.Value)
		}
	}
	return createTraversalTreeForArrayIndices(path), nil
}

func createTraversalTreeForArrayIndices(path []interface{}) *ExpressionNode {
	if len(path) == 0 {
		return &ExpressionNode{Operation: &Operation{OperationType: selfReferenceOpType}}
	}
	var node *ExpressionNode
	for _, p := range path {
		var idxNode *CandidateNode
		switch v := p.(type) {
		case int:
			idxNode = createIntScalar(int64(v))
		default:
			idxNode = createStringScalar(fmt.Sprintf("%v", v))
		}
		collect := &ExpressionNode{
			Operation: &Operation{OperationType: collectOpType},
			RHS:       &ExpressionNode{Operation: &Operation{OperationType: valueOpType, CandidateNode: idxNode}},
		}
		lhs := node
		if lhs == nil {
			lhs = &ExpressionNode{Operation: &Operation{OperationType: selfReferenceOpType}}
		}
		node = &ExpressionNode{
			Operation: &Operation{OperationType: traverseArrayOpType, Preferences: traversePreferences{}},
			LHS:       lhs,
			RHS:       collect,
		}
	}
	return node
}

func delPathsOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	pathArraysContext, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	if len(pathArraysContext.MatchingNodes) != 1 {
		return Context{}, fmt.Errorf("DELPATHS: expected single value but found %v", len(pathArraysContext.MatchingNodes))
	}
	pathArray := pathArraysContext.MatchingNodes[0]
	if pathArray.Kind != SequenceNode {
		return Context{}, fmt.Errorf("DELPATHS: expected a sequence of sequences, but found %v", pathArray.Tag)
	}
	for i, child := range pathArray.Content {
		if child.Kind != SequenceNode {
			return Context{}, fmt.Errorf("DELPATHS: expected entry [%v] to be a sequence, but found %v", i, child.Tag)
		}
		childTraversalExp, err := createTraversalTreeFromPathNodes(child.Content)
		if err != nil {
			return Context{}, err
		}
		deleteChildOpNode := &ExpressionNode{
			Operation: &Operation{OperationType: deleteChildOpType},
			RHS:       childTraversalExp,
		}
		_, err = d.GetMatchingNodes(context, deleteChildOpNode)
		if err != nil {
			return Context{}, err
		}
	}
	return context, nil
}

// ---------------- pivot -----------------

func pivotOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Tag != "!!seq" {
			return Context{}, fmt.Errorf("cannot pivot node of type %v", candidate.Tag)
		}
		if len(candidate.Content) == 0 {
			results = append(results, candidate.CopyWithoutContent())
			continue
		}
		first := candidate.Content[0]
		if first.Tag == "!!seq" {
			maxLen := 0
			for _, c := range candidate.Content {
				if len(c.Content) > maxLen {
					maxLen = len(c.Content)
				}
			}
			result := candidate.CreateReplacement(SequenceNode, "!!seq", "")
			for i := 0; i < maxLen; i++ {
				row := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
				for _, c := range candidate.Content {
					if i < len(c.Content) {
						row.AddChild(c.Content[i])
					} else {
						row.AddChild(createNullScalar())
					}
				}
				result.AddChild(row)
			}
			results = append(results, result)
		} else if first.Tag == "!!map" {
			var keys []string
			seen := map[string]bool{}
			for _, c := range candidate.Content {
				for i := 0; i+1 < len(c.Content); i += 2 {
					k := c.Content[i].Value
					if !seen[k] {
						seen[k] = true
						keys = append(keys, k)
					}
				}
			}
			result := candidate.CreateReplacement(MappingNode, "!!map", "")
			for _, k := range keys {
				row := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
				for _, c := range candidate.Content {
					v := getContentValueByKey(c.Content, k)
					if v == nil {
						v = createNullScalar()
					}
					row.AddChild(v)
				}
				result.AddKeyValueChild(createStringScalar(k), row)
			}
			results = append(results, result)
		} else {
			return Context{}, fmt.Errorf("can only pivot elements of !!seq or !!map types, received %v", first.Tag)
		}
	}
	return context.ChildContext(results), nil
}

// ---------------- split doc / error / eval / reduce / expression -----------------

func splitDocumentOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var index uint
	for _, candidate := range context.MatchingNodes {
		candidate.SetDocument(index)
		index = index + 1
	}
	return context, nil
}

func errorOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	errorMessage := "aborted"
	if len(rhs.MatchingNodes) > 0 {
		errorMessage = rhs.MatchingNodes[0].Value
	}
	return Context{}, fmt.Errorf("%v", errorMessage)
}

func evalOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.RHS == nil {
		return context, nil
	}
	pathExpStrResults, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	var expressions []*ExpressionNode
	for _, pathExpStrResult := range pathExpStrResults.MatchingNodes {
		expressionStrCandidate := pathExpStrResult
		expression, err := ParseExpression(expressionStrCandidate.Value)
		if err != nil {
			return Context{}, err
		}
		expressions = append(expressions, expression)
	}
	var results []*CandidateNode
	for _, matchEl := range context.MatchingNodes {
		for _, expression := range expressions {
			result, err := d.GetMatchingNodes(context.SingleChildContext(matchEl), expression)
			if err != nil {
				return Context{}, err
			}
			results = append(results, result.MatchingNodes...)
		}
	}
	return context.ChildContext(results), nil
}

func reduceOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.LHS.Operation.OperationType != assignVariableOpType {
		return Context{}, fmt.Errorf("reduce must be given a variables assignment, got %v instead", expressionNode.LHS.Operation.OperationType.Type)
	}
	arrayExpNode := expressionNode.LHS.LHS
	array, err := d.GetMatchingNodes(context, arrayExpNode)
	if err != nil {
		return Context{}, err
	}
	variableName := expressionNode.LHS.RHS.Operation.StringValue

	if expressionNode.RHS.Operation.OperationType != blockOpType {
		return Context{}, fmt.Errorf("reduce must be given a block, got %v instead", expressionNode.RHS.Operation.OperationType.Type)
	}

	initialValue, err := d.GetMatchingNodes(context, expressionNode.RHS.LHS)
	if err != nil {
		return Context{}, err
	}
	if len(initialValue.MatchingNodes) != 1 {
		return Context{}, fmt.Errorf("initial value should be a single node, got %v", len(initialValue.MatchingNodes))
	}
	accum := initialValue.MatchingNodes[0]

	for _, candidate := range array.MatchingNodes {
		variable := []*CandidateNode{candidate}
		accumContext := context.SingleChildContext(accum)
		accumContext.SetVariable(variableName, variable)
		newAccum, err := d.GetMatchingNodes(accumContext, expressionNode.RHS.RHS)
		if err != nil {
			return Context{}, err
		}
		if len(newAccum.MatchingNodes) != 1 {
			return Context{}, fmt.Errorf("reduce expression should return a single node, got %v", len(newAccum.MatchingNodes))
		}
		accum = newAccum.MatchingNodes[0]
	}
	return context.SingleChildContext(accum), nil
}

type expressionOpPreferences struct {
	expression string
}

func expressionOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	prefs := expressionNode.Operation.Preferences.(expressionOpPreferences)
	expNode, err := ParseExpression(prefs.expression)
	if err != nil {
		return Context{}, err
	}
	return d.GetMatchingNodes(context, expNode)
}

func explodeOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	for _, candidate := range context.MatchingNodes {
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for _, child := range rhs.MatchingNodes {
			err = explodeNode(child, context)
			if err != nil {
				return Context{}, err
			}
		}
	}
	return context, nil
}

func explodeNode(node *CandidateNode, context Context) error {
	if node.Kind == AliasNode && !ConfiguredYamlPreferences.FixMergeAnchorToSpec {
		explodeWarningOnce.Do(func() {
			logWarn("--yaml-fix-merge-anchor-to-spec is false; causing merge anchors to override the existing values which isn't to the yaml spec. This flag will default to true in late 2025.")
		})
	}
	node.Anchor = ""
	switch node.Kind {
	case SequenceNode:
		for index, contentNode := range node.Content {
			err := explodeNode(contentNode, context)
			if err != nil {
				return err
			}
			_ = index
		}
		return nil
	case AliasNode:
		if node.Alias != nil {
			node.Kind = node.Alias.Kind
			node.Style = node.Alias.Style
			node.Tag = node.Alias.Tag
			node.AddChildren(node.Alias.Content)
			node.Value = node.Alias.Value
			node.Alias = nil
		}
		return nil
	case MappingNode:
		// //check the map has an alias in it
		hasAlias := false
		for index := 0; index < len(node.Content); index = index + 2 {
			keyNode := node.Content[index]
			if keyNode.Tag == "!!merge" {
				hasAlias = true
				break
			}
		}

		if hasAlias {
			if !ConfiguredYamlPreferences.FixMergeAnchorToSpec {
				explodeWarningOnce.Do(func() {
					logWarn("--yaml-fix-merge-anchor-to-spec is false; causing merge anchors to override the existing values which isn't to the yaml spec. This flag will default to true in late 2025.")
				})
			}
			// this is a slow op, which is why we want to check before running it.
			return reconstructAliasedMap(node, context)
		}
		// this map has no aliases, but it's kids might
		for index := 0; index < len(node.Content); index = index + 2 {
			keyNode := node.Content[index]
			valueNode := node.Content[index+1]
			err := explodeNode(keyNode, context)
			if err != nil {
				return err
			}
			err = explodeNode(valueNode, context)
			if err != nil {
				return err
			}
		}
		return nil
	default:
		return nil
	}
}

func reconstructAliasedMap(node *CandidateNode, context Context) error {
	newContent := newOrderedNodeMap()
	keyNodes := map[string]*CandidateNode{}
	setEntry := func(key *CandidateNode, value *CandidateNode) {
		keyNodes[key.Value] = key
		newContent.Set(key.Value, value)
	}
	var applyMerge func(valueNode *CandidateNode) error
	applyMerge = func(valueNode *CandidateNode) error {
		target := valueNode
		if target.Kind == AliasNode {
			target = target.Alias
		}
		if target == nil {
			return nil
		}
		if target.Kind != MappingNode {
			return fmt.Errorf("can only use merge anchors with maps (!!map) or sequences (!!seq) of maps, but got %v", target.Tag)
		}
		exploded := target.Copy()
		if err := explodeNode(exploded, context); err != nil {
			return err
		}
		for i := 0; i+1 < len(exploded.Content); i += 2 {
			setEntry(exploded.Content[i], exploded.Content[i+1])
		}
		return nil
	}

	mergeValue := func(valueNode *CandidateNode) error {
		if valueNode.Kind == SequenceNode {
			for i := len(valueNode.Content) - 1; i >= 0; i-- {
				if err := applyMerge(valueNode.Content[i]); err != nil {
					return err
				}
			}
			return nil
		}
		return applyMerge(valueNode)
	}

	if ConfiguredYamlPreferences.FixMergeAnchorToSpec {
		// merges first (in order), then local keys
		for index := 0; index+1 < len(node.Content); index = index + 2 {
			keyNode := node.Content[index]
			valueNode := node.Content[index+1]
			if keyNode.Tag == "!!merge" {
				if err := mergeValue(valueNode); err != nil {
					return err
				}
			}
		}
		for index := 0; index+1 < len(node.Content); index = index + 2 {
			keyNode := node.Content[index]
			valueNode := node.Content[index+1]
			if keyNode.Tag != "!!merge" {
				if err := explodeNode(valueNode, context); err != nil {
					return err
				}
				setEntry(keyNode, valueNode)
			}
		}
	} else {
		for index := 0; index+1 < len(node.Content); index = index + 2 {
			keyNode := node.Content[index]
			valueNode := node.Content[index+1]
			if keyNode.Tag == "!!merge" {
				if err := mergeValue(valueNode); err != nil {
					return err
				}
			} else {
				if err := explodeNode(valueNode, context); err != nil {
					return err
				}
				setEntry(keyNode, valueNode)
			}
		}
	}
	node.Content = nil
	for _, k := range newContent.keys {
		node.AddKeyValueChild(keyNodes[k], newContent.values[k])
	}
	return nil
}
