func trimSpaceOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, node := range context.MatchingNodes {
		if node.guessTagFromCustomType() != "!!str" {
