func toStringOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, node := range context.MatchingNodes {
		var newStringNode *CandidateNode
		if node.Tag == "!!str" {
			newStringNode = node.CreateReplacement(ScalarNode, "!!str", node.Value)
		} else if node.Kind == ScalarNode {
			newStringNode = node.CreateReplacement(ScalarNode, "!!str", node.Value)
			newStringNode.Style = DoubleQuotedStyle
		} else {
			result, err := encodeToString(node, encoderPreferences{format: YamlFormat, indent: ConfiguredYamlPreferences.Indent})
			if err != nil {
				return Context{}, err
			}
			result = strings.TrimSuffix(result, "\n")
			newStringNode = node.CreateReplacement(ScalarNode, "!!str", result)
		}
		results = append(results, newStringNode)
