func stringInterpolationOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	inner := expressionNode.Operation.Preferences.(string)
	if len(context.MatchingNodes) == 0 {
		value, err := interpolate(d, context, nil, inner)
		if err != nil {
			return Context{}, err
		}
		return context.SingleChildContext(createStringScalar(value)), nil
	}
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		value, err := interpolate(d, context, candidate, inner)
		if err != nil {
			return Context{}, err
		}
		results = append(results, createStringScalar(value))
	}
	return context.ChildContext(results), nil
}

func interpolate(d *dataTreeNavigator, context Context, candidate *CandidateNode, raw string) (string, error) {
	var sb strings.Builder
	i := 0
	for i < len(raw) {
		c := raw[i]
		if c == '\\' && i+1 < len(raw) {
			if raw[i+1] == '(' {
				// find matching close paren
				depth := 1
				j := i + 2
				inString := false
				for j < len(raw) && depth > 0 {
					ch := raw[j]
					if inString {
						if ch == '\\' {
							j++
						} else if ch == '"' {
							inString = false
						}
					} else {
						if ch == '"' {
							inString = true
						} else if ch == '(' {
							depth++
						} else if ch == ')' {
							depth--
							if depth == 0 {
								break
							}
						}
					}
					j++
				}
				if depth != 0 {
					logWarn("unclosed interpolation string, skipping interpolation")
					return unescapeString(raw), nil
				}
				exprStr := raw[i+2 : j]
				expr, err := ParseExpression(exprStr)
				if err != nil {
					return "", err
				}
				var ctx Context
				if candidate != nil {
					ctx = context.SingleChildContext(candidate)
				} else {
					ctx = context.ChildContext(nil)
				}
				result, err := d.GetMatchingNodes(ctx.ReadOnlyClone(), expr)
				if err != nil {
					return "", err
				}
				if len(result.MatchingNodes) > 0 {
					str, err := nodeToInterpolatedString(result.MatchingNodes[0])
					if err != nil {
						return "", err
					}
					sb.WriteString(str)
				}
				i = j + 1
				continue
			}
			sb.WriteString(unescapeString(raw[i : i+2]))
			i += 2
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String(), nil
}

func nodeToInterpolatedString(node *CandidateNode) (string, error) {
	if node.Kind == ScalarNode {
		return node.Value, nil
	}
	result, err := encodeToString(node, encoderPreferences{format: YamlFormat, indent: ConfiguredYamlPreferences.Indent})
	if err != nil {
		return "", err
	}
	return strings.TrimSuffix(result, "\n"), nil
}
