	splitStr := ""
	rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	if len(rhs.MatchingNodes) != 0 {
		splitStr = rhs.MatchingNodes[0].Value
	}
	var results []*CandidateNode
	for _, node := range context.MatchingNodes {
		if node.Tag == "!!null" {
			continue
		}
		if node.guessTagFromCustomType() != "!!str" {
			return Context{}, fmt.Errorf("cannot split %v, can only split strings", node.Tag)
		}
		kind, tag, content := split(node.Value, splitStr)
		result := node.CreateReplacement(kind, tag, "")
		result.AddChildren(content)
		results = append(results, result)
	}
	return context.ChildContext(results), nil
}

func split(value string, spliter string) (Kind, string, []*CandidateNode) {
	var contents []*CandidateNode
	if value != "" {
		var newStrings = strings.Split(value, spliter)
		contents = make([]*CandidateNode, len(newStrings))
		for index, str := range newStrings {
			contents[index] = &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: str}
		}
	}
	return SequenceNode, "!!seq", contents
}

func toNumberOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		if candidate.Kind != ScalarNode {
			return Context{}, fmt.Errorf("cannot convert node at path %v of tag %v to number", candidate.GetNicePath(), candidate.Tag)
		}
		if candidate.Tag == "!!int" || candidate.Tag == "!!float" {
			results = append(results, candidate)
			continue
		}
		node, err := parseSnippet(candidate.Value)
		if err != nil || (node.Tag != "!!int" && node.Tag != "!!float") || candidate.Value == "" {
			return Context{}, fmt.Errorf("cannot convert node value [%v] at path %v of tag %v to number", candidate.Value, candidate.GetNicePath(), candidate.Tag)
		}
		result := candidate.CreateReplacement(ScalarNode, node.Tag, candidate.Value)
		results = append(results, result)
	}
	return context.ChildContext(results), nil
}

// ---------------- string interpolation -----------------

var ConfiguredStringInterpolation = true

func stringInterpolationOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	inner := expressionNode.Operation.Preferences.(string)
	if len(context.MatchingNodes) == 0 {
		value, err := interpolate(d, context, nil, inner)
		if err != nil {
			return Context{}, err
		}
		return context.SingleChildContext(createStringScalar(value)), nil
	}
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		value, err := interpolate(d, context, candidate, inner)
		if err != nil {
			return Context{}, err
		}
		results = append(results, createStringScalar(value))
	}
	return context.ChildContext(results), nil
}

func interpolate(d *dataTreeNavigator, context Context, candidate *CandidateNode, raw string) (string, error) {
	var sb strings.Builder
	i := 0
	for i < len(raw) {
		c := raw[i]
		if c == '\\' && i+1 < len(raw) {
			if raw[i+1] == '(' {
				// find matching close paren
				depth := 1
				j := i + 2
				inString := false
				for j < len(raw) && depth > 0 {
					ch := raw[j]
					if inString {
						if ch == '\\' {
							j++
						} else if ch == '"' {
							inString = false
						}
					} else {
						if ch == '"' {
							inString = true
						} else if ch == '(' {
							depth++
						} else if ch == ')' {
							depth--
							if depth == 0 {
								break
							}
						}
					}
					j++
				}
				if depth != 0 {
					logWarn("unclosed interpolation string, skipping interpolation")
					return unescapeString(raw), nil
				}
				exprStr := raw[i+2 : j]
				expr, err := ParseExpression(exprStr)
				if err != nil {
					return "", err
				}
				var ctx Context
				if candidate != nil {
					ctx = context.SingleChildContext(candidate)
				} else {
					ctx = context.ChildContext(nil)
				}
				result, err := d.GetMatchingNodes(ctx.ReadOnlyClone(), expr)
				if err != nil {
					return "", err
				}
				if len(result.MatchingNodes) > 0 {
					str, err := nodeToInterpolatedString(result.MatchingNodes[0])
					if err != nil {
						return "", err
					}
					sb.WriteString(str)
				}
				i = j + 1
				continue
			}
			sb.WriteString(unescapeString(raw[i : i+2]))
			i += 2
			continue
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String(), nil
}

func nodeToInterpolatedString(node *CandidateNode) (string, error) {
	if node.Kind == ScalarNode {
		return node.Value, nil
	}
	result, err := encodeToString(node, encoderPreferences{format: YamlFormat, indent: ConfiguredYamlPreferences.Indent})
	if err != nil {
		return "", err
	}
	return strings.TrimSuffix(result, "\n"), nil
}
