	prefs JsonPreferences
}

func NewJSONEncoder(prefs JsonPreferences) Encoder {
	return &jsonEncoder{prefs: prefs}
}

func (je *jsonEncoder) CanHandleAliases() bool                                    { return false }
func (je *jsonEncoder) PrintDocumentSeparator(writer io.Writer) error             { return nil }
func (je *jsonEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }

