			buf.WriteString(s[start:i])
			buf.WriteString("\\u202")
			buf.WriteByte(hexChars[c&0xF])
			i += size
			start = i
			continue
		}
		i += size
	}
	buf.WriteString(s[start:])
	buf.WriteByte('"')
}

func writeJSONIndent(buf *bytes.Buffer, indent string, depth int) {
	if indent == "" {
		return
	}
	buf.WriteByte('\n')
	for i := 0; i < depth; i++ {
		buf.WriteString(indent)
	}
}

func writeJSONValue(buf *bytes.Buffer, node *CandidateNode, indent string, depth int, visiting map[*CandidateNode]bool) error {
	switch node.Kind {
	case AliasNode:
		if node.Alias == nil {
			buf.WriteString("null")
			return nil
		}
		if visiting[node.Alias] {
			return errors.New("json: unsupported value: encountered a cycle")
		}
		visiting[node.Alias] = true
		err := writeJSONValue(buf, node.Alias, indent, depth, visiting)
		delete(visiting, node.Alias)
		return err
	case ScalarNode:
		return writeJSONScalar(buf, node)
	case MappingNode:
		if len(node.Content) == 0 {
			buf.WriteString("{}")
			return nil
		}
		buf.WriteByte('{')
		first := true
		for i := 0; i+1 < len(node.Content); i += 2 {
			if !first {
				buf.WriteByte(',')
			}
			first = false
			writeJSONIndent(buf, indent, depth+1)
			keyNode := node.Content[i]
			writeJSONString(buf, keyNode.Value)
			buf.WriteByte(':')
			if indent != "" {
				buf.WriteByte(' ')
			}
			if err := writeJSONValue(buf, node.Content[i+1], indent, depth+1, visiting); err != nil {
				return err
			}
		}
		writeJSONIndent(buf, indent, depth)
		buf.WriteByte('}')
		return nil
	case SequenceNode:
		if len(node.Content) == 0 {
			buf.WriteString("[]")
			return nil
		}
		buf.WriteByte('[')
