		dec.pos++
		node := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
		dec.skipWS()
		if dec.pos < len(dec.data) && dec.data[dec.pos] == ']' {
			dec.pos++
			return node, nil
		}
