			if err != nil {
				return nil, err
			}
			value.Parent = node
			value.Key = createIntScalar(int64(len(node.Content)))
			value.Key.Parent = node
			node.Content = append(node.Content, value)
			dec.skipWS()
			if dec.pos >= len(dec.data) {
				return nil, dec.errorf("unexpected end of JSON input")
			}
			if dec.data[dec.pos] == ',' {
				dec.pos++
				continue
			}
			if dec.data[dec.pos] == ']' {
				dec.pos++
				return node, nil
			}
			return nil, dec.errorf("invalid character '%c' after array element", dec.data[dec.pos])
		}
	case c == '"':
		s, err := dec.parseString()
		if err != nil {
			return nil, err
		}
		return &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: s}, nil
	case c == 't':
		if bytes.HasPrefix(dec.data[dec.pos:], []byte("true")) {
			dec.pos += 4
			return &CandidateNode{Kind: ScalarNode, Tag: "!!bool", Value: "true"}, nil
		}
		return nil, dec.errorf("invalid character %c as true", dec.data[dec.pos])
	case c == 'f':
		if bytes.HasPrefix(dec.data[dec.pos:], []byte("false")) {
			dec.pos += 5
			return &CandidateNode{Kind: ScalarNode, Tag: "!!bool", Value: "false"}, nil
		}
		return nil, dec.errorf("invalid character %c as false", dec.data[dec.pos])
	case c == 'n':
		if bytes.HasPrefix(dec.data[dec.pos:], []byte("null")) {
			dec.pos += 4
			return &CandidateNode{Kind: ScalarNode, Tag: "!!null", Value: "null"}, nil
		}
		return nil, dec.errorf("invalid character %c as null", dec.data[dec.pos])
	case c == '-' || (c >= '0' && c <= '9'):
		start := dec.pos
		dec.pos++
		for dec.pos < len(dec.data) {
			ch := dec.data[dec.pos]
			if (ch >= '0' && ch <= '9') || ch == '.' || ch == 'e' || ch == 'E' || ch == '+' || ch == '-' {
				dec.pos++
			} else {
				break
			}
		}
		numStr := string(dec.data[start:dec.pos])
		f, err := strconv.ParseFloat(numStr, 64)
		if err != nil {
			return nil, err
		}
		if f == math.Trunc(f) && f >= -9.2233720368547758e18 && f < 9.2233720368547758e18 {
			return &CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: strconv.FormatInt(int64(f), 10)}, nil
		}
		s, ferr := formatJSONFloat(f)
		if ferr != nil {
			return nil, ferr
		}
		return &CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: s}, nil
	}
	return nil, dec.errorf("invalid character '%c' looking for beginning of value", c)
}

func (dec *jsonDecoder) parseString() (string, error) {
	// assumes data[pos] == '"'
	dec.pos++
	var sb strings.Builder
	for dec.pos < len(dec.data) {
		c := dec.data[dec.pos]
		if c == '"' {
			dec.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			dec.pos++
			if dec.pos >= len(dec.data) {
				break
			}
			e := dec.data[dec.pos]
			switch e {
			case '"', '\\', '/':
				sb.WriteByte(e)
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case 'u':
				if dec.pos+4 >= len(dec.data) {
					return "", dec.errorf("unexpected end of JSON input")
				}
				r, err := strconv.ParseUint(string(dec.data[dec.pos+1:dec.pos+5]), 16, 32)
				if err != nil {
					return "", dec.errorf("invalid escape sequence")
				}
				dec.pos += 4
				ru := rune(r)
				if ru >= 0xD800 && ru < 0xDC00 && dec.pos+6 < len(dec.data) && dec.data[dec.pos+1] == '\\' && dec.data[dec.pos+2] == 'u' {
					r2, err2 := strconv.ParseUint(string(dec.data[dec.pos+3:dec.pos+7]), 16, 32)
					if err2 == nil && r2 >= 0xDC00 && r2 < 0xE000 {
						ru = ((ru - 0xD800) << 10) + (rune(r2) - 0xDC00) + 0x10000
						dec.pos += 6
					}
				}
				sb.WriteRune(ru)
			default:
				return "", dec.errorf("invalid escape sequence")
			}
			dec.pos++
			continue
		}
		sb.WriteByte(c)
		dec.pos++
	}
	return "", dec.errorf("unexpected end of JSON input")
}
