var hasOnlyOneNewLine = regexp.MustCompile("[^\n].*\n$")
var endWithNewLine = regexp.MustCompile(".*\n$")
var chomper = regexp.MustCompile("\n+$")

func encodeOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	preferences := expressionNode.Operation.Preferences.(encoderPreferences)
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		stringValue, err := encodeToString(candidate, preferences)
		if err != nil {
			return Context{}, err
		}
		originalList := context.GetVariable("decoded: " + candidate.GetKey())
		if originalList != nil && len(originalList.nodes) > 0 && hasOnlyOneNewLine.MatchString(stringValue) {
			original := originalList.nodes[0]
			if !endWithNewLine.MatchString(original.Value) {
				stringValue = chomper.ReplaceAllString(stringValue, "")
			}
		}
		if (preferences.format == JSONFormat && preferences.indent == 0) ||
			preferences.format == CSVFormat ||
			preferences.format == TSVFormat {
			stringValue = chomper.ReplaceAllString(stringValue, "")
		}
		results = append(results, candidate.CreateReplacement(ScalarNode, "!!str", stringValue))
