func loadWithDecoder(filename string, decoder Decoder) (*CandidateNode, error) {
	if decoder == nil {
		return nil, fmt.Errorf("could not load %s", filename)
	}
	file, err := os.Open(filename) // #nosec
	if err != nil {
		return nil, err
	}
	defer file.Close()
	if err := decoder.Init(file); err != nil {
		return nil, err
	}
	var docs []*CandidateNode
	for {
		node, err := decoder.Decode()
		if err == io.EOF {
			break
		} else if err != nil {
			return nil, err
		}
		docs = append(docs, node)
	}
	if len(docs) == 0 {
		return &CandidateNode{Kind: ScalarNode, Tag: "!!null"}, nil
	} else if len(docs) == 1 {
		return docs[0], nil
	}
	sequenceNode := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
	for _, doc := range docs {
		sequenceNode.AddChild(doc)
	}
	return sequenceNode, nil
}

func loadOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if ConfiguredSecurityPreferences.DisableFileOps {
		return Context{}, fmt.Errorf("file operations have been disabled")
	}
	loadPrefs := expressionNode.Operation.Preferences.(loadPrefs)
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if len(rhs.MatchingNodes) == 0 {
			return Context{}, fmt.Errorf("filename expression returned nil")
		}
		nameCandidateNode := rhs.MatchingNodes[0]
		filename := nameCandidateNode.Value
		var contentsCandidate *CandidateNode
		if loadPrefs.loadAsString {
			contentsCandidate, err = loadString(filename)
		} else {
			var decoder Decoder
			decoder, err = createDecoder(loadPrefs.format)
			if err == nil {
				if loadPrefs.format == YamlFormat {
					p := ConfiguredYamlPreferences
					p.LeadingContentPreProcessing = false
					decoder = NewYamlDecoder(p)
				}
				contentsCandidate, err = loadWithDecoder(filename, decoder)
			}
		}
		if err != nil {
			return Context{}, fmt.Errorf("failed to load %v: %w", filename, err)
		}
		results = append(results, contentsCandidate)
	}
	return context.ChildContext(results), nil
}
