	if c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
		return true
	}
	if !first && c >= '0' && c <= '9' {
		return true
	}
	return false
}

func envsubst(input string, prefs envOpPreferences) (string, error) {
	var sb strings.Builder
	var errs []string
	addErr := func(msg string) bool {
		errs = append(errs, msg)
		return prefs.FailFast
	}
	lookup := func(name string) (string, bool) {
		return os.LookupEnv(name)
	}
	checkVar := func(name string, value string, set bool) bool {
		if !set && prefs.NoUnset {
			return addErr(fmt.Sprintf("variable ${%v} not set", name))
		}
		if set && value == "" && prefs.NoEmpty {
			return addErr(fmt.Sprintf("variable ${%v} set but empty", name))
		}
		return false
	}
	i := 0
	for i < len(input) {
		c := input[i]
		if c != '$' || i+1 >= len(input) {
			sb.WriteByte(c)
			i++
			continue
		}
		next := input[i+1]
		if next == '$' {
			sb.WriteByte('$')
			i += 2
			continue
		}
		if next == '{' {
			end := strings.IndexByte(input[i+2:], '}')
			if end < 0 {
				sb.WriteString(input[i:])
				break
			}
			expr := input[i+2 : i+2+end]
			i = i + 2 + end + 1
			// parse name
			j := 0
			for j < len(expr) && isVarNameChar(expr[j], j == 0) {
				j++
			}
			name := expr[:j]
			rest := expr[j:]
			value, set := lookup(name)
			switch {
			case rest == "":
				if checkVar(name, value, set) {
					return "", fmt.Errorf("%v", strings.Join(errs, "\n"))
				}
				sb.WriteString(value)
			case strings.HasPrefix(rest, ":-"):
				if !set || value == "" {
					sb.WriteString(rest[2:])
				} else {
					sb.WriteString(value)
				}
			case strings.HasPrefix(rest, "-"):
				if !set {
					sb.WriteString(rest[1:])
				} else {
					sb.WriteString(value)
				}
			case strings.HasPrefix(rest, ":="):
				if !set || value == "" {
					sb.WriteString(rest[2:])
				} else {
					sb.WriteString(value)
				}
			case strings.HasPrefix(rest, "="):
				if !set {
					sb.WriteString(rest[1:])
				} else {
					sb.WriteString(value)
				}
			case strings.HasPrefix(rest, ":+"):
				if set && value != "" {
					sb.WriteString(rest[2:])
				}
			case strings.HasPrefix(rest, "+"):
				if set {
					sb.WriteString(rest[1:])
				}
			default:
				sb.WriteString(value)
			}
			continue
		}
		if isVarNameChar(next, true) {
			j := i + 1
			for j < len(input) && isVarNameChar(input[j], j == i+1) {
				j++
			}
			name := input[i+1 : j]
			value, set := lookup(name)
			if checkVar(name, value, set) {
				return "", fmt.Errorf("%v", strings.Join(errs, "\n"))
			}
			sb.WriteString(value)
			i = j
			continue
		}
		sb.WriteByte(c)
		i++
	}
	if len(errs) > 0 {
		return "", fmt.Errorf("%v", strings.Join(errs, "\n"))
	}
	return sb.String(), nil
}

func systemOperator(d *dataTreeNavigator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if !ConfiguredSecurityPreferences.EnableSystemOperator {
		logWarn("system operator is disabled, use --security-enable-system-operator flag to enable")
		var results []*CandidateNode
		for _, candidate := range context.MatchingNodes {
			results = append(results, candidate.CreateReplacement(ScalarNode, "!!null", "null"))
		}
		return context.ChildContext(results), nil
	}
	var results []*CandidateNode
	for _, candidate := range context.MatchingNodes {
		var command string
		var args []string
		rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if expressionNode.RHS.Operation.OperationType == blockOpType {
			cmdNodes, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(candidate), expressionNode.RHS.LHS)
			if err != nil {
				return Context{}, err
			}
			if len(cmdNodes.MatchingNodes) > 0 {
				command = cmdNodes.MatchingNodes[0].Value
			}
			argNodes, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(candidate), expressionNode.RHS.RHS)
			if err != nil {
				return Context{}, err
			}
			for _, a := range argNodes.MatchingNodes {
				if a.Kind == SequenceNode {
					for _, c := range a.Content {
						args = append(args, c.Value)
					}
				} else {
					args = append(args, a.Value)
				}
			}
		} else if len(rhs.MatchingNodes) > 0 {
			command = rhs.MatchingNodes[0].Value
		}
		if command == "" {
			return Context{}, fmt.Errorf("system operator requires a command")
		}
		stdin, err := encodeToString(candidate, encoderPreferences{format: YamlFormat, indent: 2})
		if err != nil {
			return Context{}, err
		}
		cmd := exec.Command(command, args...)
		cmd.Stdin = strings.NewReader(stdin)
		var stderr bytes.Buffer
		cmd.Stderr = &stderr
		output, err := cmd.Output()
		if err != nil {
			return Context{}, fmt.Errorf("system command '%v' failed: %w\nstderr: %v", command, err, stderr.String())
		}
		result := strings.TrimSuffix(string(output), "\n")
		results = append(results, candidate.CreateReplacement(ScalarNode, "!!str", result))
	}
	return context.ChildContext(results), nil
}
