}

func (sp *singlePrinterWriter) GetWriter(node *CandidateNode) (*bufio.Writer, error) {
	return sp.bufferedWriter, nil
}

type multiPrintWriter struct {
	treeNavigator *dataTreeNavigator
	nameExpression *ExpressionNode
	extension      string
	index          int
}

func NewMultiPrinterWriter(expression *ExpressionNode, format string) PrinterWriter {
	extension := "yml"
	switch format {
	case JSONFormat:
		extension = "json"
	case PropertiesFormat:
		extension = "properties"
	case YamlFormat:
		extension = "yml"
	default:
		extension = format
	}
	return &multiPrintWriter{
		nameExpression: expression,
		extension:      extension,
		treeNavigator:  &dataTreeNavigator{},
		index:          0,
	}
}

func (p *multiPrintWriter) GetWriter(node *CandidateNode) (*bufio.Writer, error) {
	name := ""
	indexVariableNode := CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: fmt.Sprintf("%v", p.index)}
	context := Context{MatchingNodes: []*CandidateNode{node}, Variables: map[string]*varValue{}}
	context.SetVariable("index", []*CandidateNode{&indexVariableNode})
	result, err := p.treeNavigator.GetMatchingNodes(context, p.nameExpression)
	if err != nil {
		return nil, err
	}
	if len(result.MatchingNodes) > 0 {
		name = result.MatchingNodes[0].Value
	}
	var extensionRegexp = regexp.MustCompile(`\.[a-zA-Z0-9]+$`)
	if !extensionRegexp.MatchString(name) {
		name = fmt.Sprintf("%v.%v", name, p.extension)
	}
	err = os.MkdirAll(filepath.Dir(name), 0750)
	if err != nil {
		return nil, err
	}
	f, err := os.Create(name)
	if err != nil {
		return nil, err
	}
	p.index = p.index + 1
	return bufio.NewWriter(f), nil
}

