	'è': "e", 'é': "e", 'ê': "e", 'ë': "e", 'ì': "i", 'í': "i", 'î': "i", 'ï': "i", 'ñ': "n", 'ò': "o", 'ó': "o",
	'ô': "o", 'õ': "o", 'ö': "o", 'ù': "u", 'ú': "u", 'û': "u", 'ü': "u", 'ý': "y", 'ÿ': "y",
	'ﬁ': "fi", 'ﬂ': "fl", '²': "2", '³': "3", '¹': "1",
}

func (pe *shellVariablesEncoder) appendPath(cookedPath string, rawKey interface{}) string {
	rawKeyString := fmt.Sprint(rawKey)
	if rawKeyString == "" {
		rawKeyString = "_"
	}
	var sb strings.Builder
	for _, r := range rawKeyString {
		if d, ok := latinDecompose[r]; ok {
			sb.WriteString(d)
			continue
		}
		if r < 32 || r > 126 {
			continue
		}
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') {
			sb.WriteRune(r)
		} else {
			sb.WriteRune('_')
		}
	}
	cookedKey := sb.String()
	if cookedPath == "" {
		firstRune, _ := utf8.DecodeRuneInString(cookedKey)
		if !((firstRune >= 'a' && firstRune <= 'z') || (firstRune >= 'A' && firstRune <= 'Z') || firstRune == '_') {
			return "_" + cookedKey
		}
		return cookedKey
	}
	return cookedPath + pe.prefs.KeySeparator + cookedKey
}

func quoteShellValue(value string) string {
	needsQuoting := false
	for _, r := range value {
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_') {
			needsQuoting = true
			break
		}
	}
	if needsQuoting {
		return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'"
	}
	return value
}

func mapKeysToStrings(node *CandidateNode) {
	if node.Kind == MappingNode {
		for index, child := range node.Content {
			if index%2 == 0 {
				child.Tag = "!!str"
			}
		}
	}
	for _, child := range node.Content {
		mapKeysToStrings(child)
	}
}

