}

func (pe *propertiesEncoder) CanHandleAliases() bool                        { return false }
func (pe *propertiesEncoder) PrintDocumentSeparator(writer io.Writer) error { return nil }

func (pe *propertiesEncoder) PrintLeadingContent(writer io.Writer, content string) error {
	reader := strings.NewReader(content)
	buf := new(bytes.Buffer)
	_, _ = buf.ReadFrom(reader)
	lines := strings.SplitAfter(buf.String(), "\n")
	for _, readline := range lines {
		if readline == "" {
			continue
		}
		if strings.Contains(readline, docSeparatorPlaceholder) {
			continue
		}
		if strings.HasPrefix(strings.TrimSpace(readline), "#") || strings.TrimSpace(readline) == "" {
			if err := writeString(writer, readline); err != nil {
				return err
			}
		} else if !strings.HasPrefix(readline, "%") {
			if err := writeString(writer, "# "+readline); err != nil {
				return err
			}
		}
		if !strings.HasSuffix(readline, "\n") {
			if err := writeString(writer, "\n"); err != nil {
				return err
			}
		}
	}
	return nil
}

type propEntry struct {
	key      string
	value    string
	comments []string
}

type propsWriter struct {
	keys     []string
	values   map[string]string
	comments map[string][]string
}

func (p *propsWriter) setComments(key string, comments []string) {
	p.comments[key] = comments
}

func (p *propsWriter) set(key, value string) {
	if _, ok := p.values[key]; !ok {
		p.keys = append(p.keys, key)
	}
	p.values[key] = value
}

func encodePropUtf8(s string, special string) string {
	var v strings.Builder
	for pos, r := range s {
		switch {
		case pos == 0 && (r == ' ' || r == '\t' || r == '\f'):
			v.WriteString("\\" + string(r))
		default:
			v.WriteString(propEscape(r, special))
		}
	}
	return v.String()
}

func propEscape(r rune, special string) string {
	switch r {
	case '\f':
		return "\\f"
	case '\n':
		return "\\n"
	case '\r':
		return "\\r"
	case '\t':
		return "\\t"
	case '\\':
		return "\\\\"
	default:
		if strings.ContainsRune(special, r) {
			return "\\" + string(r)
		}
		return string(r)
	}
}

func (p *propsWriter) write(w io.Writer, sep string) error {
	n := 0
	for _, key := range p.keys {
		value := p.values[key]
		if comments, ok := p.comments[key]; ok {
			allEmpty := true
			for _, c := range comments {
				if c != "" {
					allEmpty = false
					break
				}
			}
			if !allEmpty {
				if len(comments) > 0 && n > 0 {
					if _, err := fmt.Fprintln(w); err != nil {
						return err
					}
				}
				for _, c := range comments {
					if _, err := fmt.Fprintf(w, "#%s\n", c); err != nil {
						return err
					}
				}
			}
		}
		line := fmt.Sprintf("%s%s%s\n", encodePropUtf8(key, " :"), sep, encodePropUtf8(value, ""))
		if _, err := io.WriteString(w, line); err != nil {
			return err
		}
		n += len(line)
	}
	return nil
}

func (pe *propertiesEncoder) Encode(writer io.Writer, node *CandidateNode) error {
	if node.Kind == ScalarNode {
		return writeString(writer, node.Value+"\n")
	}
	mapKeysToStrings(node)
	p := &propsWriter{values: map[string]string{}, comments: map[string][]string{}}
	err := pe.doEncode(p, node, "", nil)
	if err != nil {
		return err
	}
	return p.write(writer, pe.prefs.KeyValueSeparator)
}

func propHeadAndLineComment(node *CandidateNode) string {
	return strings.Replace(node.HeadComment, "#", "", 1) + strings.Replace(node.LineComment, "#", "", 1)
}

func (pe *propertiesEncoder) doEncode(p *propsWriter, node *CandidateNode, path string, keyNode *CandidateNode) error {
	comments := ""
	if keyNode != nil {
		comments = propHeadAndLineComment(keyNode)
	}
	comments = comments + propHeadAndLineComment(node)
	commentsWithSpaces := strings.ReplaceAll(comments, "\n", "\n ")
	p.setComments(path, strings.Split(commentsWithSpaces, "\n"))

	switch node.Kind {
	case ScalarNode:
		var nodeValue string
		if pe.prefs.UnwrapScalar || !strings.Contains(node.Value, " ") {
			nodeValue = node.Value
		} else {
			nodeValue = fmt.Sprintf("%q", node.Value)
		}
		p.set(path, nodeValue)
		return nil
	case SequenceNode:
		for index, child := range node.Content {
			childPath := pe.appendPath(path, index)
			if pe.prefs.UseArrayBrackets {
				childPath = fmt.Sprintf("%v[%v]", path, index)
			}
			if err := pe.doEncode(p, child, childPath, nil); err != nil {
				return err
			}
		}
		return nil
	case MappingNode:
		for index := 0; index+1 < len(node.Content); index = index + 2 {
			key := node.Content[index]
			value := node.Content[index+1]
			if err := pe.doEncode(p, value, pe.appendPath(path, key.Value), key); err != nil {
				return err
			}
		}
		return nil
	case AliasNode:
		return pe.doEncode(p, node.Alias, path, nil)
	}
	return fmt.Errorf("unsupported node %v", node.Tag)
}

func (pe *propertiesEncoder) appendPath(path string, key interface{}) string {
	if path == "" {
		return fmt.Sprintf("%v", key)
	}
	return fmt.Sprintf("%v.%v", path, key)
}

// ---------------- csv -----------------

type CsvPreferences struct {
	Separator rune
	AutoParse bool
}

var ConfiguredCsvPreferences = CsvPreferences{Separator: ',', AutoParse: true}
var ConfiguredTsvPreferences = CsvPreferences{Separator: '\t', AutoParse: true}

type csvEncoder struct {
	separator rune
}

func NewCsvEncoder(prefs CsvPreferences) Encoder {
	return &csvEncoder{separator: prefs.Separator}
}

func (e *csvEncoder) CanHandleAliases() bool                                    { return false }
func (e *csvEncoder) PrintDocumentSeparator(writer io.Writer) error             { return nil }
func (e *csvEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }

func (e *csvEncoder) writeRow(csvWriter *csv.Writer, row []string) error {
	err := csvWriter.Write(row)
	if err != nil {
		return err
	}
	csvWriter.Flush()
	return csvWriter.Error()
}

func (e *csvEncoder) encodeRow(csvWriter *csv.Writer, encodedRow []*CandidateNode) error {
	stringValues := make([]string, len(encodedRow))
	for i, child := range encodedRow {
		if child.Kind != ScalarNode {
			return fmt.Errorf("csv encoding only works for arrays of scalars (string/numbers/booleans), child[%v] is a %v", i, child.Tag)
		}
		stringValues[i] = child.Value
	}
	return e.writeRow(csvWriter, stringValues)
}

func (e *csvEncoder) encodeArrays(csvWriter *csv.Writer, content []*CandidateNode) error {
	for i, child := range content {
		if child.Kind != SequenceNode {
			return fmt.Errorf("csv encoding only works for arrays of scalars (string/numbers/booleans), child[%v] is a %v", i, child.Tag)
		}
		err := e.encodeRow(csvWriter, child.Content)
		if err != nil {
			return err
		}
	}
	return nil
}

func (e *csvEncoder) extractHeader(child *CandidateNode) ([]*CandidateNode, error) {
	if child.Kind != MappingNode {
		return nil, fmt.Errorf("csv object encoding only works for arrays of flat objects (string key => string/numbers/boolean value), child[0] is a %v", child.Tag)
	}
	mapKeys := getMapKeys(child)
	return mapKeys.Content, nil
}

func (e *csvEncoder) createChildRow(child *CandidateNode, headers []*CandidateNode) []*CandidateNode {
	childRow := make([]*CandidateNode, 0)
	for _, header := range headers {
		keyIndex := findKeyInMap(child, header)
		value := createScalarNode(nil, "")
		if keyIndex != -1 {
			value = child.Content[keyIndex+1]
		}
		childRow = append(childRow, value)
	}
	return childRow
}

func (e *csvEncoder) encodeObjects(csvWriter *csv.Writer, content []*CandidateNode) error {
	headers, err := e.extractHeader(content[0])
	if err != nil {
		return err
	}
	err = e.encodeRow(csvWriter, headers)
	if err != nil {
		return err
	}
	for i, child := range content {
		if child.Kind != MappingNode {
			return fmt.Errorf("csv object encoding only works for arrays of flat objects (string key => string/numbers/boolean value), child[%v] is a %v", i, child.Tag)
		}
		row := e.createChildRow(child, headers)
		err = e.encodeRow(csvWriter, row)
		if err != nil {
			return err
		}
	}
	return nil
}

func (e *csvEncoder) Encode(writer io.Writer, node *CandidateNode) error {
	if node.Kind == ScalarNode {
		return writeString(writer, node.Value+"\n")
	}
	csvWriter := csv.NewWriter(writer)
	csvWriter.Comma = e.separator

	if node.Kind != SequenceNode {
		return fmt.Errorf("csv encoding only works for arrays, got: %v", node.Tag)
	} else if len(node.Content) == 0 {
		return nil
	}
	if node.Content[0].Kind == ScalarNode {
		return e.encodeRow(csvWriter, node.Content)
	}
	if node.Content[0].Kind == MappingNode {
		return e.encodeObjects(csvWriter, node.Content)
	}
	return e.encodeArrays(csvWriter, node.Content)
}

type csvObjectDecoder struct {
	prefs    CsvPreferences
	reader   *csv.Reader
	finished bool
}

func NewCSVObjectDecoder(prefs CsvPreferences) Decoder {
	return &csvObjectDecoder{prefs: prefs}
}

func (dec *csvObjectDecoder) Init(reader io.Reader) error {
	cleanReader, err := skipBOM(bufioReader(reader))
	if err != nil {
		return err
	}
	dec.reader = csv.NewReader(cleanReader)
	dec.reader.Comma = dec.prefs.Separator
	dec.finished = false
	return nil
}

func (dec *csvObjectDecoder) convertToNode(content string) *CandidateNode {
	node, err := parseSnippet(content)
	if err != nil || (!dec.prefs.AutoParse && (node.Kind != ScalarNode || node.Value != content)) {
		return createScalarNode(content, content)
	}
	return node
}

func (dec *csvObjectDecoder) createObject(headerRow []string, contentRow []string) *CandidateNode {
	objectNode := &CandidateNode{Kind: MappingNode, Tag: "!!map"}
	for i, header := range headerRow {
		objectNode.AddKeyValueChild(createScalarNode(header, header), dec.convertToNode(contentRow[i]))
	}
	return objectNode
}

func (dec *csvObjectDecoder) Decode() (*CandidateNode, error) {
	if dec.finished {
		return nil, io.EOF
	}
	headerRow, err := dec.reader.Read()
	if err != nil {
		return nil, err
	}
	rootArray := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
	contentRow, err := dec.reader.Read()
	for err == nil && len(contentRow) > 0 {
		log := dec.createObject(headerRow, contentRow)
		rootArray.AddChild(log)
		contentRow, err = dec.reader.Read()
	}
	if err != nil && err != io.EOF {
		return nil, err
	}
	dec.finished = true
	return rootArray, nil
}
