// ---------------- sh -----------------

type shEncoder struct{}

func NewShEncoder() Encoder { return &shEncoder{} }

func (e *shEncoder) CanHandleAliases() bool                                    { return false }
func (e *shEncoder) PrintDocumentSeparator(writer io.Writer) error             { return nil }
func (e *shEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }

var shUnsafeChars = regexp.MustCompile(`[^\w@%+=:,./-]`)

func (e *shEncoder) Encode(writer io.Writer, node *CandidateNode) error {
	if node.guessTagFromCustomType() != "!!str" {
		return fmt.Errorf("cannot encode %v as URI, can only operate on strings. Please first pipe through another encoding operator to convert the value to a string", node.Tag)
	}
	return writeString(writer, shEncode(node.Value))
}

func shEncode(input string) string {
	const quote = '\''
	var inQuoteBlock = false
	var encoded strings.Builder
	for _, ir := range input {
		if ir == quote {
			if inQuoteBlock {
				encoded.WriteRune(quote)
				inQuoteBlock = !inQuoteBlock
			}
			encoded.WriteRune('\\')
		} else if shUnsafeChars.MatchString(string(ir)) {
			if !inQuoteBlock {
				encoded.WriteRune(quote)
				inQuoteBlock = !inQuoteBlock
			}
		}
		encoded.WriteRune(ir)
	}
	if inQuoteBlock {
		encoded.WriteRune(quote)
	}
	return encoded.String()
}

// ---------------- shell variables -----------------

type ShellVariablesPreferences struct {
	KeySeparator string
	UnwrapScalar bool
}

var ConfiguredShellVariablesPreferences = ShellVariablesPreferences{KeySeparator: "_", UnwrapScalar: false}

