func (pe *shellVariablesEncoder) CanHandleAliases() bool                                    { return false }
func (pe *shellVariablesEncoder) PrintDocumentSeparator(writer io.Writer) error             { return nil }
func (pe *shellVariablesEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }

func (pe *shellVariablesEncoder) Encode(writer io.Writer, node *CandidateNode) error {
	mapKeysToStrings(node)
	return pe.doEncode(&writer, node, "")
}

func (pe *shellVariablesEncoder) doEncode(w *io.Writer, node *CandidateNode, path string) error {
	switch node.Kind {
	case ScalarNode:
		nonemptyPath := path
		if path == "" {
			nonemptyPath = "value"
		}
		var valueString string
		if pe.prefs.UnwrapScalar {
			valueString = node.Value
		} else {
			valueString = quoteShellValue(node.Value)
		}
		_, err := io.WriteString(*w, nonemptyPath+"="+valueString+"\n")
		return err
	case SequenceNode:
		for index, child := range node.Content {
			err := pe.doEncode(w, child, pe.appendPath(path, index))
			if err != nil {
				return err
			}
		}
		return nil
	case MappingNode:
		for index := 0; index+1 < len(node.Content); index = index + 2 {
			key := node.Content[index]
			value := node.Content[index+1]
			err := pe.doEncode(w, value, pe.appendPath(path, key.Value))
			if err != nil {
				return err
			}
		}
		return nil
	case AliasNode:
		return pe.doEncode(w, node.Alias, path)
	default:
		return fmt.Errorf("unsupported node %v", node.Tag)
	}
}

var latinDecompose = map[rune]string{
	'À': "A", 'Á': "A", 'Â': "A", 'Ã': "A", 'Ä': "A", 'Å': "A", 'Ç': "C", 'È': "E", 'É': "E", 'Ê': "E", 'Ë': "E",
	'Ì': "I", 'Í': "I", 'Î': "I", 'Ï': "I", 'Ñ': "N", 'Ò': "O", 'Ó': "O", 'Ô': "O", 'Õ': "O", 'Ö': "O", 'Ù': "U",
	'Ú': "U", 'Û': "U", 'Ü': "U", 'Ý': "Y", 'à': "a", 'á': "a", 'â': "a", 'ã': "a", 'ä': "a", 'å': "a", 'ç': "c",
	'è': "e", 'é': "e", 'ê': "e", 'ë': "e", 'ì': "i", 'í': "i", 'î': "i", 'ï': "i", 'ñ': "n", 'ò': "o", 'ó': "o",
	'ô': "o", 'õ': "o", 'ö': "o", 'ù': "u", 'ú': "u", 'û': "u", 'ü': "u", 'ý': "y", 'ÿ': "y",
	'ﬁ': "fi", 'ﬂ': "fl", '²': "2", '³': "3", '¹': "1",
}

func (pe *shellVariablesEncoder) appendPath(cookedPath string, rawKey interface{}) string {
	rawKeyString := fmt.Sprint(rawKey)
	if rawKeyString == "" {
		rawKeyString = "_"
	}
	var sb strings.Builder
	for _, r := range rawKeyString {
		if d, ok := latinDecompose[r]; ok {
			sb.WriteString(d)
			continue
		}
		if r < 32 || r > 126 {
			continue
		}
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') {
			sb.WriteRune(r)
		} else {
			sb.WriteRune('_')
		}
	}
	cookedKey := sb.String()
	if cookedPath == "" {
		firstRune, _ := utf8.DecodeRuneInString(cookedKey)
		if !((firstRune >= 'a' && firstRune <= 'z') || (firstRune >= 'A' && firstRune <= 'Z') || firstRune == '_') {
			return "_" + cookedKey
		}
		return cookedKey
	}
	return cookedPath + pe.prefs.KeySeparator + cookedKey
}

func quoteShellValue(value string) string {
	needsQuoting := false
	for _, r := range value {
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_') {
			needsQuoting = true
			break
		}
	}
	if needsQuoting {
		return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'"
	}
	return value
}

func mapKeysToStrings(node *CandidateNode) {
	if node.Kind == MappingNode {
		for index, child := range node.Content {
			if index%2 == 0 {
				child.Tag = "!!str"
			}
		}
	}
	for _, child := range node.Content {
		mapKeysToStrings(child)
	}
}

