		sb.WriteRune(r)
	}
	return sb.String()
}

func parseProperties(input string) ([]propertyEntry, error) {
	input = strings.ReplaceAll(input, "\r\n", "\n")
	rawLines := strings.Split(input, "\n")
	var entries []propertyEntry
	var pendingComments []string
	index := map[string]int{}
	for i := 0; i < len(rawLines); i++ {
		line := rawLines[i]
		trimmed := strings.TrimLeft(line, " \t\f")
		if trimmed == "" {
			continue
		}
		if trimmed[0] == '#' || trimmed[0] == '!' {
			pendingComments = append(pendingComments, strings.TrimLeft(trimmed[1:], " \t\f"))
			continue
		}
		// join continuation lines
		logical := trimmed
		for {
			// count trailing backslashes
			n := 0
			for j := len(logical) - 1; j >= 0 && logical[j] == '\\'; j-- {
				n++
			}
			if n%2 == 1 && i+1 < len(rawLines) {
				logical = logical[:len(logical)-1] + strings.TrimLeft(rawLines[i+1], " \t\f")
				i++
				continue
			} else if n%2 == 1 {
				logical = logical[:len(logical)-1]
			}
			break
		}
		// split key and value
		keyEnd := len(logical)
		for j := 0; j < len(logical); j++ {
			c := logical[j]
			if c == '\\' {
				j++
				continue
			}
			if c == '=' || c == ':' || c == ' ' || c == '\t' || c == '\f' {
				keyEnd = j
				break
			}
		}
		rawKey := logical[:keyEnd]
		rest := logical[keyEnd:]
		rest = strings.TrimLeft(rest, " \t\f")
		if len(rest) > 0 && (rest[0] == '=' || rest[0] == ':') {
			rest = rest[1:]
		}
		rest = strings.TrimLeft(rest, " \t\f")
		key := unescapeProp(rawKey)
		value := unescapeProp(rest)
		if idx, ok := index[key]; ok {
			entries[idx].value = value
			if len(pendingComments) > 0 {
				entries[idx].comments = pendingComments
			}
		} else {
			index[key] = len(entries)
			entries = append(entries, propertyEntry{key: key, value: value, comments: pendingComments})
		}
		pendingComments = nil
	}
	return entries, nil
}

func parsePropKey(key string) []interface{} {
	pathStrArray := strings.Split(key, ".")
	path := make([]interface{}, len(pathStrArray))
	for i, pathStr := range pathStrArray {
		num, err := parseInt(pathStr)
		if err == nil && !strings.HasPrefix(pathStr, "0x") && !strings.HasPrefix(pathStr, "0o") && !strings.ContainsAny(pathStr, "_+") {
			path[i] = num
		} else {
			path[i] = pathStr
		}
	}
	return path
}

func (dec *propertiesDecoder) applyProperty(root *CandidateNode, e propertyEntry) error {
	d := &dataTreeNavigator{}
	context := newRootContext([]*CandidateNode{root})
	path := parsePropKey(e.key)
	if len(e.comments) > 0 {
		var lines []string
		for _, c := range e.comments {
			lines = append(lines, "# "+c)
		}
		rhsCandidateNode := &CandidateNode{
			Tag:         "!!str",
			Value:       fmt.Sprintf("%v", path[len(path)-1]),
			HeadComment: strings.Join(lines, "\n"),
			Kind:        ScalarNode,
		}
		rhsCandidateNode.Tag = rhsCandidateNode.guessTagFromCustomType()
		assignmentOpNode := &ExpressionNode{
			Operation: &Operation{OperationType: assignOpType, Preferences: assignPreferences{}},
			LHS:       createTraversalTree(path, traversePreferences{}, true),
			RHS:       &ExpressionNode{Operation: &Operation{OperationType: referenceOpType, CandidateNode: rhsCandidateNode}},
		}
		if _, err := d.GetMatchingNodes(context, assignmentOpNode); err != nil {
			return nil
		}
	}
	rhsNode := createStringScalar(e.value)
	assignmentOpNode := &ExpressionNode{
		Operation: &Operation{OperationType: assignOpType, Preferences: assignPreferences{}},
		LHS:       createTraversalTree(path, traversePreferences{}, false),
		RHS:       &ExpressionNode{Operation: &Operation{OperationType: referenceOpType, CandidateNode: rhsNode}},
	}
	_, err := d.GetMatchingNodes(context, assignmentOpNode)
	return err
}
