package main

import (
	"fmt"
	"io"
	"regexp"
	"strconv"
	"strings"
	"unicode/utf8"
)

// ---------------- decoding -----------------

type tomlDecoder struct {
	data     []rune
	pos      int
	finished bool
	line     int
}

func NewTomlDecoder() Decoder {
	return &tomlDecoder{}
}

func (dec *tomlDecoder) Init(reader io.Reader) error {
	data, err := io.ReadAll(reader)
	if err != nil {
		return err
	}
	dec.data = []rune(string(data))
	dec.pos = 0
	dec.finished = false
	return nil
}

func (dec *tomlDecoder) peek() rune {
	if dec.pos >= len(dec.data) {
		return 0
	}
	return dec.data[dec.pos]
}

func (dec *tomlDecoder) peekAt(offset int) rune {
	if dec.pos+offset >= len(dec.data) {
		return 0
	}
	return dec.data[dec.pos+offset]
}

func (dec *tomlDecoder) eof() bool { return dec.pos >= len(dec.data) }

func (dec *tomlDecoder) skipSpaces() {
	for !dec.eof() && (dec.peek() == ' ' || dec.peek() == '\t') {
		dec.pos++
	}
}

// reads a comment if present (from '#' to end of line), returns it (including '#')
func (dec *tomlDecoder) readComment() string {
	dec.skipSpaces()
	if dec.peek() != '#' {
		return ""
	}
	start := dec.pos
	for !dec.eof() && dec.peek() != '\n' {
		dec.pos++
	}
	return strings.TrimRight(string(dec.data[start:dec.pos]), "\r")
}

func (dec *tomlDecoder) expectNewline() error {
	dec.skipSpaces()
	if dec.eof() {
		return nil
	}
	if dec.peek() == '\r' {
		dec.pos++
	}
	if dec.peek() == '\n' {
		dec.pos++
		return nil
	}
	return fmt.Errorf("expected newline but got %#U", dec.peek())
}

func isBareKeyChar(r rune) bool {
	return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' || r == '-'
}

func (dec *tomlDecoder) parseKey() ([]string, error) {
	var parts []string
	for {
		dec.skipSpaces()
		c := dec.peek()
		var part string
		if c == '"' {
			s, err := dec.parseBasicString()
			if err != nil {
				return nil, err
			}
			part = s
		} else if c == '\'' {
			s, err := dec.parseLiteralString()
			if err != nil {
				return nil, err
			}
			part = s
		} else if isBareKeyChar(c) {
			start := dec.pos
			for !dec.eof() && isBareKeyChar(dec.peek()) {
				dec.pos++
			}
			part = string(dec.data[start:dec.pos])
		} else {
			if dec.eof() {
				return nil, fmt.Errorf("expected key but got EOF")
			}
			return nil, fmt.Errorf("invalid character at start of key: %c", c)
		}
		parts = append(parts, part)
		dec.skipSpaces()
		if dec.peek() == '.' {
			dec.pos++
			continue
		}
		return parts, nil
	}
}

func (dec *tomlDecoder) parseBasicString() (string, error) {
	// assumes at '"'
	if dec.peekAt(1) == '"' && dec.peekAt(2) == '"' {
		return dec.parseMultilineBasicString()
	}
	dec.pos++
	var sb strings.Builder
	for {
		if dec.eof() || dec.peek() == '\n' {
			return "", fmt.Errorf("unterminated basic string")
		}
		c := dec.peek()
		if c == '"' {
			dec.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			r, err := dec.parseEscape()
			if err != nil {
				return "", err
			}
			sb.WriteString(r)
			continue
		}
		sb.WriteRune(c)
		dec.pos++
	}
}

func (dec *tomlDecoder) parseEscape() (string, error) {
	dec.pos++ // backslash
	c := dec.peek()
	dec.pos++
	switch c {
	case 'b':
		return "\b", nil
	case 't':
		return "\t", nil
	case 'n':
		return "\n", nil
	case 'f':
		return "\f", nil
	case 'r':
		return "\r", nil
	case 'e':
		return "\x1b", nil
	case '"':
		return "\"", nil
	case '\\':
		return "\\", nil
	case 'u', 'U':
		n := 4
		if c == 'U' {
			n = 8
		}
		if dec.pos+n > len(dec.data) {
			return "", fmt.Errorf("invalid unicode escape")
		}
		v, err := strconv.ParseUint(string(dec.data[dec.pos:dec.pos+n]), 16, 32)
		if err != nil {
			return "", fmt.Errorf("invalid unicode escape")
		}
		dec.pos += n
		return string(rune(v)), nil
	}
	return "", fmt.Errorf("invalid escaped character %#U", c)
}

func (dec *tomlDecoder) parseMultilineBasicString() (string, error) {
	dec.pos += 3
	if dec.peek() == '\r' && dec.peekAt(1) == '\n' {
		dec.pos += 2
	} else if dec.peek() == '\n' {
		dec.pos++
	}
	var sb strings.Builder
	for {
		if dec.eof() {
			return "", fmt.Errorf("unterminated multiline string")
		}
		c := dec.peek()
		if c == '"' && dec.peekAt(1) == '"' && dec.peekAt(2) == '"' {
			// allow up to 2 extra quotes
			extra := 0
			for dec.peekAt(3+extra) == '"' && extra < 2 {
				extra++
			}
			for i := 0; i < extra; i++ {
				sb.WriteRune('"')
			}
			dec.pos += 3 + extra
			return sb.String(), nil
		}
		if c == '\\' {
			// line ending backslash
			j := dec.pos + 1
			for j < len(dec.data) && (dec.data[j] == ' ' || dec.data[j] == '\t') {
				j++
			}
			if j < len(dec.data) && (dec.data[j] == '\n' || dec.data[j] == '\r') {
				dec.pos = j
				for !dec.eof() && (dec.peek() == ' ' || dec.peek() == '\t' || dec.peek() == '\n' || dec.peek() == '\r') {
					dec.pos++
				}
				continue
			}
			r, err := dec.parseEscape()
			if err != nil {
				return "", err
			}
			sb.WriteString(r)
			continue
		}
		sb.WriteRune(c)
		dec.pos++
	}
}

func (dec *tomlDecoder) parseLiteralString() (string, error) {
	if dec.peekAt(1) == '\'' && dec.peekAt(2) == '\'' {
		dec.pos += 3
		if dec.peek() == '\r' && dec.peekAt(1) == '\n' {
			dec.pos += 2
		} else if dec.peek() == '\n' {
			dec.pos++
		}
		start := dec.pos
		for {
			if dec.eof() {
				return "", fmt.Errorf("unterminated multiline literal string")
			}
			if dec.peek() == '\'' && dec.peekAt(1) == '\'' && dec.peekAt(2) == '\'' {
				extra := 0
				for dec.peekAt(3+extra) == '\'' && extra < 2 {
					extra++
				}
				s := string(dec.data[start:dec.pos+extra])
				dec.pos += 3 + extra
				return s, nil
			}
			dec.pos++
		}
	}
	dec.pos++
	start := dec.pos
	for {
		if dec.eof() || dec.peek() == '\n' {
			return "", fmt.Errorf("unterminated literal string")
		}
		if dec.peek() == '\'' {
			s := string(dec.data[start:dec.pos])
			dec.pos++
			return s, nil
		}
		dec.pos++
	}
}

func (dec *tomlDecoder) skipWhitespaceNewlinesAndComments() []string {
	var comments []string
	for !dec.eof() {
		c := dec.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			dec.pos++
		} else if c == '#' {
			comments = append(comments, dec.readComment())
		} else {
			break
		}
	}
	return comments
}

var tomlDateRegex = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}`)
var tomlTimeRegex = regexp.MustCompile(`^\d{2}:\d{2}`)

func (dec *tomlDecoder) parseValue() (*CandidateNode, error) {
	dec.skipSpaces()
	if dec.eof() {
		return nil, fmt.Errorf("expected value but got EOF")
	}
	c := dec.peek()
	switch {
	case c == '"':
		s, err := dec.parseBasicString()
		if err != nil {
			return nil, err
		}
		return createStringScalar(s), nil
	case c == '\'':
		s, err := dec.parseLiteralString()
		if err != nil {
			return nil, err
		}
		return createStringScalar(s), nil
	case c == '[':
		return dec.parseArray()
	case c == '{':
		return dec.parseInlineTable()
	}
	start := dec.pos
	for !dec.eof() {
		r := dec.peek()
		if r == ',' || r == ']' || r == '}' || r == '#' || r == '\n' || r == '\r' || r == ' ' || r == '\t' {
			break
		}
		dec.pos++
	}
	raw := string(dec.data[start:dec.pos])
	if raw == "" {
		return nil, fmt.Errorf("expected value")
	}
	switch raw {
	case "true", "false":
		return &CandidateNode{Kind: ScalarNode, Tag: "!!bool", Value: raw}, nil
	case "inf", "+inf", "-inf", "nan", "+nan", "-nan":
		return &CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: raw}, nil
	}
	if tomlDateRegex.MatchString(raw) {
		// date or datetime
		rest := raw
		if len(raw) == 10 {
			// could be date followed by space time
			if dec.peek() == ' ' && tomlTimeRegex.MatchString(string(dec.data[dec.pos+1:min(dec.pos+6, len(dec.data))])) {
				j := dec.pos + 1
				for j < len(dec.data) {
					r := dec.data[j]
					if r == ',' || r == ']' || r == '}' || r == '#' || r == '\n' || r == '\r' || r == ' ' || r == '\t' {
						break
					}
					j++
				}
				full := raw + string(dec.data[dec.pos:j])
				return nil, fmt.Errorf("parsing time %q: extra text: %q", full, full[10:])
			}
			return nil, fmt.Errorf("unsupported type LocalDate")
		}
		upper := strings.ToUpper(rest)
		if strings.HasSuffix(upper, "Z") || regexp.MustCompile(`[+-]\d{2}:\d{2}$`).MatchString(rest) {
			if _, err := parseDateTime(defaultDateTimeLayout, strings.Replace(raw, " ", "T", 1)); err != nil {
				return nil, err
			}
			return &CandidateNode{Kind: ScalarNode, Tag: "", Value: raw}, nil
		}
		return nil, fmt.Errorf("unsupported type LocalDateTime")
	}
	if tomlTimeRegex.MatchString(raw) {
		return nil, fmt.Errorf("unsupported type LocalTime")
	}
	isFloat := false
	if !strings.HasPrefix(raw, "0x") && !strings.HasPrefix(raw, "0o") && !strings.HasPrefix(raw, "0b") {
		isFloat = strings.ContainsAny(raw, ".eE")
	}
	if isFloat {
		if _, err := strconv.ParseFloat(strings.ReplaceAll(raw, "_", ""), 64); err != nil {
			return nil, err
		}
		return &CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: raw}, nil
	}
	if _, _, err := parseInt64(strings.TrimPrefix(raw, "+")); err != nil {
		if strings.HasPrefix(raw, "0b") {
			return nil, fmt.Errorf("strconv.ParseInt: parsing %q: invalid syntax", raw)
		}
		return nil, err
	}
	return &CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: raw}, nil
}

func (dec *tomlDecoder) parseArray() (*CandidateNode, error) {
	dec.pos++ // [
	seq := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
	for {
		comments := dec.skipWhitespaceNewlinesAndComments()
		if dec.eof() {
			return nil, fmt.Errorf("unterminated array")
		}
		if dec.peek() == ']' {
			dec.pos++
			return seq, nil
		}
		value, err := dec.parseValue()
		if err != nil {
			return nil, err
		}
		if len(comments) > 0 {
			value.HeadComment = strings.Join(comments, "\n")
		}
		seq.AddChild(value)
		dec.skipSpaces()
		if dec.peek() == ',' {
			dec.pos++
			lc := dec.readComment()
			if lc != "" {
				// comment after comma applies to next element as head comment
				nextComments := []string{lc}
				more := dec.skipWhitespaceNewlinesAndComments()
				nextComments = append(nextComments, more...)
				if dec.peek() == ']' {
					dec.pos++
					return seq, nil
				}
				value, err := dec.parseValue()
				if err != nil {
					return nil, err
				}
				value.HeadComment = strings.Join(nextComments, "\n")
				seq.AddChild(value)
				dec.skipSpaces()
				if dec.peek() == ',' {
					dec.pos++
				}
			}
			continue
		}
		comments = dec.skipWhitespaceNewlinesAndComments()
		if dec.peek() == ']' {
			dec.pos++
			return seq, nil
		}
		if dec.peek() == ',' {
			dec.pos++
			continue
		}
		return nil, fmt.Errorf("expected ',' or ']' in array")
	}
}

func (dec *tomlDecoder) parseInlineTable() (*CandidateNode, error) {
	dec.pos++ // {
	m := &CandidateNode{Kind: MappingNode, Tag: "!!map", tomlInline: true}
	dec.skipSpaces()
	if dec.peek() == '}' {
		dec.pos++
		return m, nil
	}
	for {
		dec.skipSpaces()
		keys, err := dec.parseKey()
		if err != nil {
			return nil, err
		}
		dec.skipSpaces()
		if dec.peek() != '=' {
			return nil, fmt.Errorf("expected '=' in inline table")
		}
		dec.pos++
		value, err := dec.parseValue()
		if err != nil {
			return nil, err
		}
		target := m
		for _, k := range keys[:len(keys)-1] {
			target = tomlGetOrCreateMap(target, k, true)
		}
		tomlSetKey(target, keys[len(keys)-1], value)
		dec.skipSpaces()
		if dec.peek() == ',' {
			dec.pos++
			continue
		}
		if dec.peek() == '}' {
			dec.pos++
			return m, nil
		}
		return nil, fmt.Errorf("expected ',' or '}' in inline table")
	}
}

func tomlGetOrCreateMap(parent *CandidateNode, key string, inline bool) *CandidateNode {
	for i := 0; i+1 < len(parent.Content); i += 2 {
		if parent.Content[i].Value == key {
			v := parent.Content[i+1]
			if v.Kind == MappingNode {
				return v
			}
			if v.Kind == SequenceNode && len(v.Content) > 0 {
				return v.Content[len(v.Content)-1]
			}
		}
	}
	newMap := &CandidateNode{Kind: MappingNode, Tag: "!!map", tomlInline: inline}
	keyNode := createStringScalar(key)
	keyNode.Parent = parent
	keyNode.IsMapKey = true
	newMap.Parent = parent
	newMap.Key = keyNode
	parent.Content = append(parent.Content, keyNode, newMap)
	return newMap
}

func tomlSetKey(parent *CandidateNode, key string, value *CandidateNode) {
	for i := 0; i+1 < len(parent.Content); i += 2 {
		if parent.Content[i].Value == key {
			value.Parent = parent
			value.Key = parent.Content[i]
			parent.Content[i+1] = value
			return
		}
	}
	keyNode := createStringScalar(key)
	keyNode.Parent = parent
	keyNode.IsMapKey = true
	value.Parent = parent
	value.Key = keyNode
	parent.Content = append(parent.Content, keyNode, value)
}

func (dec *tomlDecoder) Decode() (*CandidateNode, error) {
	if dec.finished {
		return nil, io.EOF
	}
	dec.finished = true
	root := &CandidateNode{Kind: MappingNode, Tag: "!!map"}
	current := root
	first := true
	readAnything := false
	for {
		comments := dec.skipWhitespaceNewlinesAndComments()
		if dec.eof() {
			break
		}
		readAnything = true
		c := dec.peek()
		if c == '[' {
			isArray := dec.peekAt(1) == '['
			if isArray {
				dec.pos += 2
			} else {
				dec.pos++
			}
			keys, err := dec.parseKey()
			if err != nil {
				return nil, err
			}
			dec.skipSpaces()
			if isArray {
				if dec.peek() != ']' || dec.peekAt(1) != ']' {
					return nil, fmt.Errorf("expected ']]'")
				}
				dec.pos += 2
			} else {
				if dec.peek() != ']' {
					return nil, fmt.Errorf("expected ']'")
				}
				dec.pos++
			}
			_ = dec.readComment()
			if err := dec.expectNewline(); err != nil {
				return nil, err
			}
			parent := root
			for _, k := range keys[:len(keys)-1] {
				parent = tomlGetOrCreateMap(parent, k, false)
			}
			lastKey := keys[len(keys)-1]
			if isArray {
				var seq *CandidateNode
				for i := 0; i+1 < len(parent.Content); i += 2 {
					if parent.Content[i].Value == lastKey && parent.Content[i+1].Kind == SequenceNode {
						seq = parent.Content[i+1]
					}
				}
				if seq == nil {
					seq = &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
					tomlSetKey(parent, lastKey, seq)
				}
				elem := &CandidateNode{Kind: MappingNode, Tag: "!!map"}
				if len(comments) > 0 {
					elem.HeadComment = strings.Join(comments, "\n")
				}
				seq.AddChild(elem)
				current = seq.Content[len(seq.Content)-1]
			} else {
				current = tomlGetOrCreateMap(parent, lastKey, false)
				current.tomlInline = false
				if len(comments) > 0 {
					current.HeadComment = strings.Join(comments, "\n")
				}
			}
			first = false
			continue
		}
		keys, err := dec.parseKey()
		if err != nil {
			return nil, err
		}
		dec.skipSpaces()
		if dec.peek() != '=' {
			if dec.eof() {
				return nil, fmt.Errorf("expected character =")
			}
			return nil, fmt.Errorf("expected character =")
		}
		dec.pos++
		value, err := dec.parseValue()
		if err != nil {
			return nil, err
		}
		lc := dec.readComment()
		if lc != "" {
			value.LineComment = lc
		}
		if err := dec.expectNewline(); err != nil {
			return nil, err
		}
		if len(comments) > 0 {
			if first && current == root {
				root.HeadComment = strings.Join(comments, "\n")
			} else {
				value.HeadComment = strings.Join(comments, "\n")
			}
		}
		target := current
		for _, k := range keys[:len(keys)-1] {
			target = tomlGetOrCreateMap(target, k, false)
		}
		tomlSetKey(target, keys[len(keys)-1], value)
		first = false
	}
	if !readAnything {
		return nil, io.EOF
	}
	return root, nil
}

// ---------------- encoding -----------------

type tomlEncoder struct {
	written bool
}

func NewTomlEncoder() Encoder {
	return &tomlEncoder{}
}

func (te *tomlEncoder) CanHandleAliases() bool                                    { return false }
func (te *tomlEncoder) PrintDocumentSeparator(writer io.Writer) error             { return nil }
func (te *tomlEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }

func (te *tomlEncoder) Encode(writer io.Writer, node *CandidateNode) error {
	if node.Kind == ScalarNode {
		return writeString(writer, node.Value+"\n")
	}
	if node.Kind != MappingNode {
		return fmt.Errorf("TOML encoder expects a mapping at the root level")
	}
	var sb strings.Builder
	te.written = false
	if node.HeadComment != "" {
		te.writeComment(&sb, node.HeadComment)
	}
	for i := 0; i+1 < len(node.Content); i += 2 {
		key := node.Content[i]
		value := node.Content[i+1]
		path := []string{key.Value}
		if tomlIsTable(value) {
			te.encodeTable(&sb, path, value)
		} else if tomlIsArrayOfTables(value) {
			te.encodeArrayOfTables(&sb, path, value)
		} else {
			te.encodeKeyValue(&sb, key.Value, value)
		}
	}
	return writeString(writer, sb.String())
}

func tomlIsTable(n *CandidateNode) bool {
	return n.Kind == MappingNode && n.Style&FlowStyle == 0 && !n.tomlInline
}

func tomlIsArrayOfTables(n *CandidateNode) bool {
	if n.Kind != SequenceNode || len(n.Content) == 0 {
		return false
	}
	for _, c := range n.Content {
		if c.Kind != MappingNode {
			return false
		}
	}
	return true
}

func (te *tomlEncoder) writeComment(sb *strings.Builder, comment string) {
	for _, line := range strings.Split(comment, "\n") {
		if !strings.HasPrefix(strings.TrimSpace(line), "#") {
			line = "# " + line
		}
		sb.WriteString(line + "\n")
	}
	te.written = true
}

var tomlBareKeyRegex = regexp.MustCompile(`^[A-Za-z0-9_-]+$`)

func tomlFormatKey(k string) string {
	if tomlBareKeyRegex.MatchString(k) {
		return k
	}
	return strconv.Quote(k)
}

func tomlFormatPath(path []string) string {
	parts := make([]string, len(path))
	for i, p := range path {
		parts[i] = tomlFormatKey(p)
	}
	return strings.Join(parts, ".")
}

func (te *tomlEncoder) encodeKeyValue(sb *strings.Builder, key string, value *CandidateNode) {
	if value.HeadComment != "" {
		te.writeComment(sb, value.HeadComment)
	}
	sb.WriteString(tomlFormatKey(key) + " = " + te.formatValue(value))
	if value.LineComment != "" {
		lc := value.LineComment
		if !strings.HasPrefix(lc, "#") {
			lc = "# " + lc
		}
		sb.WriteString("  " + lc)
	}
	sb.WriteString("\n")
	te.written = true
}

func (te *tomlEncoder) formatValue(value *CandidateNode) string {
	switch value.Kind {
	case AliasNode:
		if value.Alias != nil {
			return te.formatValue(value.Alias)
		}
		return `""`
	case ScalarNode:
		tag := value.guessTagFromCustomType()
		switch tag {
		case "!!str":
			return tomlQuote(value.Value)
		case "!!null":
			return `""`
		}
		return value.Value
	case SequenceNode:
		hasComments := false
		for _, c := range value.Content {
			if c.HeadComment != "" || c.LineComment != "" {
				hasComments = true
			}
		}
		if hasComments {
			var sb strings.Builder
			sb.WriteString("[\n")
			for i, c := range value.Content {
				if c.HeadComment != "" {
					if i > 0 {
						sb.WriteString("\n")
					} else {
						sb.WriteString("\n")
					}
					for _, line := range strings.Split(c.HeadComment, "\n") {
						sb.WriteString("  " + line + "\n")
					}
				}
				sb.WriteString("  " + te.formatValue(c) + ",")
				if c.LineComment != "" {
					sb.WriteString(" " + c.LineComment)
				}
				sb.WriteString("\n")
			}
			sb.WriteString("]")
			return sb.String()
		}
		parts := make([]string, 0, len(value.Content))
		for _, c := range value.Content {
			parts = append(parts, te.formatValue(c))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case MappingNode:
		parts := make([]string, 0, len(value.Content)/2)
		for i := 0; i+1 < len(value.Content); i += 2 {
			parts = append(parts, tomlFormatKey(value.Content[i].Value)+" = "+te.formatValue(value.Content[i+1]))
		}
		return "{ " + strings.Join(parts, ", ") + " }"
	}
	return `""`
}

func tomlQuote(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for i := 0; i < len(s); {
		r, size := utf8.DecodeRuneInString(s[i:])
		switch {
		case r == '"':
			sb.WriteString(`\"`)
		case r == '\\':
			sb.WriteString(`\\`)
		case r == '\n':
			sb.WriteString(`\n`)
		case r == '\t':
			sb.WriteString(`\t`)
		case r == '\r':
			sb.WriteString(`\r`)
		default:
			q := strconv.QuoteRune(r)
			inner := q[1 : len(q)-1]
			if inner == `\'` {
				inner = "'"
			}
			sb.WriteString(inner)
		}
		i += size
	}
	sb.WriteByte('"')
	return sb.String()
}

func (te *tomlEncoder) encodeTableContents(sb *strings.Builder, path []string, m *CandidateNode) {
	for i := 0; i+1 < len(m.Content); i += 2 {
		v := m.Content[i+1]
		if !tomlIsTable(v) && !tomlIsArrayOfTables(v) {
			te.encodeKeyValue(sb, m.Content[i].Value, v)
		}
	}
	for i := 0; i+1 < len(m.Content); i += 2 {
		v := m.Content[i+1]
		if tomlIsArrayOfTables(v) {
			te.encodeArrayOfTables(sb, append(append([]string{}, path...), m.Content[i].Value), v)
		}
	}
	for i := 0; i+1 < len(m.Content); i += 2 {
		v := m.Content[i+1]
		if tomlIsTable(v) {
			te.encodeTable(sb, append(append([]string{}, path...), m.Content[i].Value), v)
		}
	}
}

func (te *tomlEncoder) encodeTable(sb *strings.Builder, path []string, m *CandidateNode) {
	hasInline := false
	for i := 0; i+1 < len(m.Content); i += 2 {
		v := m.Content[i+1]
		if !tomlIsTable(v) && !tomlIsArrayOfTables(v) {
			hasInline = true
		}
	}
	if hasInline || len(m.Content) == 0 {
		if te.written {
			sb.WriteString("\n")
		}
		if m.HeadComment != "" {
			te.writeComment(sb, m.HeadComment)
		}
		sb.WriteString("[" + tomlFormatPath(path) + "]\n")
		te.written = true
		te.encodeTableContents(sb, path, m)
		return
	}
	for i := 0; i+1 < len(m.Content); i += 2 {
		v := m.Content[i+1]
		childPath := append(append([]string{}, path...), m.Content[i].Value)
		if tomlIsTable(v) {
			te.encodeTable(sb, childPath, v)
		} else if tomlIsArrayOfTables(v) {
			te.encodeArrayOfTables(sb, childPath, v)
		}
	}
}

func (te *tomlEncoder) encodeArrayOfTables(sb *strings.Builder, path []string, seq *CandidateNode) {
	for _, elem := range seq.Content {
		if elem.HeadComment != "" {
			te.writeComment(sb, elem.HeadComment)
		}
		sb.WriteString("[[" + tomlFormatPath(path) + "]]\n")
		te.written = true
		te.encodeTableContents(sb, path, elem)
	}
}
