package main

import (
	"bytes"
	"fmt"
	"io"
	"strings"
	"unicode"
)

type iniDecoder struct {
	reader   io.Reader
	finished bool
}

func NewINIDecoder() Decoder {
	return &iniDecoder{}
}

func (dec *iniDecoder) Init(reader io.Reader) error {
	dec.reader = reader
	dec.finished = false
	return nil
}

func hasSurroundedQuote(in string, quote byte) bool {
	return len(in) >= 2 && in[0] == quote && in[len(in)-1] == quote &&
		strings.IndexByte(in[1:], quote) == len(in)-2
}

func iniReadValue(line string, lines []string, idx *int) (string, error) {
	line = strings.TrimLeftFunc(line, unicode.IsSpace)
	if len(line) == 0 {
		return "", nil
	}
	var valQuote string
	if len(line) > 3 && line[0:3] == `"""` {
		valQuote = `"""`
	} else if line[0] == '`' {
		valQuote = "`"
	}
	if len(valQuote) > 0 {
		startIdx := len(valQuote)
		pos := strings.LastIndex(line[startIdx:], valQuote)
		if pos == -1 {
			// multi-line
			var sb strings.Builder
			sb.WriteString(line[startIdx:])
			for *idx+1 < len(lines) {
				*idx = *idx + 1
				next := lines[*idx]
				sb.WriteString("\n")
				if p := strings.Index(next, valQuote); p >= 0 {
					sb.WriteString(next[:p])
					return sb.String(), nil
				}
				sb.WriteString(next)
			}
			return "", fmt.Errorf("missing closing key quote (%s)", valQuote)
		}
		return line[startIdx : pos+startIdx], nil
	}
	line = strings.TrimSpace(line)
	trimmedLastChar := line[len(line)-1]
	if trimmedLastChar == '\\' {
		var sb strings.Builder
		sb.WriteString(line[:len(line)-1])
		for *idx+1 < len(lines) {
			*idx = *idx + 1
			next := strings.TrimSpace(lines[*idx])
			if len(next) > 0 && next[len(next)-1] == '\\' {
				sb.WriteString(next[:len(next)-1])
				continue
			}
			sb.WriteString(next)
			break
		}
