	} else if strings.Contains(k, "`") {
		return `"""` + k + `"""`
	}
	return k
}

func iniFormatValue(val string) string {
	if strings.ContainsAny(val, "\n`") {
		return `"""` + val + `"""`
	} else if strings.ContainsAny(val, "#;") {
		return "`" + val + "`"
	} else if len(strings.TrimSpace(val)) != len(val) {
		return `"` + val + `"`
	}
	return val
}

func writeIniSection(buf *bytes.Buffer, kvs []iniKV) {
	alignLength := 0
	for _, kv := range kvs {
		keyLength := len(kv.key)
		if strings.ContainsAny(kv.key, "\"=:") {
			keyLength += 2
		} else if strings.Contains(kv.key, "`") {
