	type section struct {
		name string
		kvs  []iniKV
	}
	var sections []section
	for i := 0; i+1 < len(node.Content); i += 2 {
		k := node.Content[i]
		v := node.Content[i+1]
		if v.Kind == AliasNode && v.Alias != nil {
			v = v.Alias
		}
		if v.Kind == ScalarNode {
			defaults = append(defaults, iniKV{k.Value, v.Value})
		} else if v.Kind == MappingNode {
			s := section{name: k.Value}
			for j := 0; j+1 < len(v.Content); j += 2 {
				sv := v.Content[j+1]
				if sv.Kind == AliasNode && sv.Alias != nil {
					sv = sv.Alias
				}
				if sv.Kind == ScalarNode {
					s.kvs = append(s.kvs, iniKV{v.Content[j].Value, sv.Value})
				}
			}
			sections = append(sections, s)
		}
	}
	var buf bytes.Buffer
	if len(defaults) > 0 {
		writeIniSection(&buf, defaults)
	}
	for _, s := range sections {
		if buf.Len() > 0 {
			buf.WriteString("\n")
		}
		buf.WriteString("[" + s.name + "]\n")
		writeIniSection(&buf, s.kvs)
	}
	_, err := writer.Write(buf.Bytes())
	return err
