func (ke *kyamlEncoder) writeComment(buf *bytes.Buffer, comment string, depth int) {
	if comment == "" {
		return
	}
	for _, line := range strings.Split(comment, "\n") {
		if line == "" {
			buf.WriteString("\n")
			continue
		}
		if !strings.HasPrefix(line, "#") {
			line = "# " + line
		}
		buf.WriteString(ke.indent(depth) + line + "\n")
	}
}

func kyamlFormatKey(k string) string {
	if kyamlBareKey.MatchString(k) {
		return k
	}
	var b bytes.Buffer
	writeJSONString(&b, k)
	return b.String()
}

func (ke *kyamlEncoder) writeScalar(buf *bytes.Buffer, node *CandidateNode) {
	tag := node.guessTagFromCustomType()
	switch tag {
	case "!!int", "!!float", "!!bool":
		buf.WriteString(node.Value)
	case "!!null":
		buf.WriteString("null")
	default:
		writeJSONString(buf, node.Value)
	}
}

func (ke *kyamlEncoder) lineComment(n *CandidateNode) string {
	if n.LineComment == "" {
		return ""
	}
	lc := n.LineComment
	if !strings.HasPrefix(lc, "#") {
		lc = "# " + lc
	}
	return " " + lc
}

func (ke *kyamlEncoder) writeNode(buf *bytes.Buffer, node *CandidateNode, depth int) {
	switch node.Kind {
	case AliasNode:
		if node.Alias != nil {
			ke.writeNode(buf, node.Alias, depth)
		} else {
			buf.WriteString("null")
		}
	case ScalarNode:
		ke.writeScalar(buf, node)
	case MappingNode:
		if len(node.Content) == 0 && node.FootComment == "" {
			buf.WriteString("{}")
			return
		}
		buf.WriteString("{\n")
		for i := 0; i+1 < len(node.Content); i += 2 {
			k := node.Content[i]
			v := node.Content[i+1]
			ke.writeComment(buf, k.HeadComment, depth+1)
			buf.WriteString(ke.indent(depth+1) + kyamlFormatKey(k.Value) + ": ")
			ke.writeNode(buf, v, depth+1)
			buf.WriteString(",")
			lc := ke.lineComment(v)
			if lc == "" {
				lc = ke.lineComment(k)
			}
			buf.WriteString(lc)
			buf.WriteString("\n")
			ke.writeComment(buf, k.FootComment, depth+1)
		}
		ke.writeComment(buf, node.FootComment, depth+1)
		buf.WriteString(ke.indent(depth) + "}")
	case SequenceNode:
		if len(node.Content) == 0 && node.FootComment == "" {
			buf.WriteString("[]")
			return
		}
		buf.WriteString("[\n")
		for _, c := range node.Content {
			ke.writeComment(buf, c.HeadComment, depth+1)
			buf.WriteString(ke.indent(depth + 1))
			ke.writeNode(buf, c, depth+1)
			buf.WriteString(",")
			buf.WriteString(ke.lineComment(c))
			buf.WriteString("\n")
			ke.writeComment(buf, c.FootComment, depth+1)
		}
		ke.writeComment(buf, node.FootComment, depth+1)
		buf.WriteString(ke.indent(depth) + "]")
	}
}
