cat > src/format_lua.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"math"
	"regexp"
	"strconv"
	"strings"
)

type LuaPreferences struct {
	DocPrefix    string
	DocSuffix    string
	UnquotedKeys bool
	Globals      bool
}

var ConfiguredLuaPreferences = LuaPreferences{DocPrefix: "return ", DocSuffix: ";\n"}

type luaEncoder struct {
	prefs LuaPreferences
}

func NewLuaEncoder(prefs LuaPreferences) Encoder {
	return &luaEncoder{prefs: prefs}
}

func (le *luaEncoder) CanHandleAliases() bool                                    { return false }
func (le *luaEncoder) PrintDocumentSeparator(writer io.Writer) error             { return nil }
func (le *luaEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }

var luaKeywords = map[string]bool{
	"and": true, "break": true, "do": true, "else": true, "elseif": true, "end": true,
	"false": true, "for": true, "function": true, "goto": true, "if": true, "in": true,
	"local": true, "nil": true, "not": true, "or": true, "repeat": true, "return": true,
	"then": true, "true": true, "until": true, "while": true,
}

var luaIdentRegex = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

func luaIsIdent(s string) bool {
	return luaIdentRegex.MatchString(s) && !luaKeywords[s]
}

func luaQuote(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\n':
			sb.WriteString(`\n`)
		case '\t':
			sb.WriteString(`\t`)
		case '\r':
			sb.WriteString(`\r`)
		case '\a':
			sb.WriteString(`\a`)
		case '\b':
			sb.WriteString(`\b`)
		case '\f':
			sb.WriteString(`\f`)
		case '\v':
			sb.WriteString(`\v`)
		case '"':
			sb.WriteString(`\"`)
		case '\'':
			sb.WriteString(`\'`)
		case '\\':
			sb.WriteString(`\\`)
		default:
			if c < 32 || c == 127 {
				sb.WriteString(fmt.Sprintf("\\%03d", c))
			} else {
				sb.WriteByte(c)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func (le *luaEncoder) formatKey(k string, unquoted bool) string {
	if unquoted && luaIsIdent(k) {
		return k
	}
	return "[" + luaQuote(k) + "]"
}

func (le *luaEncoder) encodeAny(sb *strings.Builder, node *CandidateNode, depth int) error {
	indent := strings.Repeat("\t", depth)
	switch node.Kind {
	case AliasNode:
		if node.Alias == nil {
			sb.WriteString("nil")
			return nil
		}
		return le.encodeAny(sb, node.Alias, depth)
	case SequenceNode:
		if len(node.Content) == 0 {
			sb.WriteString("{}")
			return nil
		}
		sb.WriteString("{\n")
		for _, c := range node.Content {
			sb.WriteString(indent + "\t")
			if err := le.encodeAny(sb, c, depth+1); err != nil {
				return err
			}
			sb.WriteString(",\n")
		}
		sb.WriteString(indent + "}")
		return nil
	case MappingNode:
		if len(node.Content) == 0 {
			sb.WriteString("{}")
			return nil
		}
		sb.WriteString("{\n")
		for i := 0; i+1 < len(node.Content); i += 2 {
			sb.WriteString(indent + "\t" + le.formatKey(node.Content[i].Value, le.prefs.UnquotedKeys) + " = ")
			if err := le.encodeAny(sb, node.Content[i+1], depth+1); err != nil {
				return err
			}
			sb.WriteString(";\n")
		}
		sb.WriteString(indent + "}")
		return nil
	case ScalarNode:
		switch node.Tag {
		case "!!str":
			sb.WriteString(luaQuote(node.Value))
		case "!!null":
			sb.WriteString("nil")
		case "!!bool":
			sb.WriteString(strings.ToLower(node.Value))
		case "!!int":
			if strings.HasPrefix(node.Value, "0o") {
				_, v, err := parseInt64(node.Value)
				if err != nil {
					return err
				}
				sb.WriteString(fmt.Sprintf("%v", v))
			} else {
				sb.WriteString(node.Value)
			}
		case "!!float":
			switch strings.ToLower(node.Value) {
			case ".inf", "+.inf":
				sb.WriteString("(1/0)")
			case "-.inf":
				sb.WriteString("(-1/0)")
			case ".nan":
				sb.WriteString("(0/0)")
			default:
				sb.WriteString(node.Value)
			}
		default:
			return fmt.Errorf("lua encoder NYI -- %v", node.Tag)
		}
		return nil
	}
	return fmt.Errorf("lua encoder NYI -- %v", node.Tag)
}

func (le *luaEncoder) Encode(writer io.Writer, node *CandidateNode) error {
	var sb strings.Builder
	if le.prefs.Globals {
		if node.Kind != MappingNode {
			return fmt.Errorf("--lua-global requires a top level MappingNode")
		}
		for i := 0; i+1 < len(node.Content); i += 2 {
			k := node.Content[i].Value
			if luaIsIdent(k) {
				sb.WriteString(k)
			} else {
				sb.WriteString("_ENV[" + luaQuote(k) + "]")
			}
			sb.WriteString(" = ")
			if err := le.encodeAny(&sb, node.Content[i+1], 0); err != nil {
				return err
			}
			sb.WriteString(";\n")
		}
		return writeString(writer, sb.String())
	}
	sb.WriteString(le.prefs.DocPrefix)
	if err := le.encodeAny(&sb, node, 0); err != nil {
		return err
	}
	sb.WriteString(le.prefs.DocSuffix)
	return writeString(writer, sb.String())
}

// ---------------- decoding (minimal lua table parser) -----------------

type luaDecoder struct {
	prefs    LuaPreferences
	src      []rune
	pos      int
	finished bool
}

func NewLuaDecoder(prefs LuaPreferences) Decoder {
	return &luaDecoder{prefs: prefs}
}

func (dec *luaDecoder) Init(reader io.Reader) error {
	data, err := io.ReadAll(reader)
	if err != nil {
		return err
	}
	dec.src = []rune(string(data))
	dec.pos = 0
	dec.finished = false
	return nil
}

type luaValue struct {
	kind  string // nil, bool, number, string, table
	b     bool
	num   float64
	isInt bool
	ival  int64
	str   string
	table *luaTable
}

type luaTable struct {
	arr     []*luaValue
	keys    []*luaValue
	values  map[string]*luaValue
	strKeys []string
	strVals map[string]*luaValue
}

func newLuaTable() *luaTable {
	return &luaTable{values: map[string]*luaValue{}, strVals: map[string]*luaValue{}}
}

func luaKeyString(k *luaValue) string {
	switch k.kind {
	case "number":
		if k.isInt {
			return strconv.FormatInt(k.ival, 10)
		}
		return strconv.FormatFloat(k.num, 'g', -1, 64)
	case "bool":
		return strconv.FormatBool(k.b)
	}
	return k.str
}

func (t *luaTable) set(k *luaValue, v *luaValue) {
	if k.kind == "string" {
		if _, ok := t.strVals[k.str]; !ok {
			t.strKeys = append(t.strKeys, k.str)
		}
		if v.kind == "nil" {
			delete(t.strVals, k.str)
			for i, s := range t.strKeys {
				if s == k.str {
					t.strKeys = append(t.strKeys[:i], t.strKeys[i+1:]...)
					break
				}
			}
			return
		}
		t.strVals[k.str] = v
		return
	}
	if k.kind == "number" && k.isInt && k.ival == int64(len(t.arr))+1 && v.kind != "nil" {
		t.arr = append(t.arr, v)
		// migrate following keys from hash
		for {
			nk := strconv.FormatInt(int64(len(t.arr))+1, 10)
			if nv, ok := t.values[nk]; ok {
				t.arr = append(t.arr, nv)
				delete(t.values, nk)
				for i, kk := range t.keys {
					if luaKeyString(kk) == nk {
						t.keys = append(t.keys[:i], t.keys[i+1:]...)
						break
					}
				}
			} else {
				break
			}
		}
		return
	}
	if k.kind == "number" && k.isInt && k.ival >= 1 && k.ival <= int64(len(t.arr)) {
		if v.kind == "nil" {
			t.arr[k.ival-1] = v
		} else {
			t.arr[k.ival-1] = v
		}
		return
	}
	ks := luaKeyString(k)
	if _, ok := t.values[ks]; !ok {
		t.keys = append(t.keys, k)
	}
	t.values[ks] = v
}

func (dec *luaDecoder) errorf(format string, args ...interface{}) error {
	line := 1
	col := 1
	for i := 0; i < dec.pos && i < len(dec.src); i++ {
		if dec.src[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	return fmt.Errorf("@input line:%d(column:%d) near '%s':   %s", line, col, dec.nearToken(), fmt.Sprintf(format, args...))
}

func (dec *luaDecoder) nearToken() string {
	if dec.pos >= len(dec.src) {
		return "EOF"
	}
	return string(dec.src[dec.pos])
}

func (dec *luaDecoder) skipWS() {
	for dec.pos < len(dec.src) {
		c := dec.src[dec.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			dec.pos++
			continue
		}
		if c == '-' && dec.pos+1 < len(dec.src) && dec.src[dec.pos+1] == '-' {
			dec.pos += 2
			if dec.pos+1 < len(dec.src) && dec.src[dec.pos] == '[' {
				if level := dec.longBracketLevel(); level >= 0 {
					_, _ = dec.readLongString(level)
					continue
				}
			}
			for dec.pos < len(dec.src) && dec.src[dec.pos] != '\n' {
				dec.pos++
			}
			continue
		}
		break
	}
}

func (dec *luaDecoder) longBracketLevel() int {
	if dec.pos >= len(dec.src) || dec.src[dec.pos] != '[' {
		return -1
	}
	j := dec.pos + 1
	level := 0
	for j < len(dec.src) && dec.src[j] == '=' {
		level++
		j++
	}
	if j < len(dec.src) && dec.src[j] == '[' {
		return level
	}
	return -1
}

func (dec *luaDecoder) readLongString(level int) (string, error) {
	dec.pos += level + 2
	if dec.pos < len(dec.src) && dec.src[dec.pos] == '\n' {
		dec.pos++
	}
	closing := "]" + strings.Repeat("=", level) + "]"
	rest := string(dec.src[dec.pos:])
	idx := strings.Index(rest, closing)
	if idx < 0 {
		return "", dec.errorf("unfinished long string")
	}
	s := rest[:idx]
	dec.pos += len([]rune(s)) + len(closing)
	return s, nil
}

func (dec *luaDecoder) readName() string {
	start := dec.pos
	for dec.pos < len(dec.src) {
		c := dec.src[dec.pos]
		if c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9' && dec.pos > start) {
			dec.pos++
		} else {
			break
		}
	}
	return string(dec.src[start:dec.pos])
}

func (dec *luaDecoder) parseString(q rune) (string, error) {
	dec.pos++
	var sb strings.Builder
	for dec.pos < len(dec.src) {
		c := dec.src[dec.pos]
		if c == q {
			dec.pos++
			return sb.String(), nil
		}
		if c == '\n' {
			return "", dec.errorf("unfinished string")
		}
		if c == '\\' {
			dec.pos++
			if dec.pos >= len(dec.src) {
				break
			}
			e := dec.src[dec.pos]
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case 'a':
				sb.WriteByte('\a')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'v':
				sb.WriteByte('\v')
			case '\\', '"', '\'':
				sb.WriteRune(e)
			case '\n':
				sb.WriteByte('\n')
			default:
				if e >= '0' && e <= '9' {
					j := dec.pos
					for j < len(dec.src) && j < dec.pos+3 && dec.src[j] >= '0' && dec.src[j] <= '9' {
						j++
					}
					v, _ := strconv.Atoi(string(dec.src[dec.pos:j]))
					sb.WriteByte(byte(v))
					dec.pos = j
					continue
				}
				sb.WriteRune(e)
			}
			dec.pos++
			continue
		}
		sb.WriteRune(c)
		dec.pos++
	}
	return "", dec.errorf("unfinished string")
}

func (dec *luaDecoder) parseNumber() (*luaValue, error) {
	start := dec.pos
	if dec.pos+1 < len(dec.src) && dec.src[dec.pos] == '0' && (dec.src[dec.pos+1] == 'x' || dec.src[dec.pos+1] == 'X') {
		dec.pos += 2
		for dec.pos < len(dec.src) && strings.ContainsRune("0123456789abcdefABCDEF", dec.src[dec.pos]) {
			dec.pos++
		}
		v, err := strconv.ParseInt(string(dec.src[start+2:dec.pos]), 16, 64)
		if err != nil {
			return nil, dec.errorf("malformed number")
		}
		return &luaValue{kind: "number", isInt: true, ival: v, num: float64(v)}, nil
	}
	for dec.pos < len(dec.src) {
		c := dec.src[dec.pos]
		if (c >= '0' && c <= '9') || c == '.' || c == 'e' || c == 'E' {
			dec.pos++
		} else if (c == '+' || c == '-') && (dec.src[dec.pos-1] == 'e' || dec.src[dec.pos-1] == 'E') {
			dec.pos++
		} else {
			break
		}
	}
	s := string(dec.src[start:dec.pos])
	if !strings.ContainsAny(s, ".eE") {
		v, err := strconv.ParseInt(s, 10, 64)
		if err == nil {
			return &luaValue{kind: "number", isInt: true, ival: v, num: float64(v)}, nil
		}
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return nil, dec.errorf("malformed number")
	}
	if f == math.Trunc(f) && !math.IsInf(f, 0) && math.Abs(f) < 1e18 {
		return &luaValue{kind: "number", isInt: true, ival: int64(f), num: f}, nil
	}
	return &luaValue{kind: "number", num: f}, nil
}

func (dec *luaDecoder) parseSimple() (*luaValue, error) {
	dec.skipWS()
	if dec.pos >= len(dec.src) {
		return nil, dec.errorf("syntax error")
	}
	c := dec.src[dec.pos]
	switch {
	case c == '{':
		return dec.parseTable()
	case c == '"' || c == '\'':
		s, err := dec.parseString(c)
		if err != nil {
			return nil, err
		}
		return &luaValue{kind: "string", str: s}, nil
	case c == '[':
		level := dec.longBracketLevel()
		if level < 0 {
			return nil, dec.errorf("syntax error")
		}
		s, err := dec.readLongString(level)
		if err != nil {
			return nil, err
		}
		return &luaValue{kind: "string", str: s}, nil
	case c == '(':
		dec.pos++
		v, err := dec.parseExpr()
		if err != nil {
			return nil, err
		}
		dec.skipWS()
		if dec.pos >= len(dec.src) || dec.src[dec.pos] != ')' {
			return nil, dec.errorf("syntax error")
		}
		dec.pos++
		return v, nil
	case c == '-':
		dec.pos++
		v, err := dec.parseSimple()
		if err != nil {
			return nil, err
		}
		if v.kind != "number" {
			return nil, dec.errorf("attempt to perform arithmetic on a %v value", v.kind)
		}
		return &luaValue{kind: "number", isInt: v.isInt, ival: -v.ival, num: -v.num}, nil
	case (c >= '0' && c <= '9') || c == '.':
		return dec.parseNumber()
	case c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'):
		name := dec.readName()
		switch name {
		case "nil":
			return &luaValue{kind: "nil"}, nil
		case "true":
			return &luaValue{kind: "bool", b: true}, nil
		case "false":
			return &luaValue{kind: "bool", b: false}, nil
		}
		return &luaValue{kind: "nil"}, nil
	}
	return nil, dec.errorf("syntax error")
}

func luaArith(op rune, a, b *luaValue) *luaValue {
	switch op {
	case '/':
		return &luaValue{kind: "number", num: a.num / b.num}
	case '*':
		if a.isInt && b.isInt {
			return &luaValue{kind: "number", isInt: true, ival: a.ival * b.ival, num: a.num * b.num}
		}
		return &luaValue{kind: "number", num: a.num * b.num}
	case '+':
		if a.isInt && b.isInt {
			return &luaValue{kind: "number", isInt: true, ival: a.ival + b.ival, num: a.num + b.num}
		}
		return &luaValue{kind: "number", num: a.num + b.num}
	case '-':
		if a.isInt && b.isInt {
			return &luaValue{kind: "number", isInt: true, ival: a.ival - b.ival, num: a.num - b.num}
		}
		return &luaValue{kind: "number", num: a.num - b.num}
	}
	return a
}

func (dec *luaDecoder) parseTerm() (*luaValue, error) {
	v, err := dec.parseSimple()
	if err != nil {
		return nil, err
	}
	for {
		dec.skipWS()
		if dec.pos < len(dec.src) && (dec.src[dec.pos] == '*' || dec.src[dec.pos] == '/') {
			op := dec.src[dec.pos]
			dec.pos++
			r, err := dec.parseSimple()
			if err != nil {
				return nil, err
			}
			v = luaArith(op, v, r)
			continue
		}
		return v, nil
	}
}

func (dec *luaDecoder) parseExpr() (*luaValue, error) {
	v, err := dec.parseTerm()
	if err != nil {
		return nil, err
	}
	for {
		dec.skipWS()
		if dec.pos < len(dec.src) && (dec.src[dec.pos] == '+' || (dec.src[dec.pos] == '-' && !(dec.pos+1 < len(dec.src) && dec.src[dec.pos+1] == '-'))) {
			op := dec.src[dec.pos]
			dec.pos++
			r, err := dec.parseTerm()
			if err != nil {
				return nil, err
			}
			v = luaArith(op, v, r)
			continue
		}
		if dec.pos+1 < len(dec.src) && dec.src[dec.pos] == '.' && dec.src[dec.pos+1] == '.' {
			dec.pos += 2
			r, err := dec.parseTerm()
			if err != nil {
				return nil, err
			}
			v = &luaValue{kind: "string", str: luaToString(v) + luaToString(r)}
			continue
		}
		return v, nil
	}
}

func luaToString(v *luaValue) string {
	switch v.kind {
	case "string":
		return v.str
	case "number":
		if v.isInt {
			return strconv.FormatInt(v.ival, 10)
		}
		return strconv.FormatFloat(v.num, 'g', 14, 64)
	}
	return ""
}

func (dec *luaDecoder) parseTable() (*luaValue, error) {
	dec.pos++ // {
	t := newLuaTable()
	arrIdx := int64(1)
	for {
		dec.skipWS()
		if dec.pos >= len(dec.src) {
			return nil, dec.errorf("syntax error")
		}
		if dec.src[dec.pos] == '}' {
			dec.pos++
			return &luaValue{kind: "table", table: t}, nil
		}
		c := dec.src[dec.pos]
		if c == '[' && dec.longBracketLevel() < 0 {
			dec.pos++
			k, err := dec.parseExpr()
			if err != nil {
				return nil, err
			}
			dec.skipWS()
			if dec.pos >= len(dec.src) || dec.src[dec.pos] != ']' {
				return nil, dec.errorf("syntax error")
			}
			dec.pos++
			dec.skipWS()
			if dec.pos >= len(dec.src) || dec.src[dec.pos] != '=' {
				return nil, dec.errorf("syntax error")
			}
			dec.pos++
			v, err := dec.parseExpr()
			if err != nil {
				return nil, err
			}
			t.set(k, v)
		} else if c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
			save := dec.pos
			name := dec.readName()
			dec.skipWS()
			if dec.pos < len(dec.src) && dec.src[dec.pos] == '=' && !(dec.pos+1 < len(dec.src) && dec.src[dec.pos+1] == '=') {
				dec.pos++
				v, err := dec.parseExpr()
				if err != nil {
					return nil, err
				}
				t.set(&luaValue{kind: "string", str: name}, v)
			} else {
				dec.pos = save
				v, err := dec.parseExpr()
				if err != nil {
					return nil, err
				}
				t.set(&luaValue{kind: "number", isInt: true, ival: arrIdx, num: float64(arrIdx)}, v)
				arrIdx++
			}
		} else {
			v, err := dec.parseExpr()
			if err != nil {
				return nil, err
			}
			t.set(&luaValue{kind: "number", isInt: true, ival: arrIdx, num: float64(arrIdx)}, v)
			arrIdx++
		}
		dec.skipWS()
		if dec.pos < len(dec.src) && (dec.src[dec.pos] == ',' || dec.src[dec.pos] == ';') {
			dec.pos++
		}
	}
}

func luaToNode(v *luaValue) *CandidateNode {
	switch v.kind {
	case "nil":
		return createNullScalar()
	case "bool":
		return createBoolScalar(v.b)
	case "string":
		return createStringScalar(v.str)
	case "number":
		if v.isInt {
			return createIntScalar(v.ival)
		}
		switch {
		case math.IsInf(v.num, 1):
			return &CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: ".inf"}
		case math.IsInf(v.num, -1):
			return &CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: "-.inf"}
		case math.IsNaN(v.num):
			return &CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: ".nan"}
		}
		return &CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: strconv.FormatFloat(v.num, 'g', -1, 64)}
	case "table":
		t := v.table
		hasNilInArr := false
		for _, a := range t.arr {
			if a.kind == "nil" {
				hasNilInArr = true
			}
		}
		if len(t.keys) == 0 && len(t.strKeys) == 0 && !hasNilInArr {
			if len(t.arr) == 0 {
				return &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
			}
			seq := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
			for _, a := range t.arr {
				seq.AddChild(luaToNode(a))
			}
			return seq
		}
		m := &CandidateNode{Kind: MappingNode, Tag: "!!map"}
		for i, a := range t.arr {
			if a.kind == "nil" {
				continue
			}
			m.AddKeyValueChild(createIntScalar(int64(i+1)), luaToNode(a))
		}
		for _, k := range t.keys {
			ks := luaKeyString(k)
			var keyNode *CandidateNode
			if k.kind == "number" && k.isInt {
				keyNode = createIntScalar(k.ival)
			} else {
				keyNode = createStringScalar(ks)
			}
			m.AddKeyValueChild(keyNode, luaToNode(t.values[ks]))
		}
		for _, k := range t.strKeys {
			m.AddKeyValueChild(createStringScalar(k), luaToNode(t.strVals[k]))
		}
		return m
	}
	return createNullScalar()
}

func (dec *luaDecoder) Decode() (*CandidateNode, error) {
	if dec.finished {
		return nil, io.EOF
	}
	dec.finished = true
	globals := newLuaTable()
	for {
		dec.skipWS()
		if dec.pos >= len(dec.src) {
			break
		}
		save := dec.pos
		name := dec.readName()
		if name == "" {
			if dec.src[dec.pos] == ';' {
				dec.pos++
				continue
			}
			return nil, dec.errorf("syntax error")
		}
		if name == "return" {
			v, err := dec.parseExpr()
			if err != nil {
				return nil, err
			}
			return luaToNode(v), nil
		}
		if name == "local" {
			continue
		}
		dec.skipWS()
		if dec.pos < len(dec.src) && dec.src[dec.pos] == '=' {
			dec.pos++
			v, err := dec.parseExpr()
			if err != nil {
				return nil, err
			}
			globals.set(&luaValue{kind: "string", str: name}, v)
			continue
		}
		dec.pos = save
		return nil, dec.errorf("syntax error")
	}
	return luaToNode(&luaValue{kind: "table", table: globals}), nil
}
