package main

import (
	"fmt"
	"io"
	"math"
	"regexp"
	"strconv"
	"strings"
)

type HclPreferences struct{}

var ConfiguredHclPreferences = HclPreferences{}

// ---------------- encoding -----------------

type hclEncoder struct{}

func NewHclEncoder(prefs HclPreferences) Encoder { return &hclEncoder{} }

func (he *hclEncoder) CanHandleAliases() bool                                    { return false }
func (he *hclEncoder) PrintDocumentSeparator(writer io.Writer) error             { return nil }
func (he *hclEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }

var hclIdentRegex = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_-]*$`)

func hclKey(k string) string {
	if hclIdentRegex.MatchString(k) {
		return k
	}
	return hclQuote(k)
}

func hclQuote(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 32 {
				sb.WriteString(fmt.Sprintf("\\u%04x", r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func hclIsBlock(n *CandidateNode) bool {
	return n.Kind == MappingNode && n.Style&FlowStyle == 0
}

func (he *hclEncoder) commentLines(sb *strings.Builder, comment string) {
	if comment == "" {
		return
	}
	for _, line := range strings.Split(comment, "\n") {
		if !strings.HasPrefix(strings.TrimSpace(line), "#") && !strings.HasPrefix(strings.TrimSpace(line), "//") {
			line = "# " + line
		}
		sb.WriteString(line + "\n")
	}
}

func (he *hclEncoder) expr(n *CandidateNode) (string, error) {
	switch n.Kind {
	case AliasNode:
		if n.Alias != nil {
			return he.expr(n.Alias)
		}
		return "null", nil
	case ScalarNode:
		tag := n.guessTagFromCustomType()
		switch tag {
		case "!!null":
			return "null", nil
		case "!!str":
			if n.Style&DoubleQuotedStyle != 0 || n.Style&SingleQuotedStyle != 0 || n.Style&LiteralStyle != 0 || n.Style&FoldedStyle != 0 {
				return hclQuote(n.Value), nil
			}
			if strings.Contains(n.Value, "\"") {
				return "", fmt.Errorf("unsupported character '\"' in raw HCL expression")
			}
			return n.Value, nil
		}
		return n.Value, nil
	case SequenceNode:
		parts := make([]string, 0, len(n.Content))
		for _, c := range n.Content {
			e, err := he.expr(c)
			if err != nil {
				return "", err
			}
			parts = append(parts, e)
		}
		return "[" + strings.Join(parts, ", ") + "]", nil
	case MappingNode:
		if len(n.Content) == 0 {
			return "{}", nil
		}
		var sb strings.Builder
		sb.WriteString("{\n")
		for i := 0; i+1 < len(n.Content); i += 2 {
			e, err := he.expr(n.Content[i+1])
			if err != nil {
				return "", err
			}
			sb.WriteString(hclKey(n.Content[i].Value) + " = " + e + "\n")
		}
		sb.WriteString("}")
		return sb.String(), nil
	}
	return "null", nil
}

func (he *hclEncoder) body(sb *strings.Builder, m *CandidateNode) error {
	for i := 0; i+1 < len(m.Content); i += 2 {
		k := m.Content[i]
		v := m.Content[i+1]
		if v.Kind == AliasNode && v.Alias != nil {
			v = v.Alias
		}
		he.commentLines(sb, k.HeadComment)
		if hclIsBlock(v) {
			if err := he.block(sb, k.Value, nil, v); err != nil {
				return err
			}
		} else {
			e, err := he.expr(v)
			if err != nil {
				return err
			}
			sb.WriteString(hclKey(k.Value) + " = " + e + "\n")
		}
	}
	return nil
}

func (he *hclEncoder) block(sb *strings.Builder, blockType string, labels []string, m *CandidateNode) error {
	allBlocks := len(m.Content) > 0
	for i := 1; i < len(m.Content); i += 2 {
		v := m.Content[i]
		if v.Kind == AliasNode && v.Alias != nil {
			v = v.Alias
		}
		if !hclIsBlock(v) {
			allBlocks = false
		}
	}
	if allBlocks {
		for i := 0; i+1 < len(m.Content); i += 2 {
			v := m.Content[i+1]
			if v.Kind == AliasNode && v.Alias != nil {
				v = v.Alias
			}
			newLabels := append(append([]string{}, labels...), m.Content[i].Value)
			if err := he.block(sb, blockType, newLabels, v); err != nil {
				return err
			}
		}
		return nil
	}
	sb.WriteString(hclKey(blockType))
	for _, l := range labels {
		sb.WriteString(" " + hclQuote(l))
	}
	sb.WriteString(" {\n")
	if err := he.body(sb, m); err != nil {
		return err
	}
	sb.WriteString("}\n")
	return nil
}

func hclBracketChange(line string) int {
	net := 0
	inString := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if inString {
			if c == '\\' {
				i++
				continue
			}
			if c == '"' {
				inString = false
			}
			continue
		}
		switch c {
		case '"':
			inString = true
		case '{', '[', '(':
			net++
		case '}', ']', ')':
			net--
		}
	}
	return net
}

func hclFormatIndent(text string) string {
	lines := strings.Split(text, "\n")
	var indents []int
	var out strings.Builder
	for idx, line := range lines {
		line = strings.TrimLeft(line, " ")
		if line == "" {
			if idx < len(lines)-1 {
				out.WriteString("\n")
			}
			continue
		}
		netBrackets := hclBracketChange(line)
		depth := len(indents)
		switch {
		case netBrackets > 0:
			depth = len(indents)
			indents = append(indents, netBrackets)
		case netBrackets < 0:
			closed := -netBrackets
			for closed > 0 && len(indents) > 0 {
				top := indents[len(indents)-1]
				switch {
				case closed > top:
					closed -= top
					indents = indents[:len(indents)-1]
				case closed < top:
					indents[len(indents)-1] -= closed
					closed = 0
				default:
					indents = indents[:len(indents)-1]
					closed = 0
				}
			}
			depth = len(indents)
		}
		out.WriteString(strings.Repeat("  ", depth) + line)
		if idx < len(lines)-1 {
			out.WriteString("\n")
		}
	}
	return out.String()
}

func (he *hclEncoder) Encode(writer io.Writer, node *CandidateNode) error {
	if node.Kind == ScalarNode {
		return writeString(writer, node.Value+"\n")
	}
	if node.Kind != MappingNode {
		kindName := "SequenceNode"
		if node.Kind == AliasNode {
			kindName = "AliasNode"
		}
		return fmt.Errorf("failed to encode HCL: HCL encoder expects a mapping at the root level, got %v", kindName)
	}
	var sb strings.Builder
	he.commentLines(&sb, node.HeadComment)
	if err := he.body(&sb, node); err != nil {
		return fmt.Errorf("failed to encode HCL: %w", err)
	}
	return writeString(writer, hclFormatIndent(sb.String()))
}

// ---------------- decoding -----------------

type hclDecoder struct {
	src      []rune
	pos      int
	finished bool
}

func NewHclDecoder() Decoder { return &hclDecoder{} }

func (dec *hclDecoder) Init(reader io.Reader) error {
	data, err := io.ReadAll(reader)
	if err != nil {
		return err
	}
	dec.src = []rune(string(data))
	dec.pos = 0
	dec.finished = false
	return nil
}

func (dec *hclDecoder) eof() bool { return dec.pos >= len(dec.src) }
func (dec *hclDecoder) peek() rune {
	if dec.eof() {
		return 0
	}
	return dec.src[dec.pos]
}
func (dec *hclDecoder) peekAt(o int) rune {
	if dec.pos+o >= len(dec.src) {
		return 0
	}
	return dec.src[dec.pos+o]
}

func (dec *hclDecoder) lineCol() (int, int) {
	line, col := 1, 1
	for i := 0; i < dec.pos && i < len(dec.src); i++ {
		if dec.src[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	return line, col
}

func (dec *hclDecoder) errorf(summary string, detail string) error {
	line, col := dec.lineCol()
	return fmt.Errorf("hcl parse error: input.hcl:%d,%d-%d: %s; %s", line, col, col+1, summary, detail)
}

// skips spaces and comments (not newlines); returns collected comments
func (dec *hclDecoder) skipInline() []string {
	var comments []string
	for !dec.eof() {
		c := dec.peek()
		if c == ' ' || c == '\t' || c == '\r' {
			dec.pos++
		} else if c == '#' || (c == '/' && dec.peekAt(1) == '/') {
			start := dec.pos
			for !dec.eof() && dec.peek() != '\n' {
				dec.pos++
			}
			comments = append(comments, string(dec.src[start:dec.pos]))
		} else if c == '/' && dec.peekAt(1) == '*' {
			start := dec.pos
			dec.pos += 2
			for !dec.eof() && !(dec.peek() == '*' && dec.peekAt(1) == '/') {
				dec.pos++
			}
			dec.pos += 2
			comments = append(comments, string(dec.src[start:min(dec.pos, len(dec.src))]))
		} else {
			break
		}
	}
	return comments
}

func (dec *hclDecoder) skipAll() []string {
	var comments []string
	for !dec.eof() {
		c := dec.skipInline()
		comments = append(comments, c...)
		if dec.peek() == '\n' {
			dec.pos++
			continue
		}
		break
	}
	return comments
}

func isHclIdentStart(r rune) bool {
	return r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}
func isHclIdentChar(r rune) bool {
	return isHclIdentStart(r) || (r >= '0' && r <= '9') || r == '-'
}

func (dec *hclDecoder) readIdent() string {
	start := dec.pos
	for !dec.eof() && isHclIdentChar(dec.peek()) {
		dec.pos++
	}
	return string(dec.src[start:dec.pos])
}

func hclCommentToYaml(comments []string) string {
	var lines []string
	for _, c := range comments {
		c = strings.TrimSpace(c)
		if strings.HasPrefix(c, "//") {
			continue
		}
		if strings.HasPrefix(c, "/*") {
			continue
		}
		lines = append(lines, c)
	}
	return strings.Join(lines, "\n")
}

type hclVal struct {
	node *CandidateNode
	raw  bool // couldn't evaluate
}

func (dec *hclDecoder) parseString() (string, bool, error) {
	// returns string value and whether it is a template with interpolation
	dec.pos++ // "
	var sb strings.Builder
	isTemplate := false
	for !dec.eof() {
		c := dec.peek()
		if c == '"' {
			dec.pos++
			return sb.String(), isTemplate, nil
		}
		if c == '\n' {
			return "", false, dec.errorf("Unterminated template string", "No closing marker was found for the string.")
		}
		if c == '\\' {
			dec.pos++
			e := dec.peek()
			dec.pos++
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case 'u', 'U':
				n := 4
				if e == 'U' {
					n = 8
				}
				if dec.pos+n <= len(dec.src) {
					v, err := strconv.ParseUint(string(dec.src[dec.pos:dec.pos+n]), 16, 32)
					if err == nil {
						sb.WriteRune(rune(v))
						dec.pos += n
						continue
					}
				}
				sb.WriteRune(e)
			default:
				sb.WriteByte('\\')
				sb.WriteRune(e)
			}
			continue
		}
		if (c == '$' || c == '%') && dec.peekAt(1) == '{' {
			if c == '$' && dec.peekAt(2) == '{' {
				// escaped
			}
			isTemplate = true
			depth := 0
			for !dec.eof() {
				ch := dec.peek()
				sb.WriteRune(ch)
				dec.pos++
				if ch == '{' {
					depth++
				} else if ch == '}' {
					depth--
					if depth == 0 {
						break
					}
				}
			}
			continue
		}
		sb.WriteRune(c)
		dec.pos++
	}
	return "", false, dec.errorf("Unterminated template string", "No closing marker was found for the string.")
}

func (dec *hclDecoder) parseHeredoc() (string, error) {
	// at <<
	dec.pos += 2
	indent := false
	if dec.peek() == '-' {
		indent = true
		dec.pos++
	}
	marker := dec.readIdent()
	for !dec.eof() && dec.peek() != '\n' {
		dec.pos++
	}
	dec.pos++
	var lines []string
	for !dec.eof() {
		start := dec.pos
		for !dec.eof() && dec.peek() != '\n' {
			dec.pos++
		}
		line := string(dec.src[start:dec.pos])
		if !dec.eof() {
			dec.pos++
		}
		if strings.TrimSpace(line) == marker {
			break
		}
		lines = append(lines, line)
	}
	if indent {
		minIndent := -1
		for _, l := range lines {
			if strings.TrimSpace(l) == "" {
				continue
			}
			n := len(l) - len(strings.TrimLeft(l, " \t"))
			if minIndent < 0 || n < minIndent {
				minIndent = n
			}
		}
		if minIndent > 0 {
			for i, l := range lines {
				if len(l) >= minIndent {
					lines[i] = l[minIndent:]
				}
			}
		}
	}
	if len(lines) == 0 {
		return "", nil
	}
	return strings.Join(lines, "\n") + "\n", nil
}

func hclNumberNode(f float64, raw string) *CandidateNode {
	if f == math.Trunc(f) && math.Abs(f) < 1e18 && !strings.ContainsAny(raw, ".eE") {
		return &CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: strconv.FormatInt(int64(f), 10)}
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e18 {
		return &CandidateNode{Kind: ScalarNode, Tag: "!!int", Value: strconv.FormatInt(int64(f), 10)}
	}
	return &CandidateNode{Kind: ScalarNode, Tag: "!!float", Value: strconv.FormatFloat(f, 'f', -1, 64)}
}

func hclNumeric(n *CandidateNode) (float64, bool) {
	if n == nil || n.Kind != ScalarNode {
		return 0, false
	}
	if n.Tag != "!!int" && n.Tag != "!!float" {
		return 0, false
	}
	f, err := strconv.ParseFloat(n.Value, 64)
	return f, err == nil
}

// parsePrimary parses a primary expression; returns value node (nil if unevaluable)
func (dec *hclDecoder) parsePrimary() (*CandidateNode, error) {
	dec.skipInline()
	if dec.eof() {
		return nil, dec.errorf("Invalid expression", "Expected the start of an expression, but found the end of the file.")
	}
	c := dec.peek()
	switch {
	case c == '"':
		s, isTemplate, err := dec.parseString()
		if err != nil {
			return nil, err
		}
		_ = isTemplate
		return &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: s, Style: DoubleQuotedStyle}, nil
	case c == '<' && dec.peekAt(1) == '<':
		s, err := dec.parseHeredoc()
		if err != nil {
			return nil, err
		}
		return &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: s, Style: DoubleQuotedStyle}, nil
	case c == '[':
		dec.pos++
		dec.skipAll()
		if dec.peek() == 'f' && strings.HasPrefix(string(dec.src[dec.pos:min(dec.pos+4, len(dec.src))]), "for ") {
			return dec.parseForList()
		}
		seq := &CandidateNode{Kind: SequenceNode, Tag: "!!seq"}
		evaluable := true
		for {
			dec.skipAll()
			if dec.peek() == ']' {
				dec.pos++
				break
			}
			v, err := dec.parseExpr()
			if err != nil {
				return nil, err
			}
			if v == nil {
				evaluable = false
			} else {
				seq.AddChild(v)
			}
			dec.skipAll()
			if dec.peek() == ',' {
				dec.pos++
				continue
			}
			dec.skipAll()
			if dec.peek() == ']' {
				dec.pos++
				break
			}
			return nil, dec.errorf("Missing item separator", "Expected a comma to mark the beginning of the next item.")
		}
		if !evaluable {
			return nil, nil
		}
		return seq, nil
	case c == '{':
		dec.pos++
		m := &CandidateNode{Kind: MappingNode, Tag: "!!map", Style: FlowStyle}
		for {
			dec.skipAll()
			if dec.peek() == '}' {
				dec.pos++
				break
			}
			var key string
			if dec.peek() == '"' {
				s, _, err := dec.parseString()
				if err != nil {
					return nil, err
				}
				key = s
			} else if isHclIdentStart(dec.peek()) {
				key = dec.readIdent()
			} else {
				return nil, dec.errorf("Invalid object key", "Expected an object key.")
			}
			dec.skipInline()
			if dec.peek() != '=' && dec.peek() != ':' {
				return nil, dec.errorf("Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value.")
			}
			dec.pos++
			v, err := dec.parseExpr()
			if err != nil {
				return nil, err
			}
			if v == nil {
				v = createNullScalar()
			}
			m.AddKeyValueChild(createStringScalar(key), v)
			dec.skipInline()
			if dec.peek() == ',' {
				dec.pos++
			}
		}
		return m, nil
	case c == '(':
		dec.pos++
		v, err := dec.parseExpr()
		if err != nil {
			return nil, err
		}
		dec.skipAll()
		if dec.peek() == ')' {
			dec.pos++
		}
		return v, nil
	case c == '-' || c == '!':
		dec.pos++
		v, err := dec.parsePrimary()
		if err != nil || v == nil {
			return nil, err
		}
		if c == '!' {
			if v.Tag == "!!bool" {
				return createBoolScalar(v.Value != "true"), nil
			}
			return nil, nil
		}
		if f, ok := hclNumeric(v); ok {
			return hclNumberNode(-f, v.Value), nil
		}
		return nil, nil
	case c >= '0' && c <= '9':
		start := dec.pos
		for !dec.eof() {
			ch := dec.peek()
			if (ch >= '0' && ch <= '9') || ch == '.' || ch == 'e' || ch == 'E' {
				dec.pos++
			} else if (ch == '+' || ch == '-') && (dec.src[dec.pos-1] == 'e' || dec.src[dec.pos-1] == 'E') {
				dec.pos++
			} else {
				break
			}
		}
		raw := string(dec.src[start:dec.pos])
		f, err := strconv.ParseFloat(raw, 64)
		if err != nil {
			return nil, dec.errorf("Invalid number literal", "Failed to recognize the value of this number literal.")
		}
		return hclNumberNode(f, raw), nil
	case isHclIdentStart(c):
		ident := dec.readIdent()
		switch ident {
		case "true", "false":
			return &CandidateNode{Kind: ScalarNode, Tag: "!!bool", Value: ident}, nil
		case "null":
			return &CandidateNode{Kind: ScalarNode, Tag: "!!null", Value: ""}, nil
		}
		// traversal or function call
		if dec.peek() == '(' {
			depth := 0
			for !dec.eof() {
				ch := dec.peek()
				dec.pos++
				if ch == '(' {
					depth++
				} else if ch == ')' {
					depth--
					if depth == 0 {
						break
					}
				} else if ch == '"' {
					for !dec.eof() && dec.peek() != '"' {
						if dec.peek() == '\\' {
							dec.pos++
						}
						dec.pos++
					}
					dec.pos++
				}
			}
			return nil, nil
		}
		for !dec.eof() && (dec.peek() == '.' || dec.peek() == '[') {
			if dec.peek() == '.' {
				dec.pos++
				dec.readIdent()
				if dec.peek() == '*' {
					dec.pos++
				}
			} else {
				for !dec.eof() && dec.peek() != ']' {
					dec.pos++
				}
				dec.pos++
			}
		}
		return nil, nil
	}
	return nil, dec.errorf("Invalid expression", "Expected the start of an expression, but found an invalid expression token.")
}

func (dec *hclDecoder) parseForList() (*CandidateNode, error) {
	// [for x in LIST : EXPR] - only supports identity-ish evaluation of literal lists
	start := dec.pos
	depth := 1
	for !dec.eof() && depth > 0 {
		ch := dec.peek()
		if ch == '[' {
			depth++
		} else if ch == ']' {
			depth--
			if depth == 0 {
				break
			}
		}
		dec.pos++
	}
	body := string(dec.src[start:dec.pos])
	dec.pos++
	re := regexp.MustCompile(`^for\s+(\w+)\s+in\s+(.*?)\s*:\s*(\w+)\s*$`)
	m := re.FindStringSubmatch(body)
	if m == nil || m[1] != m[3] {
		return nil, nil
	}
	sub := &hclDecoder{src: []rune(m[2])}
	v, err := sub.parseExpr()
	if err != nil || v == nil {
		return nil, nil
	}
	return v, nil
}

func hclPrecedence(op string) int {
	switch op {
	case "||":
		return 1
	case "&&":
		return 2
	case "==", "!=":
		return 3
	case "<", ">", "<=", ">=":
		return 4
	case "+", "-":
		return 5
	case "*", "/", "%":
		return 6
	}
	return 0
}

func (dec *hclDecoder) readOperator() string {
	dec.skipInline()
	if dec.eof() {
		return ""
	}
	two := string(dec.src[dec.pos:min(dec.pos+2, len(dec.src))])
	switch two {
	case "||", "&&", "==", "!=", "<=", ">=":
		return two
	}
	c := dec.peek()
	switch c {
	case '+', '-', '*', '/', '%', '<', '>':
		return string(c)
	}
	return ""
}

func hclApply(op string, a, b *CandidateNode) *CandidateNode {
	if a == nil || b == nil {
		return nil
	}
	switch op {
	case "+", "-", "*", "/", "%":
		fa, oka := hclNumeric(a)
		fb, okb := hclNumeric(b)
		if !oka || !okb {
			return nil
		}
		var r float64
		switch op {
		case "+":
			r = fa + fb
		case "-":
			r = fa - fb
		case "*":
			r = fa * fb
		case "/":
			r = fa / fb
		case "%":
			r = math.Mod(fa, fb)
		}
		return hclNumberNode(r, "")
	case "==", "!=":
		eq := a.Kind == ScalarNode && b.Kind == ScalarNode && a.Value == b.Value && a.Tag == b.Tag
		if op == "!=" {
			eq = !eq
		}
		return createBoolScalar(eq)
	case "<", ">", "<=", ">=":
		fa, oka := hclNumeric(a)
		fb, okb := hclNumeric(b)
		if !oka || !okb {
			return nil
		}
		var r bool
		switch op {
		case "<":
			r = fa < fb
		case ">":
			r = fa > fb
		case "<=":
			r = fa <= fb
		case ">=":
			r = fa >= fb
		}
		return createBoolScalar(r)
	case "&&", "||":
		if a.Tag != "!!bool" || b.Tag != "!!bool" {
			return nil
		}
		if op == "&&" {
			return createBoolScalar(a.Value == "true" && b.Value == "true")
		}
		return createBoolScalar(a.Value == "true" || b.Value == "true")
	}
	return nil
}

func (dec *hclDecoder) parseBinary(minPrec int) (*CandidateNode, bool, error) {
	lhs, err := dec.parsePrimary()
	if err != nil {
		return nil, false, err
	}
	unevaluable := lhs == nil
	for {
		op := dec.readOperator()
		prec := hclPrecedence(op)
		if op == "" || prec < minPrec {
			return lhs, unevaluable, nil
		}
		dec.pos += len(op)
		rhs, ru, err := dec.parseBinary(prec + 1)
		if err != nil {
			return nil, false, err
		}
		if ru {
			unevaluable = true
		}
		lhs = hclApply(op, lhs, rhs)
		if lhs == nil {
			unevaluable = true
		}
	}
}

func (dec *hclDecoder) parseExpr() (*CandidateNode, error) {
	dec.skipInline()
	start := dec.pos
	v, unevaluable, err := dec.parseBinary(1)
	if err != nil {
		return nil, err
	}
	dec.skipInline()
	if dec.peek() == '?' {
		dec.pos++
		if _, err := dec.parseExpr(); err != nil {
			return nil, err
		}
		dec.skipInline()
		if dec.peek() == ':' {
			dec.pos++
		}
		if _, err := dec.parseExpr(); err != nil {
			return nil, err
		}
		unevaluable = true
	}
	if unevaluable || v == nil {
		raw := strings.TrimSpace(string(dec.src[start:dec.pos]))
		return &CandidateNode{Kind: ScalarNode, Tag: "!!str", Value: raw}, nil
	}
	return v, nil
}

func hclMergeBlock(parent *CandidateNode, keys []string, body *CandidateNode) {
	target := parent
	for _, k := range keys {
		var found *CandidateNode
		for i := 0; i+1 < len(target.Content); i += 2 {
			if target.Content[i].Value == k && target.Content[i+1].Kind == MappingNode {
				found = target.Content[i+1]
			}
		}
		if found == nil {
			found = &CandidateNode{Kind: MappingNode, Tag: "!!map"}
			_, found = target.AddKeyValueChild(createStringScalar(k), found)
		}
		target = found
	}
	for i := 0; i+1 < len(body.Content); i += 2 {
		target.AddKeyValueChild(body.Content[i], body.Content[i+1])
	}
}

func (dec *hclDecoder) parseBody(closing bool) (*CandidateNode, error) {
	m := &CandidateNode{Kind: MappingNode, Tag: "!!map"}
	first := true
	for {
		comments := dec.skipAll()
		if dec.eof() {
			if closing {
				return nil, dec.errorf("Unclosed configuration block", "There is no closing brace for this block before the end of the file.")
			}
			if first && len(comments) > 0 {
				m.HeadComment = hclCommentToYaml(comments)
			}
			return m, nil
		}
		if closing && dec.peek() == '}' {
			dec.pos++
			return m, nil
		}
		if !isHclIdentStart(dec.peek()) {
			return nil, dec.errorf("Argument or block definition required", "An argument or block definition is required here.")
		}
		name := dec.readIdent()
		dec.skipInline()
		if dec.peek() == '=' && dec.peekAt(1) != '=' {
			dec.pos++
			v, err := dec.parseExpr()
			if err != nil {
				return nil, err
			}
			lc := dec.skipInline()
			keyNode := createStringScalar(name)
			if len(comments) > 0 {
				hc := hclCommentToYaml(comments)
				if first && !closing {
					m.HeadComment = hc
				} else {
					keyNode.HeadComment = hc
				}
			}
			if len(lc) > 0 {
				v.LineComment = hclCommentToYaml(lc)
			}
			m.AddKeyValueChild(keyNode, v)
		} else {
			var labels []string
			for {
				dec.skipInline()
				if dec.peek() == '"' {
					s, _, err := dec.parseString()
					if err != nil {
						return nil, err
					}
					labels = append(labels, s)
				} else if isHclIdentStart(dec.peek()) {
					labels = append(labels, dec.readIdent())
				} else {
					break
				}
			}
			dec.skipInline()
			if dec.peek() != '{' {
				return nil, dec.errorf("Invalid block definition", "Either a quoted string block label or an opening brace (\"{\") is expected here.")
			}
			dec.pos++
			body, err := dec.parseBody(true)
			if err != nil {
				return nil, err
			}
			if first && !closing && len(comments) > 0 {
				m.HeadComment = hclCommentToYaml(comments)
			}
			hclMergeBlock(m, append([]string{name}, labels...), body)
		}
		first = false
	}
}

func (dec *hclDecoder) Decode() (*CandidateNode, error) {
	if dec.finished {
		return nil, io.EOF
	}
	dec.finished = true
	root, err := dec.parseBody(false)
	if err != nil {
		return nil, err
	}
	return root, nil
}
