	if regexp.MustCompile(`^[-+]?0[0-7]+$`).MatchString(v) {
		return -1
	}
	if regexp.MustCompile(`^[-+]?\.(inf|Inf|INF)$`).MatchString(v) || regexp.MustCompile(`^\.(nan|NaN|NAN)$`).MatchString(v) {
		return -1
	}
	return colorFgGreen
}

func tokenizeForColor(src string) []ctok {
	var tokens []ctok
	pending := ""
	flowDepth := 0
	i := 0
	n := len(src)
	lineStart := 0
	lineIndent := func(pos int) int {
		// indentation of the line containing pos
		start := strings.LastIndex(src[:pos], "\n") + 1
		j := start
		for j < n && src[j] == ' ' {
			j++
		}
		return j - start
	}
	emit := func(kind ctokKind, text string) {
		tokens = append(tokens, ctok{kind: kind, origin: pending + text, text: text})
		pending = ""
	}
	isWS := func(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' }
	for i < n {
		c := src[i]
		if isWS(c) {
			pending += string(c)
			if c == '\n' {
				lineStart = i + 1
			}
			i++
			continue
		}
		_ = lineStart
		prevIsWS := i == 0 || isWS(src[i-1])
		switch {
		case c == '#' && prevIsWS:
			j := i
			for j < n && src[j] != '\n' {
				j++
			}
			if j < n {
				j++
			}
			emit(ckComment, src[i:j])
			i = j
			continue
		case c == '-' && flowDepth == 0 && (i+1 >= n || isWS(src[i+1])):
			emit(ckIndicator, "-")
			i++
			continue
		case c == ':' && (i+1 >= n || isWS(src[i+1]) || (flowDepth > 0 && strings.ContainsRune(",]}", rune(src[i+1])))):
			emit(ckMappingValue, ":")
			i++
			continue
		case c == '[' || c == '{':
			flowDepth++
			emit(ckIndicator, string(c))
			i++
			continue
		case c == ']' || c == '}':
			if flowDepth > 0 {
				flowDepth--
			}
			emit(ckIndicator, string(c))
			i++
			continue
		case c == ',' && flowDepth > 0:
			emit(ckIndicator, ",")
			i++
			continue
		case c == '!':
			j := i
			for j < n && !isWS(src[j]) {
				j++
			}
			k := j
			for k < n && (src[k] == ' ' || src[k] == '\t') {
				k++
			}
			emit(ckTag, src[i:k])
			i = k
			continue
		case c == '&' || c == '*':
			if c == '&' {
				emit(ckAnchor, "&")
			} else {
				emit(ckAlias, "*")
			}
			j := i + 1
			for j < n && !isWS(src[j]) && !(flowDepth > 0 && strings.ContainsRune(",]}", rune(src[j]))) {
				j++
			}
			emit(ckPlain, src[i+1:j])
			tokens[len(tokens)-1].kind = ckPlain
			i = j
			continue
		case (c == '|' || c == '>') && flowDepth == 0:
			indent := lineIndent(i)
			j := i
			for j < n && src[j] != '\n' {
				j++
			}
			if j < n {
				j++
			}
			emit(ckIndicator, src[i:j])
			i = j
			// block content
			k := i
			for k < n {
				le := strings.IndexByte(src[k:], '\n')
				var line string
				if le < 0 {
					line = src[k:]
				} else {
					line = src[k : k+le+1]
				}
				trimmed := strings.TrimLeft(line, " ")
				if strings.TrimSpace(line) != "" && len(line)-len(trimmed) <= indent {
					break
				}
				k += len(line)
			}
			if k > i {
				emit(ckBlockContent, src[i:k])
			}
			i = k
			continue
		case c == '"' || c == '\'':
			j := i + 1
			for j < n {
				if c == '"' && src[j] == '\\' {
					j += 2
					continue
				}
				if src[j] == c {
					if c == '\'' && j+1 < n && src[j+1] == '\'' {
						j += 2
						continue
					}
					break
				}
				j++
			}
			if j < n {
				j++
			}
			emit(ckQuoted, src[i:j])
			i = j
			continue
		}
		// plain scalar
		j := i
		for j < n {
			ch := src[j]
			if ch == '\n' {
				break
			}
			if ch == ':' && (j+1 >= n || isWS(src[j+1]) || (flowDepth > 0 && strings.ContainsRune(",]}", rune(src[j+1])))) {
				break
			}
			if ch == '#' && j > i && isWS(src[j-1]) {
				break
			}
			if flowDepth > 0 && strings.ContainsRune(",]}", rune(ch)) {
				break
			}
			j++
		}
		text := src[i:j]
		trimmedText := strings.TrimRight(text, " \t")
		// absorb trailing whitespace (including newlines) unless followed by ':'
		k := i + len(trimmedText)
		if !(k < n && src[k] == ':') {
			for k < n && isWS(src[k]) {
				k++
			}
		}
		absorbed := src[i:k]
		if k >= n {
			absorbed = strings.TrimRight(absorbed, " \t\r\n")
		}
		tokens = append(tokens, ctok{kind: ckPlain, origin: pending + absorbed, text: trimmedText})
		pending = ""
		i = k
	}
	return tokens
}

func colorizeText(src string) string {
	tokens := tokenizeForColor(src)
	var sb strings.Builder
	for idx, tk := range tokens {
		color := -1
		var prevKind ctokKind = -1
		if idx > 0 {
			prevKind = tokens[idx-1].kind
		}
		nextIsMapValue := idx+1 < len(tokens) && tokens[idx+1].kind == ckMappingValue
		switch {
		case prevKind == ckAnchor || prevKind == ckAlias:
			color = colorFgHiYellow
		case nextIsMapValue:
			color = colorFgCyan
		default:
			switch tk.kind {
			case ckAnchor, ckAlias:
				color = colorFgHiYellow
			case ckQuoted, ckBlockContent:
				color = colorFgGreen
			case ckComment:
				color = colorFgHiBlack
			case ckPlain:
				color = classifyPlainColor(tk.text)
			}
		}
		lines := strings.Split(tk.origin, "\n")
		for li, line := range lines {
			if li > 0 {
				sb.WriteString("\n")
			}
			if color >= 0 {
				sb.WriteString(colorFormat(color) + line + colorFormat(colorReset))
			} else {
				sb.WriteString(line)
			}
		}
	}
	return sb.String()
}

func colorizeAndPrint(yamlBytes []byte, writer io.Writer) error {
	_, err := writer.Write([]byte(colorizeText(string(yamlBytes)) + "\n"))
	return err
}

func colorizeJSON(s string, indent int) string {
	return colorizeText(s) + "\n"
}
